package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CountDownLatch;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** The append-only, bounded, file-backed outbox (#656). */
public class EventOutboxTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private EventOutbox outboxIn(File file) {
    return new EventOutbox(file, new Gson());
  }

  private File newFile() throws IOException {
    return new File(folder.newFolder("bankstand"), "events.json");
  }

  private TransientEvent event(String id) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("itemName", "Dragon warhammer");
    return new TransientEvent(id, TransientEvent.TYPE_NOTABLE_DROP, "2026-08-10T10:00:00Z", payload);
  }

  @Test
  public void roundTripsPendingEntries() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(123L, event("a"));
    outbox.add(123L, event("b"));

    List<OutboxEntry> reloaded = outboxIn(file).pending();

    assertEquals(2, reloaded.size());
    assertEquals("a", reloaded.get(0).getEvent().getId());
    assertEquals("b", reloaded.get(1).getEvent().getId());
    assertEquals(123L, reloaded.get(0).getAccountHash());
  }

  @Test
  public void readsAsEmptyWhenNothingWasEverWritten() throws IOException {
    assertTrue(outboxIn(newFile()).pending().isEmpty());
  }

  @Test
  public void ackRemovesExactlyTheMatchingEntriesAndLeavesTheRestInOrder() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(1L, event("a"));
    outbox.add(1L, event("b"));
    outbox.add(1L, event("c"));

    outbox.ack(EventOutbox.toIdSet(Collections.singletonList("b")));

    List<OutboxEntry> remaining = outbox.pending();
    assertEquals(2, remaining.size());
    assertEquals("a", remaining.get(0).getEvent().getId());
    assertEquals("c", remaining.get(1).getEvent().getId());
  }

  @Test
  public void ackWithNoMatchesChangesNothing() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(1L, event("a"));

    outbox.ack(EventOutbox.toIdSet(Collections.singletonList("not-present")));

    assertEquals(1, outbox.pending().size());
  }

  @Test
  public void clearForgetsEveryPendingEvent() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    outbox.add(1L, event("a"));
    outbox.add(2L, event("b"));

    outbox.clear();

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void overflowingTheCapDropsTheOldestEntryAndKeepsTheRest() throws IOException {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    for (int i = 0; i < EventOutbox.MAX_PENDING; i++) {
      outbox.add(1L, event("id-" + i));
    }
    // One more than the cap.
    outbox.add(1L, event("overflow"));

    List<OutboxEntry> pending = outbox.pending();
    assertEquals(EventOutbox.MAX_PENDING, pending.size());
    // The very first entry ("id-0") was the oldest and must be the one dropped.
    assertEquals("id-1", pending.get(0).getEvent().getId());
    assertEquals("overflow", pending.get(pending.size() - 1).getEvent().getId());
  }

  @Test
  public void readingACorruptFileResolvesToEmptyRatherThanThrowing() throws IOException {
    File file = newFile();
    java.nio.file.Files.write(file.toPath(), "not json".getBytes(java.nio.charset.StandardCharsets.UTF_8));

    assertTrue(outboxIn(file).pending().isEmpty());
  }

  /**
   * Reproduces the torn read-modify-write the plugin's own real wiring exposes:
   * {@code add} runs on the client thread from a capture's {@code @Subscribe}
   * handler, {@code ack} runs off it from the drain's executor continuation. Both
   * do an independent read-mutate-write against the same file. {@code ack} here
   * never matches anything, so every add it does not itself remove must survive.
   * Fails on an unsynchronized {@code EventOutbox}: some adds land between a
   * concurrent ack's read and its write and are silently overwritten.
   */
  @Test
  public void concurrentAddAndAckDoNotLoseEntries() throws Exception {
    File file = newFile();
    EventOutbox outbox = outboxIn(file);
    int iterations = 150; // below MAX_PENDING, so no drop-oldest eviction is expected
    Set<String> neverMatches = EventOutbox.toIdSet(Collections.singletonList("no-such-id"));
    CountDownLatch ready = new CountDownLatch(2);
    CountDownLatch go = new CountDownLatch(1);

    Thread adder =
        new Thread(
            () -> {
              ready.countDown();
              awaitUninterruptibly(go);
              for (int i = 0; i < iterations; i++) {
                outbox.add(1L, event("id-" + i));
              }
            });
    Thread acker =
        new Thread(
            () -> {
              ready.countDown();
              awaitUninterruptibly(go);
              for (int i = 0; i < iterations; i++) {
                outbox.ack(neverMatches);
              }
            });

    adder.start();
    acker.start();
    ready.await();
    go.countDown();
    adder.join(30_000);
    acker.join(30_000);

    assertEquals(iterations, outbox.pending().size());
  }

  private static void awaitUninterruptibly(CountDownLatch latch) {
    try {
      latch.await();
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class CapabilityManifestTest {

  private static CapabilityManifest.RawManifest parse(String json) {
    return new Gson().fromJson(json, CapabilityManifest.RawManifest.class);
  }

  @Test
  public void cannotExpressAnythingButPrimitives() {
    // **The whole guarantee, asserted rather than described.** A Plugin Hub reviewer's
    // question is whether a compromised server could make this plugin read a bank, an
    // inventory, chat or a location. It cannot, because the wire type has no field that
    // could carry a varbit, a script, a widget, a URL, a class name or an expression.
    // This fails the moment somebody adds one.
    for (Field field : CapabilityManifest.RawManifest.class.getDeclaredFields()) {
      if (field.isSynthetic()) {
        continue;
      }
      Type type = field.getGenericType();
      boolean ok;
      if (type == int.class || type == long.class || type == boolean.class || type == String.class) {
        ok = true;
      } else if (type instanceof ParameterizedType) {
        ParameterizedType p = (ParameterizedType) type;
        // The one container allowed, and only of strings.
        ok = p.getRawType() == List.class && p.getActualTypeArguments()[0] == String.class;
      } else {
        ok = false;
      }
      assertTrue(
          "RawManifest." + field.getName() + " is not a primitive the contract allows: " + type,
          ok);
    }
  }

  @Test
  public void acceptsAWellFormedManifest() {
    CapabilityManifest m =
        CapabilityManifest.validate(
            parse(
                "{\"schemaVersion\":1,\"minPluginVersion\":\"0.1.0\","
                    + "\"capabilities\":[\"skills\",\"diaries\"],\"uploadIntervalSeconds\":300}"));
    assertEquals(Arrays.asList("skills", "diaries"), m.capabilities());
    assertEquals(300, m.uploadIntervalSeconds());
    assertTrue(m.allows("skills"));
    assertFalse(m.allows("quests"));
  }

  @Test
  public void rejectsAWholeManifestOnAnUnknownSchemaVersion() {
    // The version gates the document, not a field. A manifest written against a contract
    // this build does not speak cannot be partly understood, and honouring the parts that
    // look familiar is how a client ends up applying half of something.
    assertNull(
        CapabilityManifest.validate(
            parse("{\"schemaVersion\":2,\"capabilities\":[\"skills\"],\"uploadIntervalSeconds\":300}")));
    assertNull(
        CapabilityManifest.validate(
            parse("{\"capabilities\":[\"skills\"],\"uploadIntervalSeconds\":300}")));
  }

  @Test
  public void dropsAnUnknownCapabilityAndKeepsTheRest() {
    // Deliberately the opposite of the version gate. A new capability is an additive
    // change the server is entitled to make, and rejecting the whole manifest over one
    // would mean no capability could ever be introduced without stranding older clients.
    CapabilityManifest m =
        CapabilityManifest.validate(
            parse(
                "{\"schemaVersion\":1,\"capabilities\":[\"skills\",\"bankValue\",\"quests\"],"
                    + "\"uploadIntervalSeconds\":300}"));
    assertEquals(Arrays.asList("skills", "quests"), m.capabilities());
    assertFalse(m.allows("bankValue"));
  }

  @Test
  public void refusesTheCapabilitiesTheProductPromisedNeverToTake() {
    // Named explicitly because these are the ones the product states it will not capture.
    // They are unreachable twice over: not on the allowlist, and not expressible in the
    // wire type at all.
    CapabilityManifest m =
        CapabilityManifest.validate(
            parse(
                "{\"schemaVersion\":1,\"capabilities\":[\"bank\",\"inventory\",\"equipment\","
                    + "\"chat\",\"location\",\"skills\"],\"uploadIntervalSeconds\":300}"));
    assertEquals(Arrays.asList("skills"), m.capabilities());
    for (String denied : new String[] {"bank", "inventory", "equipment", "chat", "location"}) {
      assertFalse(denied, m.allows(denied));
      assertFalse(denied, CapabilityManifest.SUPPORTED_CAPABILITIES.contains(denied));
    }
  }

  @Test
  public void holdsTheUploadIntervalBetweenItsOwnFloorAndCeiling() {
    // A server able to drive this to zero could turn every paired client into a load
    // generator against Bankstand and against Wise Old Man. The client keeps the floor.
    assertEquals(
        CapabilityManifest.MIN_UPLOAD_INTERVAL_SECONDS, CapabilityManifest.clampInterval(0));
    assertEquals(
        CapabilityManifest.MIN_UPLOAD_INTERVAL_SECONDS, CapabilityManifest.clampInterval(-9999));
    assertEquals(
        CapabilityManifest.MIN_UPLOAD_INTERVAL_SECONDS, CapabilityManifest.clampInterval(1));
    assertEquals(
        CapabilityManifest.MAX_UPLOAD_INTERVAL_SECONDS,
        CapabilityManifest.clampInterval(Integer.MAX_VALUE));
    assertEquals(300, CapabilityManifest.clampInterval(300));
  }

  @Test
  public void ignoresFieldsItDoesNotKnow() {
    // What lets the server add a field without stranding older clients. Gson simply has
    // nowhere to put them, which is the behaviour we want and worth pinning.
    CapabilityManifest m =
        CapabilityManifest.validate(
            parse(
                "{\"schemaVersion\":1,\"capabilities\":[\"skills\"],\"uploadIntervalSeconds\":300,"
                    + "\"somethingNew\":\"ignored\",\"another\":{\"nested\":true}}"));
    assertEquals(Arrays.asList("skills"), m.capabilities());
  }

  @Test
  public void refusesAnAbsurdlyLongCapabilityList() {
    StringBuilder names = new StringBuilder();
    for (int i = 0; i < 200; i++) {
      names.append(i == 0 ? "" : ",").append("\"skills\"");
    }
    assertNull(
        CapabilityManifest.validate(
            parse(
                "{\"schemaVersion\":1,\"capabilities\":["
                    + names
                    + "],\"uploadIntervalSeconds\":300}")));
  }

  @Test
  public void namesEachCapabilityOnce() {
    CapabilityManifest m =
        CapabilityManifest.validate(
            parse(
                "{\"schemaVersion\":1,\"capabilities\":[\"skills\",\"skills\",\"skills\"],"
                    + "\"uploadIntervalSeconds\":300}"));
    assertEquals(Arrays.asList("skills"), m.capabilities());
  }

  @Test
  public void survivesRubbish() {
    // Every failure resolves to "keep what you have", never to an exception. A manifest
    // outage must not stop a paired client working.
    assertNull(CapabilityManifest.validate(null));
    assertNull(CapabilityManifest.validate(parse("{}")));
    assertNull(CapabilityManifest.validate(parse("{\"schemaVersion\":1}")));
    assertNull(
        CapabilityManifest.validate(parse("{\"schemaVersion\":1,\"capabilities\":null}")));
  }

  @Test
  public void fallsBackToEverythingThisBuildSupports() {
    // Before the first fetch, and after a total failure. The server's copy can only ever
    // narrow this, never widen it.
    CapabilityManifest bundled = CapabilityManifest.bundled();
    assertEquals(
        CapabilityManifest.SUPPORTED_CAPABILITIES.size(), bundled.capabilities().size());
    for (String name : CapabilityManifest.SUPPORTED_CAPABILITIES) {
      assertTrue(name, bundled.allows(name));
    }
    assertTrue(
        bundled.uploadIntervalSeconds() >= CapabilityManifest.MIN_UPLOAD_INTERVAL_SECONDS);
  }

  @Test
  public void describesItselfForTheDebugOutput() {
    // The active manifest should never be a guess when someone is reading a bug report.
    String line = CapabilityManifest.bundled().describe();
    assertTrue(line, line.contains("skills"));
    assertTrue(line, line.contains("v1"));
  }

  @Test
  public void everyCapabilityTheClientEverGatesOnIsInTheAllowlist() {
    // Every string BankstandPlugin ever passes to manifest.allows(...). Kept as a
    // literal list here, not derived, so this test does not accidentally validate
    // itself: it must independently know what the plugin gates on.
    List<String> gatedOn =
        Arrays.asList(
            "skills", "quests", "diaries", "collectionLog", "combatAchievements",
            "accountType", "notableDrops", "petDrops");
    for (String capability : gatedOn) {
      assertTrue(
          capability + " is gated on by the plugin but missing from SUPPORTED_CAPABILITIES,"
              + " so manifest.allows(" + capability + ") can never return true",
          CapabilityManifest.SUPPORTED_CAPABILITIES.contains(capability));
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class BrandedNoticeTest {

  @Test
  public void namesBankstandInBrandGoldAndLeavesTheBodyAlone() {
    // The colour tag closes after the prefix, so the body renders in whatever colour
    // the player's chat already uses. That is the part they have to read, and it stays
    // legible across every chat mode and transparency setting.
    assertEquals(
        "<col=b3730a>Bankstand: </col>Verified as Crusty Jobby.",
        BankstandPlugin.brandedNotice("Verified as Crusty Jobby."));
  }

  @Test
  public void usesTheLightSurfaceAccent() {
    // b3730a, not the site's brighter f0a830: the chat box is pale parchment by
    // default, where the dark-theme gold washes out.
    assertTrue(BankstandPlugin.brandedNotice("Connected.").contains("b3730a"));
  }

  @Test
  public void coloursNothingButThePrefix() {
    String line = BankstandPlugin.brandedNotice("Could not sync your progress.");
    assertEquals(1, line.split("<col=", -1).length - 1);
  }
}

package com.bankstand;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

/**
 * Keeps README.md's "What it captures" section naming every real capture toggle.
 *
 * <p>The disclosure text bankstand#1143 fixed existed because the opposite happened
 * silently: the plugin grew from 4 capture toggles to 8 and nobody updated the text
 * describing them, so it claimed combat achievements were "deliberately absent" for
 * months after they shipped. This test is the mechanical guard against that recurring:
 * every {@code @ConfigItem} whose key is named {@code KEY_COLLECT_*} must have its human
 * label (the item's own {@code name =} value, minus the leading "Collect") named
 * somewhere in the README, so a ninth toggle added without touching the README fails the
 * build instead of shipping silent drift.
 *
 * <p>Source-scanning rather than behavioural, in the same spirit as {@link
 * NoCredentialsInConfigTest}: the constraint is two files agreeing, not a runtime
 * behaviour. It derives the toggle list from {@code BankstandConfig.java} itself rather
 * than a hardcoded list here, so it does not need updating by hand every time a toggle is
 * added; only the README does.
 */
public class ReadmeCaptureListTest {

  private static final Path CONFIG_FILE =
      Paths.get("src", "main", "java", "com", "bankstand", "BankstandConfig.java");
  private static final Path README_FILE = Paths.get("README.md");

  private static final Pattern NAME_ATTRIBUTE = Pattern.compile("name\\s*=\\s*\"([^\"]+)\"");

  @Test
  public void everyCaptureToggleIsNamedInReadme() throws IOException {
    String config = Files.readString(CONFIG_FILE, StandardCharsets.UTF_8);
    String readme = Files.readString(README_FILE, StandardCharsets.UTF_8).toLowerCase(Locale.ROOT);

    List<String> labels = new ArrayList<>();
    // Split right before each @ConfigItem( so every chunk holds exactly one item's own
    // attributes and nothing past the next item's, however many lines (or comments)
    // separate its keyName from its name.
    for (String chunk : config.split("(?=@ConfigItem\\()")) {
      if (!chunk.contains("BankstandKeys.KEY_COLLECT_")) {
        continue;
      }
      Matcher nameMatcher = NAME_ATTRIBUTE.matcher(chunk);
      assertTrue(
          "Found a KEY_COLLECT_* @ConfigItem with no parseable name = \"...\" attribute:\n"
              + chunk,
          nameMatcher.find());
      labels.add(nameMatcher.group(1));
    }

    assertTrue(
        "Expected at least one KEY_COLLECT_* @ConfigItem in BankstandConfig.java; the"
            + " naming convention this test parses may have changed.",
        !labels.isEmpty());

    List<String> missing = new ArrayList<>();
    for (String label : labels) {
      // "Collect skill XP" -> "skill xp": the toggle's own subject, stripped of the verb
      // every label starts with, since the README states each subject on its own
      // ("Skill XP.", not "Collect skill XP.").
      String subject = label.replaceFirst("(?i)^collect\\s+", "").toLowerCase(Locale.ROOT);
      if (!readme.contains(subject)) {
        missing.add(label);
      }
    }

    assertTrue(
        "README.md's \"What it captures\" section does not name every real capture"
            + " toggle. A toggle exists in BankstandConfig.java with no matching mention"
            + " in the README, which is exactly how the plugin grew from 4 documented"
            + " toggles to 8 without anyone noticing. Missing: "
            + missing,
        missing.isEmpty());
  }
}

package com.bankstand;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

/**
 * Keeps credentials and identity out of the log file.
 *
 * <p>The plugin logs at DEBUG so a bug report from a stranger carries something
 * to diagnose. That is only safe while four things never appear in a log line:
 * the device token (a bearer credential for the submit API), the account hash
 * and display name (they identify a real account), and a raw request or response
 * body (it contains all three plus the whole capture).
 *
 * <p>Source-scanning, like {@link NoAutomationApiTest} and
 * {@link NoCredentialsInConfigTest}, because the constraint is an argument that
 * must not be passed. A behavioural test would have to provoke each log line to
 * find out, and the lines that matter are the ones on the failure paths nobody
 * exercises by accident.
 */
public class NoSecretsInLogsTest {

  private static final Path SOURCE_ROOT = Paths.get("src", "main", "java");

  /** Identifiers that hold something a log must never carry. */
  private static final String[] FORBIDDEN_ARGUMENTS = {
    "token", "accountHash", "displayName", "body", "getToken()",
  };

  @Test
  public void noLogLineTakesACredentialOrAnIdentity() throws IOException {
    List<String> offences = new ArrayList<>();
    try (Stream<Path> files = Files.walk(SOURCE_ROOT)) {
      for (Path file :
          (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        for (int i = 0; i < lines.size(); i++) {
          String line = lines.get(i);
          if (isComment(line) || !line.contains("log.")) {
            continue;
          }
          // A log call can wrap across lines, so the whole statement is read up
          // to its closing `);` rather than just the line the call starts on.
          StringBuilder statement = new StringBuilder(line);
          for (int j = i + 1; j < lines.size() && statement.indexOf(");") < 0; j++) {
            if (!isComment(lines.get(j))) {
              statement.append(lines.get(j));
            }
          }
          // String literals are stripped first. The ban is on passing the value,
          // not on naming it: "token rejected" is exactly the kind of message a
          // log SHOULD carry, and matching it would push authors towards vaguer
          // wording to satisfy a test.
          String args = withoutStringLiterals(statement.toString());
          for (String forbidden : FORBIDDEN_ARGUMENTS) {
            if (args.contains(forbidden)) {
              offences.add(file + ":" + (i + 1) + "  " + line.trim());
            }
          }
        }
      }
    }
    assertTrue(
        "A log line must never carry the device token, the account hash, the display"
            + " name, or a raw body. Log the outcome instead: a status, a reason, or"
            + " which capability blocks the server acknowledged.\n"
            + String.join("\n", offences),
        offences.isEmpty());
  }

  /** Everything between double quotes removed, escapes included. */
  private static String withoutStringLiterals(String statement) {
    return statement.replaceAll("\\\\.", "").replaceAll("\"[^\"]*\"", "\"\"");
  }

  private static boolean isComment(String line) {
    String trimmed = line.trim();
    return trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*");
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import com.bankstand.dto.PairResponse;
import com.bankstand.dto.SubmitEventsResponse;
import com.bankstand.dto.SubmitResponse;
import com.bankstand.dto.SubmitSnapshotResponse;
import com.bankstand.http.HttpResponse;
import com.bankstand.http.HttpTransport;
import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.junit.Test;

public class BankstandClientTest {

  private static final String BASE = "https://example.test";

  /** Records the request and returns a canned response, or throws, without a socket. */
  private static final class FakeTransport implements HttpTransport {
    String url;
    String body;
    Map<String, String> headers;
    boolean called;
    private final HttpResponse response;
    private final IOException toThrow;

    FakeTransport(HttpResponse response) {
      this(response, null);
    }

    FakeTransport(HttpResponse response, IOException toThrow) {
      this.response = response;
      this.toThrow = toThrow;
    }

    @Override
    public HttpResponse post(String url, String jsonBody, Map<String, String> headers)
        throws IOException {
      this.called = true;
      this.url = url;
      this.body = jsonBody;
      this.headers = headers;
      if (toThrow != null) {
        throw toThrow;
      }
      return response;
    }

    @Override
    public HttpResponse get(String url, Map<String, String> headers) throws IOException {
      this.called = true;
      this.url = url;
      this.headers = headers;
      if (toThrow != null) {
        throw toThrow;
      }
      return response;
    }
  }

  /** Returns a scripted sequence of responses/errors and counts calls, for retry tests. */
  private static final class SequencedTransport implements HttpTransport {
    private final java.util.Deque<Object> steps = new java.util.ArrayDeque<>();
    int calls;

    SequencedTransport(Object... steps) {
      java.util.Collections.addAll(this.steps, steps);
    }

    @Override
    public HttpResponse get(String url, Map<String, String> headers) throws IOException {
      return post(url, "", headers);
    }

    @Override
    public HttpResponse post(String url, String jsonBody, Map<String, String> headers)
        throws IOException {
      calls++;
      Object step = steps.isEmpty() ? null : steps.poll();
      if (step instanceof IOException) {
        throw (IOException) step;
      }
      if (step instanceof HttpResponse) {
        return (HttpResponse) step;
      }
      throw new IllegalStateException("no scripted response for call " + calls);
    }
  }

  // Real, not a stub: the retry tests below need actual scheduling to happen.
  // Single-threaded and shared for the whole class rather than one per test,
  // matching how a plugin holds exactly one; every test here uses a zero base
  // delay, so nothing queues up waiting on it.
  private static final ScheduledExecutorService EXECUTOR = Executors.newSingleThreadScheduledExecutor();

  private static final long GET_TIMEOUT_SECONDS = 5;

  private static BankstandClient client(FakeTransport transport) {
    return new BankstandClient(transport, new Gson(), EXECUTOR);
  }

  /** Unwraps the {@link SubmitException} a retrying call's future fails with,
   *  the same shape {@code Future.get()} always reports a failure in. */
  private static SubmitException unwrapSubmitException(ExecutionException e) {
    return (SubmitException) e.getCause();
