package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public class SubmitEnvelopeTest {
  private static Map<String, Integer> skills() {
    Map<String, Integer> s = new LinkedHashMap<>();
    s.put("attack", 5500000);
    s.put("slayer", 101333);
    return s;
  }

  @Test
  public void buildsTheV1WireShape() {
    Map<String, Object> body =
        SubmitEnvelope.body(
            "018f9c8e-7b7a-7c00-8000-000000000abc",
            1,
            "1.0.0",
            "2026-07-23T10:00:00.000Z",
            123456789012345L,
            "Zezima",
            skills());
    JsonObject json = new Gson().toJsonTree(body).getAsJsonObject();

    assertEquals("018f9c8e-7b7a-7c00-8000-000000000abc", json.get("submissionId").getAsString());
    assertEquals(1, json.get("schemaVersion").getAsInt());
    assertEquals("1.0.0", json.get("pluginVersion").getAsString());
    assertEquals("2026-07-23T10:00:00.000Z", json.get("capturedAt").getAsString());
    // account hash is a decimal STRING, not a number.
    assertTrue(json.get("accountHash").getAsJsonPrimitive().isString());
    assertEquals("123456789012345", json.get("accountHash").getAsString());
    assertEquals("Zezima", json.get("displayName").getAsString());
    assertEquals(5500000, json.getAsJsonObject("skills").getAsJsonObject("attack").get("xp").getAsInt());
  }

  @Test
  public void omitsDisplayNameWhenBlank() {
    Map<String, Object> body =
        SubmitEnvelope.body("id", 1, "1.0.0", "t", 1L, null, skills());
    assertFalse(new Gson().toJsonTree(body).getAsJsonObject().has("displayName"));
  }

  @Test
  public void omitsDiariesWhenNull() {
    Map<String, Object> body =
        SubmitEnvelope.body("id", 1, "1.0.0", "t", 1L, "Zezima", skills(), null, null);
    assertFalse(new Gson().toJsonTree(body).getAsJsonObject().has("diaries"));
  }

  @Test
  public void omitsDiariesWhenEmpty() {
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "t", 1L, "Zezima", skills(), null, new LinkedHashMap<>());
    assertFalse(new Gson().toJsonTree(body).getAsJsonObject().has("diaries"));
  }

  @Test
  public void carriesDiaryTaskCountsWhenThereAreAny() {
    java.util.Map<String, Integer> counts = new java.util.LinkedHashMap<>();
    counts.put("ARDOUGNE_EASY", 9);
    counts.put("ARDOUGNE_MEDIUM", 0);
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, counts, null);

    @SuppressWarnings("unchecked")
    Map<String, Object> sent = (Map<String, Object>) body.get("diaryTasks");
    assertEquals(Integer.valueOf(9), sent.get("ARDOUGNE_EASY"));
    // Zero is a real reading and must survive. A tier with none done is a different
    // fact from a tier that was not read, and only the block's absence says the latter.
    assertEquals(Integer.valueOf(0), sent.get("ARDOUGNE_MEDIUM"));
  }

  @Test
  public void omitsDiaryTaskCountsWhenThereAreNone() {
    // Absent means "not observed". A present-but-empty block is treated as an erase by
    // the per-capability merge, which is the trap every other block here avoids too.
    Map<String, Object> none =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, new java.util.LinkedHashMap<>(), null);
    assertFalse(none.containsKey("diaryTasks"));

    Map<String, Object> nullCounts =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null);
    assertFalse(nullCounts.containsKey("diaryTasks"));
  }

  @Test
  public void carriesTheAccountTypeWhenTheGameNamedOne() {
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, "hardcore_group");

    assertEquals("hardcore_group", body.get("accountType"));
  }

  @Test
  public void omitsTheAccountTypeWhenTheGameNamedNone() {
    // Null is the varbit holding a value this build has no name for, or the opt-in being
    // off. Both mean "not observed", and a wrong type is worse than none: it is the badge
    // on the player's own profile.
    Map<String, Object> nothing =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null);
    assertFalse(nothing.containsKey("accountType"));

    Map<String, Object> empty =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, "");
    assertFalse(empty.containsKey("accountType"));
  }

  @Test
  public void carriesCombatAchievementBossCountsWhenThereAreAny() {
    java.util.Map<String, Integer> bossCounts = new java.util.LinkedHashMap<>();
    bossCounts.put("Vorkath", 4);
    bossCounts.put("Zulrah", 0);
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false, bossCounts);

    @SuppressWarnings("unchecked")
    Map<String, Object> sent = (Map<String, Object>) body.get("combatAchievementBossCounts");
    assertEquals(Integer.valueOf(4), sent.get("Vorkath"));
    // A genuine zero is a fact (the boss's tasks were read and none are done), not the
    // same thing as the boss never having been read at all.
    assertEquals(Integer.valueOf(0), sent.get("Zulrah"));
  }

  @Test
  public void omitsCombatAchievementBossCountsWhenThereAreNone() {
    // Absent means "not observed"; a present-but-empty block is treated as an erase by
    // the per-capability merge, the same trap every other block here avoids.
    Map<String, Object> none =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false, new java.util.LinkedHashMap<>());
    assertFalse(none.containsKey("combatAchievementBossCounts"));

    Map<String, Object> nullCounts =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false, null);
    assertFalse(nullCounts.containsKey("combatAchievementBossCounts"));
  }

  @Test
  public void aPreExistingCallerWithNoBossCountsStillOmitsTheBlock() {
    // The 14-arg overload every caller before this field existed still compiles
    // against; it must keep omitting the new field, not send it as empty.
    Map<String, Object> body =
        SubmitEnvelope.body(
            "id", 1, "1.0.0", "2026-08-09T10:00:00Z", 42L, "Zezima",
            java.util.Collections.singletonMap("attack", 100),
            null, null, null, null, null, null, false);
    assertFalse(body.containsKey("combatAchievementBossCounts"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The pairing credentials, kept in a file rather than in {@code ConfigManager}.
 *
 * <p>Every failure here resolves to "not paired", which asks the player to pair again.
 * The alternative, carrying on with a credential we could not read, submits against a
 * token that may not be ours.
 */
public class DeviceCredentialStoreTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private DeviceCredentialStore storeIn(File file) {
    return new DeviceCredentialStore(file, new Gson());
  }

  private File newFile() throws IOException {
    return new File(folder.newFolder("bankstand"), "device.json");
  }

  @Test
  public void roundTripsAPairing() throws IOException {
    File file = newFile();
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    saved.setDeviceId("dev_1");
    saved.setExpiresAt("2027-01-01T00:00:00Z");
    storeIn(file).save(saved);

    DeviceCredentials loaded = storeIn(file).load();

    assertEquals("tok_abc", loaded.getToken());
    assertEquals("dev_1", loaded.getDeviceId());
    assertEquals("2027-01-01T00:00:00Z", loaded.getExpiresAt());
    assertTrue(loaded.isPaired());
  }

  @Test
  public void readsAsUnpairedWhenNothingWasEverWritten() throws IOException {
    DeviceCredentials loaded = storeIn(newFile()).load();

    assertFalse(loaded.isPaired());
    assertNull(loaded.getToken());
  }

  @Test
  public void readsAsUnpairedWhenTheFileIsCorrupt() throws IOException {
    // A truncated write, a half-synced file, a hand-edit. Never a parse failure the
    // player has to diagnose, and never a partially-populated credential.
    File file = newFile();
    Files.write(file.toPath(), "{ not json".getBytes(StandardCharsets.UTF_8));

    assertFalse(storeIn(file).load().isPaired());
  }

  @Test
  public void treatsABlankTokenAsUnpaired() throws IOException {
    File file = newFile();
    DeviceCredentials blank = new DeviceCredentials();
    blank.setToken("   ");
    storeIn(file).save(blank);

    assertFalse(storeIn(file).load().isPaired());
  }

  @Test
  public void clearForgetsThePairing() throws IOException {
    File file = newFile();
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    storeIn(file).save(saved);

    storeIn(file).clear();

    assertFalse(storeIn(file).load().isPaired());
  }

  @Test
  public void clearOnAnAlreadyEmptyStoreIsNotAnError() throws IOException {
    storeIn(newFile()).clear();
  }

  @Test
  public void createsItsDirectoryOnFirstSave() throws IOException {
    // The plugin points this at <RUNELITE_DIR>/bankstand, which does not exist on a
    // fresh install until something writes to it.
    File file = new File(new File(folder.getRoot(), "not-created-yet"), "device.json");
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");

    storeIn(file).save(saved);

    assertTrue(storeIn(file).load().isPaired());
  }

  @Test
  public void aFailedSaveDoesNotDestroyThePreviousPairing() throws IOException {
    // Temp-then-move, so a crash between opening the file and finishing the write
    // cannot leave a truncated token where a working one used to be.
    File file = newFile();
    DeviceCredentials first = new DeviceCredentials();
    first.setToken("tok_first");
    storeIn(file).save(first);

    DeviceCredentials second = new DeviceCredentials();
    second.setToken("tok_second");
    storeIn(file).save(second);

    assertEquals("tok_second", storeIn(file).load().getToken());
  }

  @Test
  public void cachesAfterTheFirstLoadRatherThanReReadingTheFile() throws IOException {
    // Every gate the plugin registers calls load() on nearly every in-game event, so a
    // second load() on the same instance must not touch disk again: deleting the file out
    // from under an already-loaded instance must not flip it back to unpaired.
    File file = newFile();
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    DeviceCredentialStore store = storeIn(file);
    store.save(saved);

    assertTrue(store.load().isPaired());
    Files.delete(file.toPath());

    assertTrue(store.load().isPaired());
    assertEquals("tok_abc", store.load().getToken());
  }

  @Test
  public void aSaveIsVisibleToTheSameInstancesNextLoadWithoutTouchingDisk() throws IOException {
    File file = newFile();
    DeviceCredentialStore store = storeIn(file);
    assertFalse(store.load().isPaired());

    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_new");
    store.save(saved);

    assertEquals("tok_new", store.load().getToken());
  }

  @Test
  public void clearIsVisibleToTheSameInstancesNextLoad() throws IOException {
    File file = newFile();
    DeviceCredentialStore store = storeIn(file);
    DeviceCredentials saved = new DeviceCredentials();
    saved.setToken("tok_abc");
    store.save(saved);
    assertTrue(store.load().isPaired());

    store.clear();

    assertFalse(store.load().isPaired());
  }
}

package com.bankstand;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

/**
 * Holds the Plugin Hub's other line: a retry backs off by scheduling, never by blocking
 * a thread.
 *
 * <p>Review on PR #15400 flagged exactly this: {@code Thread.sleep} in the submit retry's
 * backoff, and the {@code Thread.currentThread().interrupt()} that came with catching its
 * {@code InterruptedException}. Fixed by moving the backoff onto the plugin's own {@code
 * ScheduledExecutorService} (see {@code BankstandClient#attempt}), which needed no blocked
 * thread and no interrupt handling at all. Source-scanning, the same shape as {@link
 * NoAutomationApiTest}, so a future retry loop reaching for the obvious-looking blocking
 * idiom fails a test instead of a review round trip.
 */
public class NoBlockingRetryTest {

  private static final Path SOURCE_ROOT = Paths.get("src", "main", "java");

  private static final String[] BANNED = {
    "Thread.sleep(", "Thread.currentThread().interrupt()",
  };

  @Test
  public void noSourceFileBlocksAThreadToBackOff() throws IOException {
    List<String> offences = new ArrayList<>();
    try (Stream<Path> files = Files.walk(SOURCE_ROOT)) {
      for (Path file : (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        for (int i = 0; i < lines.size(); i++) {
          String line = lines.get(i);
          if (isComment(line)) {
            continue;
          }
          for (String banned : BANNED) {
            if (line.contains(banned)) {
              offences.add(file + ":" + (i + 1) + "  " + line.trim());
            }
          }
        }
      }
    }
    assertTrue(
        "Plugin Hub bans blocking a thread to back off. Schedule the retry on a"
            + " ScheduledExecutorService instead:\n"
            + String.join("\n", offences),
        offences.isEmpty());
  }

  private static boolean isComment(String line) {
    String trimmed = line.trim();
    return trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*");
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.util.Map;
import java.util.Set;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class DiaryTaskCompletionCaptureTest {

  private static final String WESTERN_TASK_MESSAGE =
      "Well done! You have completed an elite task in the Western Provinces area. Your"
          + " Achievement Diary has been updated.";

  // The wire region key DiaryTaskRegions resolves "Western Provinces" to, and the first
  // of DiaryTaskVarplayers.ALL's two ids for it (WESTERN_ACHIEVEMENT_DIARY).
  private static final String WESTERN_REGION = "WESTERN_PROVINCES";
  private static final int WESTERN_VARPLAYER = DiaryTaskVarplayers.ALL.get(WESTERN_REGION)[0];

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private EventOutbox outboxIn(File file) {
    return new EventOutbox(file, new Gson());
  }

  private File newFile() throws IOException {
    // A unique subfolder per call: TemporaryFolder#newFolder throws if the same
    // relative path is requested twice within one test (see emitsForEveryRealTier,
    // which calls this in a loop).
    return new File(folder.newFolder(), "events.json");
  }

  private DiaryTaskManifest verifiedWesternManifest(String tier, String taskName) {
    return new DiaryTaskManifest(
        Set.of(WESTERN_REGION),
        Map.of(WESTERN_REGION, Map.of(
            WESTERN_VARPLAYER, Map.of(0, new DiaryTaskManifest.Entry(tier, taskName)))));
  }

  @Test
  public void emitsOnADiaryTaskCompletionBroadcast() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed an elite task in the Western Provinces area. Your"
            + " Achievement Diary has been updated.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals(
        TransientEvent.TYPE_DIARY_TASK_COMPLETED, outbox.pending().get(0).getEvent().getType());
    assertEquals("elite", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals(
        "Western Provinces", outbox.pending().get(0).getEvent().getPayload().get("area"));
  }

  @Test
  public void emitsOnAnIndefiniteArticleAVariant() throws IOException {
    // "a hard"/"a medium" use the "a" article, not "an"; the pattern must accept both.
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed a hard task in the Kandarin area. Your Achievement"
            + " Diary has been updated.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("hard", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals("Kandarin", outbox.pending().get(0).getEvent().getPayload().get("area"));
  }

  @Test
  public void emitsForEveryRealTier() throws IOException {
    for (String tier : new String[] {"easy", "medium", "hard", "elite"}) {
      EventOutbox outbox = outboxIn(newFile());
      DiaryTaskCompletionCapture capture =
          new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);
      String article = tier.equals("elite") || tier.equals("easy") ? "an" : "a";

      capture.handleMessage(
          "Well done! You have completed "
              + article
              + " "
              + tier
              + " task in the Varrock area. Your Achievement Diary has been updated.");

      assertTrue("expected an event for tier " + tier, !outbox.pending().isEmpty());
      assertEquals(tier, outbox.pending().get(0).getEvent().getPayload().get("tier"));
    }
  }

  @Test
  public void keepsADoubleBarrelledAreaNameIntact() throws IOException {
    // Three regions are double-barrelled (Kourend & Kebos, Lumbridge & Draynor, Western
    // Provinces); the greedy capture group must keep the whole phrase, not stop at the
    // first word.
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed a medium task in the Lumbridge & Draynor area. Your"
            + " Achievement Diary has been updated.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals(
        "Lumbridge & Draynor", outbox.pending().get(0).getEvent().getPayload().get("area"));
  }

  @Test
  public void ignoresAnUnrecognisedTierWord() throws IOException {
    // "master"/"grandmaster" are real combat-achievement tiers, not diary tiers; a
    // mis-parse resolving to one of those must never reach the outbox.
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Well done! You have completed a master task in the Varrock area. Your Achievement"
            + " Diary has been updated.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void doesNotConfuseTheTierCompletionBroadcastForThisOne() throws IOException {
    // The #770 early-trigger's tier-completion broadcast starts with "Congratulations"
    // and names the tier and area differently; this capture's pattern must not match it.
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Congratulations, you have completed all of the Easy tasks in the Varrock area. Your"
            + " Achievement Diary has been updated.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void ignoresAnUnrelatedMessage() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've reached level 99 in Attack!");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void skipsAnOversizedAreaName() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);
    String oversizedArea = repeat("A", 129);

    capture.handleMessage(
        "Well done! You have completed an elite task in the "
            + oversizedArea
            + " area. Your Achievement Diary has been updated.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void emitsAnAreaNameAtExactlyTheLengthBound() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    DiaryTaskCompletionCapture capture =
        new DiaryTaskCompletionCapture(outbox, () -> true, () -> 1L);
    String boundedArea = repeat("A", 128);

    capture.handleMessage(
        "Well done! You have completed an elite task in the "
            + boundedArea
            + " area. Your Achievement Diary has been updated.");

