package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.bankstand.dto.EventAck;
import com.bankstand.dto.SubmitSnapshotResponse;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Test;

/**
 * Developer-mode entry point: launches RuneLite with this plugin sideloaded. Lives
 * in the test source set so it is never part of the shipped plugin. Run it with
 * {@code ./gradlew run}.
 *
 * <p>Also covers the plugin's capture-decision logic. {@link BankstandPlugin}'s
 * capture-and-submit wiring reads a live {@code Client} and a Guice-constructed
 * {@code ConfigManager} (whose constructor is private, so it cannot be faked
 * without a mocking library); the decision logic that gates a submit and a
 * baseline advance is exposed as small package-private static methods so it is
 * unit-testable on its own, using the real {@link SkillBaseline} and {@link
 * QuestBaseline}.
 */
public class BankstandPluginTest {
  public static void main(String[] args) throws Exception {
    ExternalPluginManager.loadBuiltin(BankstandPlugin.class);
    RuneLite.main(args);
  }

  private static Map<String, Integer> skills(String key, int xp) {
    Map<String, Integer> m = new LinkedHashMap<>();
    m.put(key, xp);
    return m;
  }

  private static Map<String, String> quests(String key, String state) {
    Map<String, String> m = new LinkedHashMap<>();
    m.put(key, state);
    return m;
  }

  private static Map<String, String> diaries(String key, String state) {
    Map<String, String> m = new LinkedHashMap<>();
    m.put(key, state);
    return m;
  }

  /** A set of {@code count} distinct observed item ids. */
  private static Set<Integer> logItems(int count) {
    Set<Integer> ids = new LinkedHashSet<>();
    for (int i = 1; i <= count; i++) {
      ids.add(i);
    }
    return ids;
  }

  /** {@code count} distinct transient events, ids ordered "id-0".."id-(count-1)". */
  private static List<TransientEvent> events(int count) {
    List<TransientEvent> list = new ArrayList<>();
    for (int i = 0; i < count; i++) {
      Map<String, Object> payload = new LinkedHashMap<>();
      payload.put("itemName", "Dragon warhammer");
      list.add(
          new TransientEvent(
              "id-" + i, TransientEvent.TYPE_NOTABLE_DROP, "2026-08-10T10:00:00Z", payload));
    }
    return list;
  }

  /** An {@link EventAck} as Gson would populate it from the wire, since the type has
   *  no public constructor of its own. */
  private static EventAck ack(String id, String outcome, String reason) {
    String json =
        reason == null
            ? String.format("{\"id\":\"%s\",\"outcome\":\"%s\"}", id, outcome)
            : String.format(
                "{\"id\":\"%s\",\"outcome\":\"%s\",\"reason\":\"%s\"}", id, outcome, reason);
    return new Gson().fromJson(json, EventAck.class);
  }

  /**
   * The submit decision alone, which is what every test below this line is about.
   *
   * <p>{@code plan} now answers two questions at once: whether to submit, and which
   * optional blocks ride along. The per-block choice is covered by {@link
   * SubmitPlanTest}; these cases predate it and are the regression net for the decision
   * itself, so they are left asserting exactly what they always asserted rather than
   * being rewritten around the wider return type.
   */
  private static boolean shouldSubmit(
      SkillBaseline skillBaseline,
      Map<String, Integer> skills,
      QuestBaseline questBaseline,
      Map<String, String> quests,
      DiaryBaseline diaryBaseline,
      Map<String, String> diaries,
      CollectionLogBaseline collectionLogBaseline,
      int collectionLogCount) {
    return BankstandPlugin.plan(
            skillBaseline,
            skills,
            questBaseline,
            quests,
            diaryBaseline,
            diaries,
            collectionLogBaseline,
            logItems(collectionLogCount))
        .shouldSubmit();
  }

  private static SubmitSnapshotResponse response(boolean accepted, boolean stored, String reason) {
    String json =
        String.format(
            "{\"accepted\":%s,\"stored\":%s,\"reason\":\"%s\"}", accepted, stored, reason);
    return new Gson().fromJson(json, SubmitSnapshotResponse.class);
  }

  /** A response that stored the submission and acknowledged the named blocks. */
  private static SubmitSnapshotResponse storedBlocks(String... blocks) {
    StringBuilder list = new StringBuilder();
    for (String block : blocks) {
      if (list.length() > 0) {
        list.append(",");
      }
      list.append("\"").append(block).append("\"");
    }
    String json =
        String.format(
            "{\"accepted\":true,\"stored\":true,\"reason\":\"persisted\",\"storedBlocks\":[%s]}",
            list);
    return new Gson().fromJson(json, SubmitSnapshotResponse.class);
  }

  @Test
  public void submitsWhenSkillsChangedAndQuestsAreNotIncluded() {
    // The opt-in is off: the capture path passes a null quests map. A skill change
    // alone is still enough to submit.
    assertTrue(
        shouldSubmit(
            new SkillBaseline(),
            skills("attack", 100),
            new QuestBaseline(),
            null,
            new DiaryBaseline(),
            null, new CollectionLogBaseline(), 0));
  }

  @Test
  public void ignoresAQuestChangeWhenQuestCaptureIsOff() {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    // Skills are unchanged and quests are null (opt-in off): a quest change can never
    // be observed, so nothing should trigger a submit.
    assertFalse(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            new QuestBaseline(),
            null,
            new DiaryBaseline(),
            null, new CollectionLogBaseline(), 0));
  }

  @Test
  public void submitsOnAQuestChangeAloneWhenQuestCaptureIsOn() {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    // Skills are identical to the baseline; only the quest state changed.
    assertTrue(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            new QuestBaseline(),
            quests("COOKS_ASSISTANT", "IN_PROGRESS"),
            new DiaryBaseline(),
            null, new CollectionLogBaseline(), 0));
  }

  @Test
  public void doesNotSubmitWhenNeitherSkillsNorQuestsChanged() {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    QuestBaseline questBaseline = new QuestBaseline();
    questBaseline.advance(quests("COOKS_ASSISTANT", "IN_PROGRESS"));
    assertFalse(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            questBaseline,
            quests("COOKS_ASSISTANT", "IN_PROGRESS"),
            new DiaryBaseline(),
            null, new CollectionLogBaseline(), 0));
  }

  @Test
  public void ignoresADiaryChangeWhenDiaryCaptureIsOff() {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    // Skills and quests are unchanged and diaries are null (opt-in off): a diary
    // change can never be observed, so nothing should trigger a submit.
    assertFalse(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            new QuestBaseline(),
            null,
            new DiaryBaseline(),
            null, new CollectionLogBaseline(), 0));
  }

  @Test
  public void submitsOnADiaryChangeAloneWhenDiaryCaptureIsOn() {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    // Skills are identical to the baseline; only the diary state changed.
    assertTrue(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            new QuestBaseline(),
            null,
            new DiaryBaseline(),
            diaries("ARDOUGNE_EASY", "COMPLETE"),
            new CollectionLogBaseline(),
            0));
  }

  @Test
  public void submitsWhenOnlyTheCollectionLogGrew() {
    // The case that made this gate necessary. A player syncs their log and gains no
    // xp; without the collection log in the gate the submission would wait for the
    // next level, which is exactly when they are not looking at their log.
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    assertTrue(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            new QuestBaseline(),
            null,
            new DiaryBaseline(),
            null,
            new CollectionLogBaseline(),
            42));
  }

  @Test
  public void doesNotSubmitForAnEmptyCollectionLog() {
    // Nothing observed is not nothing owned, so an empty log is not a change worth
    // sending on every capture.
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    assertFalse(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            new QuestBaseline(),
            null,
            new DiaryBaseline(),
            null,
            new CollectionLogBaseline(),
            0));
  }

  @Test
  public void doesNotSubmitWhenNeitherSkillsNorQuestsNorDiariesChanged() {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills("attack", 100));
    QuestBaseline questBaseline = new QuestBaseline();
    questBaseline.advance(quests("COOKS_ASSISTANT", "IN_PROGRESS"));
    DiaryBaseline diaryBaseline = new DiaryBaseline();
    diaryBaseline.advance(diaries("ARDOUGNE_EASY", "COMPLETE"));
    assertFalse(
        shouldSubmit(
            skillBaseline,
            skills("attack", 100),
            questBaseline,
            quests("COOKS_ASSISTANT", "IN_PROGRESS"),
            diaryBaseline,
            diaries("ARDOUGNE_EASY", "COMPLETE"),
            new CollectionLogBaseline(),
            0));
  }

  @Test
  public void advancesSkillsWhenTheServerAcknowledgedTheBlock() {
    assertTrue(BankstandPlugin.shouldAdvanceSkills(storedBlocks("skills")));
  }

  @Test
  public void doesNotAdvanceSkillsOnACooldown() {
    assertFalse(BankstandPlugin.shouldAdvanceSkills(response(true, false, "cooldown")));
  }

  @Test
  public void doesNotAdvanceSkillsWhenTheAccountIsUnclaimed() {
    // The real server shape: accepted, HTTP 200, but nothing stored. Asserting this
    // with accepted=false would pass while missing the bug, because the server never
    // returns accepted=false for a reason it recognises.
    assertFalse(BankstandPlugin.shouldAdvanceSkills(response(true, false, "unclaimed")));
  }

  @Test
  public void doesNotAdvanceSkillsWhenIngestIsNotApplied() {
    assertFalse(BankstandPlugin.shouldAdvanceSkills(response(true, false, "not_applied")));
  }

  @Test
  public void advancesQuestsWhenTheServerAcknowledgedTheBlock() {
    assertTrue(BankstandPlugin.shouldAdvanceQuests(storedBlocks("skills", "quests"), true));
  }

  @Test
  public void doesNotAdvanceQuestsWhenStoredButTheBlockWasNotAcknowledged() {
    // The submission stored (skills were fresh) but the server dropped the quests block
    // because its rollout flag is off. Advancing here would acknowledge data that was
    // never written.
    assertFalse(BankstandPlugin.shouldAdvanceQuests(storedBlocks("skills"), true));
  }

  @Test
  public void doesNotAdvanceQuestsWhenTheServerSendsNoAcknowledgement() {
    // An older server omits the field entirely. Treating that as "not written" re-sends
    // rather than risking a silent loss.
    assertFalse(BankstandPlugin.shouldAdvanceQuests(response(true, true, "persisted"), true));
  }

  @Test
  public void doesNotAdvanceQuestsWhenIncludedButNotStored() {
    assertFalse(BankstandPlugin.shouldAdvanceQuests(response(true, false, "not_applied"), true));
  }

  @Test
  public void doesNotAdvanceQuestsWhenIncludedButStale() {
    assertFalse(BankstandPlugin.shouldAdvanceQuests(response(true, false, "stale"), true));
  }

  @Test
  public void doesNotAdvanceQuestsWhenNotIncludedEvenIfAcknowledged() {
    assertFalse(BankstandPlugin.shouldAdvanceQuests(storedBlocks("skills", "quests"), false));
  }

  @Test
  public void advancesDiariesWhenTheServerAcknowledgedTheBlock() {
    assertTrue(BankstandPlugin.shouldAdvanceDiaries(storedBlocks("skills", "diaries"), true));
  }

  @Test
  public void doesNotAdvanceDiariesWhenStoredButTheBlockWasNotAcknowledged() {
    // The case that loses data if it advances: a completed diary tier is a one-shot
    // fact, so a false acknowledgement means it is never re-sent.
    assertFalse(BankstandPlugin.shouldAdvanceDiaries(storedBlocks("skills", "quests"), true));
  }

  @Test
  public void doesNotAdvanceDiariesWhenTheServerSendsNoAcknowledgement() {
    assertFalse(BankstandPlugin.shouldAdvanceDiaries(response(true, true, "persisted"), true));
  }

  @Test
  public void doesNotAdvanceDiariesWhenIncludedButNotStored() {
    assertFalse(BankstandPlugin.shouldAdvanceDiaries(response(true, false, "not_applied"), true));
  }

  @Test
  public void doesNotAdvanceDiariesWhenNotIncludedEvenIfAcknowledged() {
    assertFalse(BankstandPlugin.shouldAdvanceDiaries(storedBlocks("skills", "diaries"), false));
  }

  // --- Event outbox draining: chunking against the server's per-request cap, and
  // which acked ids stop being retried (the two halves of the #770 review fix). ---

  @Test
  public void chunkEventsKeepsAGroupAtExactlyTheCapInOneChunk() {
    List<List<TransientEvent>> chunks = BankstandPlugin.chunkEvents(events(50), 50);

    assertEquals(1, chunks.size());
    assertEquals(50, chunks.get(0).size());
  }

  @Test
  public void chunkEventsSplitsAGroupOverTheCapIntoTwoChunks() {
    // The bug this guards: a group of 51 submitted whole gets one 400 for the whole
    // group, forever, because the server's own MAX_EVENTS_PER_BATCH is 50.
    List<List<TransientEvent>> chunks = BankstandPlugin.chunkEvents(events(51), 50);

    assertEquals(2, chunks.size());
    assertEquals(50, chunks.get(0).size());
    assertEquals(1, chunks.get(1).size());
  }

  @Test
  public void chunkEventsPreservesOrderWithinAndAcrossChunks() {
    List<List<TransientEvent>> chunks = BankstandPlugin.chunkEvents(events(120), 50);

    assertEquals(3, chunks.size());
    assertEquals("id-0", chunks.get(0).get(0).getId());
    assertEquals("id-49", chunks.get(0).get(49).getId());
    assertEquals("id-50", chunks.get(1).get(0).getId());
    assertEquals("id-99", chunks.get(1).get(49).getId());
    assertEquals("id-100", chunks.get(2).get(0).getId());
    assertEquals("id-119", chunks.get(2).get(19).getId());
  }

  @Test
  public void idsToAckIncludesStoredAndDuplicateOutcomes() {
    Set<String> ids =
        BankstandPlugin.idsToAck(Arrays.asList(ack("a", "stored", null), ack("b", "duplicate", null)));

    assertTrue(ids.contains("a"));
    assertTrue(ids.contains("b"));
  }

  @Test
  public void idsToAckIncludesARejectedStaleOutcome() {
    // Aged past the server's retention window: age only increases, so resubmitting
    // the exact same event can never become deliverable. Leaving it queued would
    // waste outbox capacity forever, bounded only by the 200-entry cap eventually
    // evicting it.
    Set<String> ids = BankstandPlugin.idsToAck(Collections.singletonList(ack("a", "rejected", "stale")));

    assertTrue(ids.contains("a"));
  }

  @Test
  public void idsToAckExcludesARejectedNotAppliedOutcome() {
    // A capability flag can be turned on later, which makes this reason legitimately
    // worth retrying, unlike a stale rejection.
    Set<String> ids =
        BankstandPlugin.idsToAck(Collections.singletonList(ack("a", "rejected", "not_applied")));

    assertTrue(ids.isEmpty());
  }

  @Test
  public void idsToAckExcludesAnUnrecognisedOutcome() {
    Set<String> ids = BankstandPlugin.idsToAck(Collections.singletonList(ack("a", "pending", null)));

    assertTrue(ids.isEmpty());
  }

  @Test
  public void notableUntradeableAllowlistIsNotEmpty() {
    // #1096: the allowlist shipped empty for a while, so a tradeable-value-only
    // notable drop capture silently missed every pet/untradeable unique. This just
    // guards against that regressing again, not against a specific curation choice.
    assertFalse(BankstandPlugin.NOTABLE_UNTRADEABLE_ALLOWLIST.isEmpty());
  }

  @Test
  public void notableUntradeableAllowlistUsesRealInGameCasing() {
    // Every entry was cross-checked against the game's own cache item definitions
    // (exact name text, tradeable=false), not typed from a wiki-disambiguated
    // collection-log display name: a first draft pulled from that source had
    // inconsistent Title Case on roughly a third of its entries (e.g. "Baby mole"
    // vs. the real "Baby Mole"), which would have silently never matched a real
    // drop, since the check this backs is a plain Set#contains against
    // ItemComposition#getName(). Spot-checking a representative sample here, not
    // exhaustively: the point is to catch a wholesale reintroduction of that class
    // of mistake, not to duplicate the verification script's own coverage.
    Set<String> allowlist = BankstandPlugin.NOTABLE_UNTRADEABLE_ALLOWLIST;
    assertTrue(allowlist.contains("Baby Mole"));
    assertTrue(allowlist.contains("Pet Kree'arra"));
    assertTrue(allowlist.contains("TzRek-Jad"));
    assertTrue(allowlist.contains("Rift guardian"));
    assertFalse(allowlist.contains("Baby mole"));
    assertFalse(allowlist.contains("Rift guardian (fire)"));
  }

  @Test
  public void capturedSkillsIncludesSailing() {
    // Sailing was OSRS's 24th skill and this allowlist missed it for a while,
    // silently never reading or sending its XP even though nothing else in the
    // pipeline was broken. This guards against that regressing again. The exact
    // count (24) is asserted too, since a future skill addition should fail this
    // test rather than pass it silently.
    assertEquals(24, BankstandPlugin.CAPTURED_SKILLS.size());
    assertTrue(BankstandPlugin.CAPTURED_SKILLS.contains(Skill.SAILING));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.bankstand.CollectionLogSync.Outcome;
import org.junit.Test;

public class CollectionLogSyncTest {

  /** Ticks with the log open, the search closed and no items arriving. */
  private static void idleTicks(CollectionLogSync sync, int count) {
    for (int i = 0; i < count; i++) {
      assertNull(sync.onTick(false, true));
    }
  }

  @Test
  public void ignoresOrdinaryPageBrowsing() {
    CollectionLogSync sync = new CollectionLogSync();

    assertFalse(sync.isActive());
    // The same script fires when the player just turns a page. It must reach the
    // accumulator without reporting itself as a whole-log sync.
    sync.onItemObserved(1, false);
    sync.onItemObserved(2, false);

    assertFalse(sync.isActive());
    assertEquals(0, sync.observedCount());
    assertNull(sync.onTick(false, true));
  }

  /**
   * The reason arming is no longer required. WikiSync is one button because it drives
   * the Search with a call the Hub bans us from; the fewest actions left to us is the
   * player clicking the game's own Search, so that alone has to be enough.
   */
  @Test
  public void aSearchStartsAReadWithNothingArmed() {
    CollectionLogSync sync = new CollectionLogSync();

    sync.onItemObserved(1, true);
    sync.onItemObserved(2, true);

    assertTrue(sync.isActive());
    assertFalse(sync.isAwaitingSearch());
    assertEquals(2, sync.observedCount());
  }

  @Test
  public void anUnarmedSearchStillReportsComplete() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.onItemObserved(1, true);

    Outcome outcome = null;
    for (int i = 0; i < CollectionLogSync.QUIET_TICKS && outcome == null; i++) {
      outcome = sync.onTick(true, true);
    }

    assertEquals(Outcome.COMPLETE, outcome);
  }

  @Test
  public void armingWaitsForTheSearchWithoutCountingAnything() {
    CollectionLogSync sync = new CollectionLogSync();

    sync.arm();

    assertTrue(sync.isActive());
    assertTrue(sync.isAwaitingSearch());
    assertEquals(0, sync.observedCount());
  }

  @Test
  public void countsItemsOnceTheSearchStartsStreaming() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();

    assertNull(sync.onTick(true, true));
    sync.onItemObserved(3, true);
    sync.onItemObserved(4, true);
    sync.onItemObserved(5, true);

    assertFalse(sync.isAwaitingSearch());
    assertEquals(3, sync.observedCount());
  }

  @Test
  public void reportsCompleteWhenAReadRunUnderSearchGoesQuiet() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));
    sync.onItemObserved(6, true);
    sync.onItemObserved(7, true);

    Outcome outcome = null;
    for (int i = 0; i < CollectionLogSync.QUIET_TICKS && outcome == null; i++) {
      outcome = sync.onTick(true, true);
    }

    assertEquals(Outcome.COMPLETE, outcome);
    assertEquals(2, outcome.getObserved());
    // The outcome is reported exactly once, then the sync is done.
    assertFalse(sync.isActive());
    assertNull(sync.onTick(true, true));
  }

  /**
   * Observed live: a real enumeration fires the script twice per entry on the first read
   * of a session, and counting events reported "Synced 422 entries" for a log holding
   * 211. The accumulator was always right, being a set; the figure shown was not.
   */
  /** Both Prospector sets are eight ids filling four slots, and the box says four. */
  @Test
  public void countsAVariantAsTheSlotItFills() {
    CollectionLogSync sync = new CollectionLogSync();
    for (int id : new int[] {12013, 12014, 12015, 12016, 29472, 29474, 29476, 29478}) {
      sync.onItemObserved(id, true);
    }

    assertEquals(4, sync.observedCount());
  }

  @Test
  public void countsDistinctEntriesRatherThanScriptFires() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));

    for (int repeat = 0; repeat < 2; repeat++) {
      for (int id = 1; id <= 211; id++) {
        sync.onItemObserved(id, true);
      }
    }

    assertEquals(211, sync.observedCount());
  }

  @Test
  public void doesNotFinishWhileItemsAreStillArriving() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));

    // An item on every tick keeps the stream alive well past the quiet threshold.
    for (int i = 0; i < CollectionLogSync.QUIET_TICKS * 3; i++) {
      sync.onItemObserved(100 + i, true);
      assertNull(sync.onTick(true, true));
    }

    assertTrue(sync.isActive());
    assertEquals(CollectionLogSync.QUIET_TICKS * 3, sync.observedCount());
  }

  @Test
  public void reportsPartialWhenTheLogClosesMidRead() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));
    sync.onItemObserved(9, true);
    sync.onItemObserved(10, true);
    sync.onItemObserved(11, true);

    Outcome outcome = sync.onTick(true, false);

    assertEquals(Outcome.PARTIAL, outcome);
    assertEquals(3, outcome.getObserved());
    assertFalse(sync.isActive());
  }

  /**
   * The conservative direction, and deliberately so. The search-open signal is a widget
   * read that cannot be verified outside a running client, so when it never arrives the
   * sync under-claims rather than calling an unverified read complete.
   */
  @Test
  public void reportsPartialWhenItemsArrivedWithoutTheSearchEverBeingSeen() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    sync.onItemObserved(12, true);

    Outcome outcome = null;
    for (int i = 0; i < CollectionLogSync.QUIET_TICKS && outcome == null; i++) {
      outcome = sync.onTick(false, true);
    }

    assertEquals(Outcome.PARTIAL, outcome);
    assertEquals(1, outcome.getObserved());
  }

  @Test
  public void cancelsSilentlyWhenTheLogClosesBeforeAnySearch() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();

    // Nothing was read, so there is no outcome worth telling the player about.
    assertNull(sync.onTick(false, false));
    assertFalse(sync.isActive());
  }

  @Test
  public void cancelsAnArmedSyncThePlayerNeverActedOn() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();

    idleTicks(sync, CollectionLogSync.ARM_TIMEOUT_TICKS - 1);
    assertTrue(sync.isActive());
    assertNull(sync.onTick(false, true));

    // Times out with no outcome: the player opened the menu and thought better of it.
    assertFalse(sync.isActive());
  }

  @Test
  public void theArmTimeoutDoesNotApplyOnceItemsAreStreaming() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    idleTicks(sync, CollectionLogSync.ARM_TIMEOUT_TICKS - 1);

    // A read that starts on the last possible tick still gets its full quiet window,
    // rather than being cut off by a timeout meant for a sync that never began.
    sync.onItemObserved(13, true);
    assertNull(sync.onTick(true, true));
    assertTrue(sync.isActive());
    assertEquals(1, sync.observedCount());
  }

  @Test
  public void armingTwiceRestartsTheReadRatherThanAccumulating() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    assertNull(sync.onTick(true, true));
    sync.onItemObserved(14, true);
    sync.onItemObserved(15, true);

    sync.arm();

    assertEquals(0, sync.observedCount());
    assertTrue(sync.isAwaitingSearch());
  }

  @Test
  public void resetAbandonsAnythingInFlight() {
    CollectionLogSync sync = new CollectionLogSync();
    sync.arm();
    sync.onItemObserved(16, true);

    // An account switch or a logout: the read belongs to the character that started it.
    sync.reset();

    assertFalse(sync.isActive());
    assertEquals(0, sync.observedCount());
    assertNull(sync.onTick(true, true));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

/**
 * What {@code ::bstand help} prints: one line per command, in the same order the
 * dispatcher resolves them, so a player never sees a command listed here that
 * {@code actionFor} does not actually recognise, or vice versa.
 */
public class HelpLinesTest {

  private static boolean mentions(List<String> lines, String needle) {
    return lines.stream().anyMatch((line) -> line.contains(needle));
  }

  @Test
  public void namesEveryRealCommand() {
    List<String> lines = StatusReport.helpLines();
    for (String command : new String[] {
      "::bstand", "::bstand sync", "::bstand link", "::bstand log",
      "::bstand export", "::bstand repair", "::bstand help"
    }) {
      assertTrue("missing " + command, mentions(lines, command));
    }
  }

  /**
   * The guard against the next one. A command added to {@code actionFor} without a
   * matching line here leaves a real command nobody can discover; a line added here
   * for a command that does not exist tells a player to run something that fails.
   * Counting pins the list rather than trusting each name check alone.
   */
  @Test
  public void hasExactlyOneLinePerCommandPlusAHeader() {
    assertEquals(8, StatusReport.helpLines().size());
  }

  @Test
  public void firstLineIsAHeaderNotACommand() {
    assertTrue(StatusReport.helpLines().get(0).toLowerCase().contains("command"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class AckedStateStoreTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private File file;
  private AckedStateStore store;

  @Before
  public void setUp() throws IOException {
    file = new File(folder.getRoot(), "acked.json");
    store = new AckedStateStore(file, new Gson());
  }

  private static Set<Integer> ids(Integer... values) {
    return new LinkedHashSet<>(Arrays.asList(values));
  }

  @Test
  public void aCharacterNothingIsKnownAboutReadsAsEmpty() {
    AckedState state = store.load(1234L);

    assertNull(state.getSkills());
    assertTrue(state.getCollectionLogItems().isEmpty());
    // Not zero. Zero would mean "the server acknowledged an empty log", which is a
    // different claim from never having been told.
    assertEquals(-1, state.getCollectionLogAcked());
  }

  @Test
  public void survivesARoundTrip() {
    AckedState state = AckedState.empty();
    state.setSkills("skills-digest");
    state.setQuests("quests-digest");
    state.setDiaries("diaries-digest");
    state.setCollectionLogItems(ids(1, 2, 3));
    state.setCollectionLogAcked(3);
    Map<String, Long> synced = new LinkedHashMap<>();
    synced.put("skills", 1_700_000_000_000L);
    state.setLastSyncedAt(synced);

    store.save(1234L, state);
    AckedState loaded = new AckedStateStore(file, new Gson()).load(1234L);

    assertEquals("skills-digest", loaded.getSkills());
    assertEquals("quests-digest", loaded.getQuests());
    assertEquals("diaries-digest", loaded.getDiaries());
    assertEquals(ids(1, 2, 3), loaded.getCollectionLogItems());
    assertEquals(3, loaded.getCollectionLogAcked());
    assertEquals(1_700_000_000_000L, (long) loaded.getLastSyncedAt().get("skills"));
  }

  /** A document written before this field existed has none in its JSON at all, not a
   *  null value: Gson leaves the field null on that class, and the store must still
   *  hand out an empty, iterable map rather than propagate the null. */
  @Test
  public void aDocumentMissingLastSyncedAtStillLoads() throws IOException {
    Files.write(
        file.toPath(),
        "{\"accounts\":{\"1234\":{\"skills\":\"only-skills\"}}}".getBytes(StandardCharsets.UTF_8));

    AckedState state = new AckedStateStore(file, new Gson()).load(1234L);

    assertTrue(state.getLastSyncedAt().isEmpty());
  }

  /** A baseline belongs to one character; two on one machine must not see each other's. */
  @Test
  public void keepsCharactersApart() {
    AckedState first = AckedState.empty();
    first.setSkills("first");
    first.setCollectionLogItems(ids(1, 2));
    AckedState second = AckedState.empty();
    second.setSkills("second");
    second.setCollectionLogItems(ids(9));

    store.save(1L, first);
    store.save(2L, second);

    assertEquals("first", store.load(1L).getSkills());
    assertEquals(ids(1, 2), store.load(1L).getCollectionLogItems());
    assertEquals("second", store.load(2L).getSkills());
    assertEquals(ids(9), store.load(2L).getCollectionLogItems());
  }

  @Test
  public void savingOneCharacterLeavesTheOtherAlone() {
    AckedState first = AckedState.empty();
    first.setSkills("first");
    store.save(1L, first);

    AckedState second = AckedState.empty();
    second.setSkills("second");
    store.save(2L, second);

    assertEquals("first", new AckedStateStore(file, new Gson()).load(1L).getSkills());
  }

  @Test
  public void aNegativeAccountHashIsARealAccount() {
    // The account hash is a signed 64-bit value and a negative one is real, which this
    // codebase has already been bitten by once.
    AckedState state = AckedState.empty();
    state.setSkills("negative");

    store.save(-8_234_567_890_123L, state);

    assertEquals("negative", new AckedStateStore(file, new Gson()).load(-8_234_567_890_123L).getSkills());
  }

  /**
   * The safe direction. A file we cannot read means we do not know what the server has,
   * and the only honest answer to that is to send everything again, which costs one
   * redundant submission. Refusing to start, or trusting a half-parsed document, both
   * cost more.
   */
  @Test
  public void treatsAnUnreadableFileAsEmptyRatherThanFailing() throws IOException {
    Files.write(file.toPath(), "{ this is not json".getBytes(StandardCharsets.UTF_8));

    AckedState state = new AckedStateStore(file, new Gson()).load(1234L);

    assertNull(state.getSkills());
    assertEquals(-1, state.getCollectionLogAcked());
  }

  @Test
  public void recoversByOverwritingACorruptFileOnTheNextSave() throws IOException {
    Files.write(file.toPath(), "not json at all".getBytes(StandardCharsets.UTF_8));
    AckedStateStore fresh = new AckedStateStore(file, new Gson());

    AckedState state = AckedState.empty();
    state.setSkills("recovered");
    fresh.save(1234L, state);

    assertEquals("recovered", new AckedStateStore(file, new Gson()).load(1234L).getSkills());
  }

  @Test
  public void aDocumentMissingItsCollectionLogFieldsStillLoads() throws IOException {
    Files.write(
        file.toPath(),
        "{\"accounts\":{\"1234\":{\"skills\":\"only-skills\"}}}".getBytes(StandardCharsets.UTF_8));

    AckedState state = new AckedStateStore(file, new Gson()).load(1234L);

    assertEquals("only-skills", state.getSkills());
    assertTrue(state.getCollectionLogItems().isEmpty());
  }

  @Test
  public void leavesNoTemporaryFileBehind() {
    store.save(1L, AckedState.empty());

    String[] names = folder.getRoot().list();
    assertEquals(1, names.length);
    assertEquals("acked.json", names[0]);
  }

  @Test
  public void createsTheParentDirectoryOnFirstSave() {
    File nested = new File(new File(folder.getRoot(), "bankstand"), "acked.json");
    AckedState state = AckedState.empty();
    state.setSkills("nested");

    new AckedStateStore(nested, new Gson()).save(7L, state);

    assertTrue(nested.exists());
    assertEquals("nested", new AckedStateStore(nested, new Gson()).load(7L).getSkills());
  }

  /** A caller mutating what it loaded must not reach through into the stored document. */
  @Test
  public void handsOutStateTheCallerCannotAliasIntoTheStore() {
    AckedState state = AckedState.empty();
    state.setCollectionLogItems(ids(1, 2));
    store.save(1L, state);

    AckedState loaded = store.load(1L);
    loaded.getCollectionLogItems().add(999);

    assertEquals(ids(1, 2), store.load(1L).getCollectionLogItems());
  }

  @Test
  public void aSavedDigestReplacesTheOneBefore() {
    AckedState first = AckedState.empty();
    first.setSkills("old");
    store.save(1L, first);

    AckedState second = AckedState.empty();
    second.setSkills("new");
    store.save(1L, second);

    assertEquals("new", store.load(1L).getSkills());
    assertNotEquals("old", store.load(1L).getSkills());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class CombatAchievementTierCompletionCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private EventOutbox outboxIn(File file) {
    return new EventOutbox(file, new Gson());
  }

  private File newFile() throws IOException {
    return new File(folder.newFolder("bankstand"), "events.json");
  }

  @Test
  public void emitsOnATierCompletionBroadcast() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementTierCompletionCapture capture =
        new CombatAchievementTierCompletionCapture(outbox, () -> true, () -> 1L);

    // Best-effort guess, NOT verified against a live capture: built from the one documented
    // fragment available (RuneLite's own chat-notification highlight pattern, "has completed the
    // (\w*) tier of the Combat Achievements"). If this test starts failing against a real capture
    // later, the wording is wrong, not the test; update both together, the same way the CA_ID
    // prefix and the @ach_comp@ icon tag were both fixed only after a real live capture.
    capture.handleMessage("Congratulations, you have completed the elite tier of the Combat Achievements!");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("elite", outbox.pending().get(0).getEvent().getPayload().get("tier"));
  }

  @Test
  public void emitsWhenTheBroadcastHasNoTrailingExclamationMark() throws IOException {
    // Same unverified guess as above; the trailing "!" is optional in the pattern because
    // nothing in the one documented fragment confirms it is always present.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementTierCompletionCapture capture =
        new CombatAchievementTierCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you have completed the hard tier of the Combat Achievements");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("hard", outbox.pending().get(0).getEvent().getPayload().get("tier"));
  }

  @Test
  public void ignoresAnUnrecognisedTierWord() throws IOException {
    // Defends against a mis-parse resolving to something outside the six real
    // tiers, which the server's own zod enum would reject anyway, but failing
    // closed here means nothing is even queued for a doomed submission.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementTierCompletionCapture capture =
        new CombatAchievementTierCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you have completed the mythical tier of the Combat Achievements!");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void ignoresAnUnrelatedMessage() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementTierCompletionCapture capture =
        new CombatAchievementTierCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've completed a hard combat task: Whack-a-Mole.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void touchesNothingWhenDisabled() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementTierCompletionCapture capture =
        new CombatAchievementTierCompletionCapture(outbox, () -> false, () -> 1L);

    capture.handleMessage("Congratulations, you have completed the elite tier of the Combat Achievements!");

    assertTrue(outbox.pending().isEmpty());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class PanelPresentationTest {

  @Test
  public void notPairedIsAlwaysGreyWhateverElseIsTrue() {
    assertEquals(
        PanelPresentation.SyncDot.GREY,
        PanelPresentation.resolveDot(false, true, false));
    assertEquals(
        PanelPresentation.SyncDot.GREY,
        PanelPresentation.resolveDot(false, false, true));
  }

  @Test
  public void pairedAndSucceededIsGreen() {
    assertEquals(
        PanelPresentation.SyncDot.GREEN,
        PanelPresentation.resolveDot(true, true, false));
  }

  @Test
  public void pairedAndTheMostRecentAttemptFailedIsAmberEvenAfterAnEarlierSuccess() {
    assertEquals(
        PanelPresentation.SyncDot.AMBER,
        PanelPresentation.resolveDot(true, true, true));
  }

  @Test
  public void pairedButNothingHasEverSucceededIsGreyRatherThanAFalseGreen() {
    assertEquals(
        PanelPresentation.SyncDot.GREY,
        PanelPresentation.resolveDot(true, false, false));
  }

  @Test
  public void underAMinuteReadsAsJustNow() {
    assertEquals("just now", PanelPresentation.formatAge(0));
    assertEquals("just now", PanelPresentation.formatAge(59_999));
  }

  @Test
  public void minutesRoundDown() {
    assertEquals("1m ago", PanelPresentation.formatAge(60_000));
    assertEquals("2m ago", PanelPresentation.formatAge(179_999));
  }

  @Test
  public void hoursTakeOverAtSixtyMinutes() {
    assertEquals("59m ago", PanelPresentation.formatAge(59 * 60_000L));
    assertEquals("1h ago", PanelPresentation.formatAge(60 * 60_000L));
  }

  @Test
  public void daysTakeOverAtTwentyFourHours() {
    assertEquals("23h ago", PanelPresentation.formatAge(23 * 3_600_000L));
    assertEquals("1d ago", PanelPresentation.formatAge(24 * 3_600_000L));
    assertEquals("5d ago", PanelPresentation.formatAge(5 * 24 * 3_600_000L));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.LinkedHashSet;
import org.junit.Test;

public class CollectionLogAccumulatorTest {

  @Test
  public void recordsAnItemOnceAndReportsWhetherItWasNew() {
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    assertTrue(log.observe(11832));
    assertFalse(log.observe(11832));
    assertEquals(1, log.size());
  }

  @Test
  public void accumulatesAcrossReadsRatherThanReplacing() {
    // The whole point. A partial enumeration (one page browsed, a search cancelled)
    // must add to what is known, never become the new truth. Replacing here would
    // discard the rest of the player's log every time they opened a single page.
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(11832);
    log.observe(11834);

    // A later, narrower read that only sees one item.
    log.observe(4151);

    assertEquals(
        new LinkedHashSet<>(Arrays.asList(11832, 11834, 4151)), log.observed());
  }

  @Test
  public void keepsFirstSeenOrder() {
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(3);
    log.observe(1);
    log.observe(2);
    assertEquals(Arrays.asList(3, 1, 2), new java.util.ArrayList<>(log.observed()));
  }

  @Test
  public void resetForgetsEverything() {
    // Called on an account switch. A collection log belongs to one character, and
    // carrying it over would attribute one account's items to another.
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(11832);
    log.reset();
    assertTrue(log.isEmpty());
    assertEquals(0, log.size());
  }

  @Test
  public void exposesAnUnmodifiableView() {
    // Callers build a submission from this; letting them mutate it would corrupt the
    // accumulator without going through observe().
    CollectionLogAccumulator log = new CollectionLogAccumulator();
    log.observe(11832);
    try {
      log.observed().add(999);
      org.junit.Assert.fail("expected the view to be unmodifiable");
    } catch (UnsupportedOperationException expected) {
      // as intended
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class ManifestStoreTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private ManifestStore store(String name) {
    return new ManifestStore(new File(folder.getRoot(), name), new Gson());
  }

  private static CapabilityManifest.RawManifest raw(String json) {
    return new Gson().fromJson(json, CapabilityManifest.RawManifest.class);
  }

  private static final String GOOD =
      "{\"schemaVersion\":1,\"minPluginVersion\":\"0.1.0\","
          + "\"capabilities\":[\"skills\",\"quests\"],\"uploadIntervalSeconds\":300}";

  @Test
  public void roundTripsAManifest() {
    ManifestStore s = store("m.json");
    s.save(raw(GOOD));
    assertEquals(Arrays.asList("skills", "quests"), s.load().capabilities());
  }

  @Test
  public void hasNothingBeforeAnythingIsSaved() {
    assertNull(store("absent.json").load());
  }

  @Test
  public void revalidatesOnTheWayOut() throws Exception {
    // The file is on disk where anything can edit it. A cached manifest naming a
    // capability this build no longer supports must not be honoured just because it was
    // once written by us.
    File f = new File(folder.getRoot(), "tampered.json");
    Files.write(
        f.toPath(),
        ("{\"schemaVersion\":1,\"capabilities\":[\"skills\",\"bank\"],"
                + "\"uploadIntervalSeconds\":1}")
            .getBytes(StandardCharsets.UTF_8));
    CapabilityManifest loaded = new ManifestStore(f, new Gson()).load();
    assertEquals(Arrays.asList("skills"), loaded.capabilities());
    // And the interval is clamped on the way out too, not merely on the way in.
    assertEquals(
        CapabilityManifest.MIN_UPLOAD_INTERVAL_SECONDS, loaded.uploadIntervalSeconds());
  }

  @Test
  public void treatsAnUnreadableFileAsNothingCached() throws Exception {
    File f = new File(folder.getRoot(), "junk.json");
    Files.write(f.toPath(), "not json at all".getBytes(StandardCharsets.UTF_8));
    assertNull(new ManifestStore(f, new Gson()).load());
  }

  @Test
  public void prefersAFreshManifestOverTheCache() {
    ManifestStore s = store("order.json");
    s.save(raw(GOOD));
    CapabilityManifest fresh =
        CapabilityManifest.validate(
            raw("{\"schemaVersion\":1,\"capabilities\":[\"diaries\"],\"uploadIntervalSeconds\":300}"));
    assertEquals(Arrays.asList("diaries"), s.current(fresh).capabilities());
  }

  @Test
  public void fallsBackToTheCacheThenToTheBundle() {
    ManifestStore s = store("fallback.json");
    // Nothing fetched, nothing cached: the compiled-in manifest, so a client that has
    // never reached the server still captures what it was built to capture.
    assertTrue(s.current(null).allows("skills"));
    assertEquals(
        CapabilityManifest.SUPPORTED_CAPABILITIES.size(), s.current(null).capabilities().size());

    // Nothing fetched but something cached: the cache wins over the bundle.
    s.save(raw(GOOD));
    assertEquals(Arrays.asList("skills", "quests"), s.current(null).capabilities());
  }

  @Test
  public void survivesSavingNothing() {
    ManifestStore s = store("null.json");
    s.save(null);
    assertNull(s.load());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Varbits;
import org.junit.Test;

public class CombatAchievementVarbitsTest {

  @Test
  public void coversEveryTierOnce() {
    assertEquals(
        new HashSet<>(
            Arrays.asList("easy", "medium", "hard", "elite", "master", "grandmaster")),
        CombatAchievementVarbits.ALL.keySet());
  }

  @Test
  public void keysAreTheServersWireKeys() {
    // Lowercase, matching the server's CA_TIER_KEYS. An uppercase key would be
    // rejected by the envelope's tier refine, silently dropping the whole block.
    for (String key : CombatAchievementVarbits.ALL.keySet()) {
      assertEquals(key, key.toLowerCase());
    }
  }

  @Test
  public void readsTaskCountsAndNotRewardClaims() {
    // The trap this table exists to avoid. COMBAT_ACHIEVEMENT_TIER_* sit right
    // beside these and track whether the tier's REWARDS were claimed from the
    // taskmaster, which is a different fact: a player can finish every Easy task
    // and never claim, and reading those would report them at zero.
    Set<Integer> rewardVarbits =
        new HashSet<>(
            Arrays.asList(
                Varbits.COMBAT_ACHIEVEMENT_TIER_EASY,
                Varbits.COMBAT_ACHIEVEMENT_TIER_MEDIUM,
                Varbits.COMBAT_ACHIEVEMENT_TIER_HARD,
                Varbits.COMBAT_ACHIEVEMENT_TIER_ELITE,
                Varbits.COMBAT_ACHIEVEMENT_TIER_MASTER));

    for (Integer id : CombatAchievementVarbits.ALL.values()) {
      assertFalse("read a reward-claim varbit, not a task count", rewardVarbits.contains(id));
    }
    assertEquals(
        (Integer) Varbits.COMBAT_TASK_EASY, CombatAchievementVarbits.ALL.get("easy"));
    assertEquals(
        (Integer) Varbits.COMBAT_TASK_GRANDMASTER,
        CombatAchievementVarbits.ALL.get("grandmaster"));
  }

  @Test
  public void everyTierMapsToADistinctVarbit() {
    assertEquals(
        CombatAchievementVarbits.ALL.size(),
        new HashSet<>(CombatAchievementVarbits.ALL.values()).size());
  }

  @Test
  public void baselineOnlyReportsChangeWhenACountMoves() {
    CombatAchievementBaseline baseline = new CombatAchievementBaseline();
    Map<String, Integer> counts = new LinkedHashMap<>();
    counts.put("easy", 23);

    assertTrue("nothing acknowledged yet", baseline.changedSince(counts));
    baseline.advance(counts);
    assertFalse("unchanged since the ack", baseline.changedSince(counts));

    Map<String, Integer> moved = new LinkedHashMap<>();
    moved.put("easy", 24);
    assertTrue(baseline.changedSince(moved));
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public class QuestBaselineTest {
  private static Map<String, String> of(String k, String v) {
    Map<String, String> m = new LinkedHashMap<>();
    m.put(k, v);
    return m;
  }

  @Test
  public void everythingIsChangedAgainstAFreshBaseline() {
    assertTrue(new QuestBaseline().changedSince(of("COOKS_ASSISTANT", "NOT_STARTED")));
  }

  @Test
  public void unchangedAfterAdvance() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    assertFalse(b.changedSince(of("COOKS_ASSISTANT", "NOT_STARTED")));
  }

  @Test
  public void aQuestStateChangeIsAChange() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    assertTrue(b.changedSince(of("COOKS_ASSISTANT", "IN_PROGRESS")));
  }

  @Test
  public void aNewQuestKeyIsAChange() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    Map<String, String> more = of("COOKS_ASSISTANT", "NOT_STARTED");
    more.put("DRAGON_SLAYER_I", "IN_PROGRESS");
    assertTrue(b.changedSince(more));
  }

  @Test
  public void resetForgetsTheBaseline() {
    QuestBaseline b = new QuestBaseline();
    b.advance(of("COOKS_ASSISTANT", "NOT_STARTED"));
    b.reset();
    assertTrue(b.changedSince(of("COOKS_ASSISTANT", "NOT_STARTED")));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * The panel's per-capability rows: same stable order and same skip-when-off rule as
 * {@link CapabilityNamesTest}, plus the row's own last-synced value.
 */
public class CapabilityRowsTest {

  private static Map<String, Long> syncedAt(String key, long ms) {
    Map<String, Long> map = new LinkedHashMap<>();
    map.put(key, ms);
    return map;
  }

  @Test
  public void rowsEveryEnabledCapabilityInTheSameOrderAsCapabilityNames() {
    List<PanelModel.CapabilityRow> rows =
        BankstandPlugin.capabilityRows(
            true, true, true, true, true, true, true, true, new LinkedHashMap<>());

    assertEquals(
        List.of(
            "Skills",
            "Quests",
            "Diaries",
            "Collection log",
            "Combat achievements",
            "Account type",
            "Notable drops",
            "Pet drops"),
        rows.stream().map(row -> row.name).collect(java.util.stream.Collectors.toList()));
  }

  @Test
  public void skipsWhatIsSwitchedOff() {
    List<PanelModel.CapabilityRow> rows =
        BankstandPlugin.capabilityRows(
            true, false, false, false, true, false, false, false, new LinkedHashMap<>());

    assertEquals(
        List.of("Skills", "Combat achievements"),
        rows.stream().map(row -> row.name).collect(java.util.stream.Collectors.toList()));
  }

  @Test
  public void rowsNothingWhenEverythingIsOff() {
    assertTrue(
        BankstandPlugin.capabilityRows(
                false, false, false, false, false, false, false, false, new LinkedHashMap<>())
            .isEmpty());
  }

  @Test
  public void carriesTheLastSyncedTimeForItsOwnKey() {
    List<PanelModel.CapabilityRow> rows =
        BankstandPlugin.capabilityRows(
            true, false, false, false, false, false, false, false, syncedAt("skills", 1_000L));

    assertEquals(1, rows.size());
    assertEquals(1_000L, (long) rows.get(0).lastSyncedAtMs);
  }

  @Test
  public void aNeverSyncedCapabilityCarriesNullRatherThanAFakeTime() {
    List<PanelModel.CapabilityRow> rows =
        BankstandPlugin.capabilityRows(
            true, false, false, false, false, false, false, false, new LinkedHashMap<>());

    assertNull(rows.get(0).lastSyncedAtMs);
  }

  @Test
  public void aCapabilityOnlyReadsItsOwnKeyNeverAnotherOnes() {
    // notableDrops and skills share nothing; a row must not pick up a stray value
    // stored under a different capability's key.
    List<PanelModel.CapabilityRow> rows =
        BankstandPlugin.capabilityRows(
            true, false, false, false, false, false, false, false, syncedAt("notableDrops", 1_000L));

    assertNull(rows.get(0).lastSyncedAtMs);
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class DiaryTaskVarplayersTest {

  @Test
  public void coversTheSame12RegionsAsTheOtherDiaryTables() {
    // A region present in the completion/count tables but missing here would be one
    // DiaryTaskCompletionCapture can never read varplayers for, silently.
    assertEquals(12, DiaryTaskVarplayers.ALL.size());
    Set<String> regionsFromTierKeys = new HashSet<>();
    for (String key : DiaryVarbits.ALL.keySet()) {
      regionsFromTierKeys.add(key.substring(0, key.lastIndexOf('_')));
    }
    assertEquals(regionsFromTierKeys, DiaryTaskVarplayers.ALL.keySet());
  }

  @Test
  public void totalsTwentySevenVarplayers() {
    // 10 regions x 2, plus Kourend & Kebos's extra MULTISTAGE, plus Karamja's four.
    int total = 0;
    for (int[] ids : DiaryTaskVarplayers.ALL.values()) {
      total += ids.length;
    }
    assertEquals(27, total);
  }

  @Test
  public void mostRegionsHaveExactlyTwoVarplayers() {
    for (Map.Entry<String, int[]> e : DiaryTaskVarplayers.ALL.entrySet()) {
      if (e.getKey().equals("KOUREND_KEBOS")) {
        assertEquals(3, e.getValue().length);
      } else if (e.getKey().equals("KARAMJA")) {
        assertEquals(4, e.getValue().length);
      } else {
        assertEquals(e.getKey(), 2, e.getValue().length);
      }
    }
  }

  @Test
  public void namesEachVarplayerOnce() {
    // A copy-paste across regions would make two regions share a varplayer and diff
    // the same bits twice, attributing one account's diary to two regions.
    List<Integer> all = new ArrayList<>();
    for (int[] ids : DiaryTaskVarplayers.ALL.values()) {
      for (int id : ids) {
        all.add(id);
      }
    }
    Set<Integer> seen = new HashSet<>(all);
    assertEquals(all.size(), seen.size());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class CombatAchievementCompletionCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  private EventOutbox outboxIn(File file) {
    return new EventOutbox(file, new Gson());
  }

  private File newFile() throws IOException {
    return new File(folder.newFolder("bankstand"), "events.json");
  }

  @Test
  public void emitsOnACombatTaskCompletionBroadcast() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've completed a hard combat task: Whack-a-Mole.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("hard", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals(
        "Whack-a-Mole", outbox.pending().get(0).getEvent().getPayload().get("taskName"));
  }

  @Test
  public void emitsWhenTheGameTagsTheBroadcastWithACaId() throws IOException {
    // Observed live (2026-08-11): the real broadcast carries a "CA_ID:<n>|" prefix the
    // pattern's ^-anchor didn't account for, so every completion silently failed to
    // capture. Caught by testing against the actual game text, not an assumed wording.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "CA_ID:632|Congratulations, you've completed an easy combat task: Brutus Novice (1"
            + " point).");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("easy", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals(
        "Brutus Novice", outbox.pending().get(0).getEvent().getPayload().get("taskName"));
  }

  @Test
  public void stripsALeadingIconTagFromTheTaskName() throws IOException {
    // Observed live (2026-08-29): the real broadcast can carry a leading "@word@" icon
    // tag directly against the task name, the game's own inline icon-substitution
    // syntax, left raw because the chat line reaches the plugin before the client
    // resolves it. Caught the same way the CA_ID prefix was: an actual live capture,
    // not an assumed wording.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Congratulations, you've completed a medium combat task: @ach_comp@Perfect"
            + " Shellbane.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("medium", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals(
        "Perfect Shellbane", outbox.pending().get(0).getEvent().getPayload().get("taskName"));
  }

  @Test
  public void emitsOnAnIndefiniteArticleAnVariant() throws IOException {
    // "an easy"/"an elite" use the "an" article; the pattern must accept both a/an.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've completed an easy combat task: A Slow Death.");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals("easy", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals(
        "A Slow Death", outbox.pending().get(0).getEvent().getPayload().get("taskName"));
  }

  @Test
  public void stripsAPointsSuffixFromTheTaskName() throws IOException {
    // The clean name is a permanent server-side primary key with no later sync to fix
    // it, so the "(N points)" suffix the game appends must never reach the outbox.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Congratulations, you've completed a grandmaster combat task: No Pressure (6 points).");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals(
        "grandmaster", outbox.pending().get(0).getEvent().getPayload().get("tier"));
    assertEquals(
        "No Pressure", outbox.pending().get(0).getEvent().getPayload().get("taskName"));
  }

  @Test
  public void keepsAPeriodOrParenthesesInsideTheTaskName() throws IOException {
    // Pins the greedy capture group: everything up to the final ". " terminator stays
    // part of the task name, including an internal period or parenthetical aside.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage(
        "Congratulations, you've completed a master combat task: Mr. Ex-Diner (No Seconds).");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals(
        "Mr. Ex-Diner (No Seconds)",
        outbox.pending().get(0).getEvent().getPayload().get("taskName"));
  }

  /** The server validates a whole batch in one schema parse (128-char task-name bound)
   *  and 400s the WHOLE BATCH on any one event failing validation, with the drain
   *  acking nothing on failure: one oversized name would block every other queued
   *  event for the account, forever. Same fix as CollectionLogUnlockCapture's. */
  @Test
  public void skipsAnOversizedTaskName() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);
    String oversizedName = repeat("A", 129);

    capture.handleMessage(
        "Congratulations, you've completed a hard combat task: " + oversizedName + ".");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void emitsATaskNameAtExactlyTheLengthBound() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);
    String boundedName = repeat("A", 128);

    capture.handleMessage(
        "Congratulations, you've completed a hard combat task: " + boundedName + ".");

    assertTrue(!outbox.pending().isEmpty());
  }

  private static String repeat(String s, int times) {
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < times; i++) {
      builder.append(s);
    }
    return builder.toString();
  }

  /** The strip can consume the entire captured group (a double space before the
   *  suffix leaves nothing behind), and an empty name is worse than useless: the
   *  server's min(1) rejects it, and one rejected event in a batch 400s the whole
   *  batch, permanently blocking every other queued event for the account. */
  @Test
  public void doesNotEmitWhenTheTaskNameStripsToEmpty() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've completed a hard combat task:  (1 point).");

    assertTrue(outbox.pending().isEmpty());
  }

  /** A whitespace-only name is min(1)-valid junk, not a real task name, and must be
   *  caught the same way an empty one is. */
  @Test
  public void doesNotEmitAWhitespaceOnlyTaskName() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've completed a hard combat task:    .");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void ignoresAnUnrecognisedTierWord() throws IOException {
    // Defends against a mis-parse resolving to something outside the six real
    // tiers, which the server's own zod enum would reject anyway, but failing
    // closed here means nothing is even queued for a doomed submission.
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've completed a mythical combat task: Nonsense.");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void ignoresAnUnrelatedMessage() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Congratulations, you've reached level 99 in Attack!");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void touchesNothingWhenDisabled() throws IOException {
    EventOutbox outbox = outboxIn(newFile());
    CombatAchievementCompletionCapture capture =
        new CombatAchievementCompletionCapture(outbox, () -> false, () -> 1L);

    capture.handleMessage("Congratulations, you've completed a hard combat task: Whack-a-Mole.");

    assertTrue(outbox.pending().isEmpty());
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

/**
 * What {@code ::bstand export} prints: the current Collect/Events toggle state, plain
 * values so the wording is testable without a live config.
 */
public class ExportLinesTest {

  private static boolean mentions(List<String> lines, String needle) {
    return lines.stream().anyMatch((line) -> line.contains(needle));
  }

  @Test
  public void marksAnEnabledToggleOn() {
    List<String> lines =
        StatusReport.exportLines(true, false, false, false, false, false, false, 1_000_000, false);
    assertTrue(mentions(lines, "Skill XP: on"));
  }

  @Test
  public void marksADisabledToggleOff() {
    List<String> lines =
        StatusReport.exportLines(false, false, false, false, false, false, false, 1_000_000, false);
    assertTrue(mentions(lines, "Skill XP: off"));
  }

  @Test
  public void namesOnePerToggle() {
    // The same guard CapabilityNamesTest already keeps for the status line: a toggle
    // added to the config without being added here silently omits it from the export.
    List<String> lines =
        StatusReport.exportLines(true, true, true, true, true, true, true, 1_000_000, true);
    assertTrue(mentions(lines, "Skill XP"));
    assertTrue(mentions(lines, "Quest progress"));
    assertTrue(mentions(lines, "Diary progress"));
    assertTrue(mentions(lines, "Collection log"));
    assertTrue(mentions(lines, "Combat achievements"));
    assertTrue(mentions(lines, "Account type"));
    assertTrue(mentions(lines, "Notable drops"));
    assertTrue(mentions(lines, "Pet drops"));
  }

  @Test
  public void includesTheNotableDropThreshold() {
    List<String> lines =
        StatusReport.exportLines(false, false, false, false, false, false, false, 250_000, false);
    assertTrue(mentions(lines, "250000"));
  }

  @Test
  public void neverMentionsThePairingCodeDeviceTokenOrServerUrl() {
    // The one hard rule this command exists under: none of the three secrets/identity
    // fields this plugin holds may ever appear in an export meant to be pasted
    // somewhere else.
    List<String> lines =
        StatusReport.exportLines(true, true, true, true, true, true, true, 1_000_000, true);
    for (String line : lines) {
      String lower = line.toLowerCase();
      assertFalse(lower.contains("pairing"));
      assertFalse(lower.contains("token"));
      assertFalse(lower.contains("server"));
    }
  }
}

package com.bankstand;

