package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/**
 * What a capture decides to put on the wire.
 *
 * <p>The old rule was "if anything changed, send everything". That resent the whole
 * collection log, around seventeen hundred ids, on every cycle where a single xp drop
 * moved, which is every cycle a player is training. These tests pin the replacement:
 * a capability rides along only when that capability itself changed.
 */
public class SubmitPlanTest {

  private static Map<String, Integer> skills(String name, int xp) {
    Map<String, Integer> map = new LinkedHashMap<>();
    map.put(name, xp);
    return map;
  }

  private static Map<String, String> states(String key, String value) {
    Map<String, String> map = new LinkedHashMap<>();
    map.put(key, value);
    return map;
  }

  private static final Set<Integer> NO_LOG = Collections.emptySet();

  /** Baselines with everything already acknowledged, so only real changes show up. */
  private static class Acked {
    final SkillBaseline skills = new SkillBaseline();
    final QuestBaseline quests = new QuestBaseline();
    final DiaryBaseline diaries = new DiaryBaseline();
    final CollectionLogBaseline log = new CollectionLogBaseline();

    Acked() {
      skills.advance(SubmitPlanTest.skills("attack", 100));
      quests.advance(states("COOKS_ASSISTANT", "FINISHED"));
      diaries.advance(states("VARROCK_EASY", "COMPLETE"));
      log.advance(2);
    }

    BankstandPlugin.SubmitPlan plan(
        Map<String, Integer> s, Map<String, String> q, Map<String, String> d, Set<Integer> c) {
      return BankstandPlugin.plan(skills, s, quests, q, diaries, d, log, c);
    }
  }

  @Test
  public void sendsNothingWhenNothingMoved() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertFalse(plan.shouldSubmit());
  }

  /**
   * The headline. An xp change submits, and carries only skills: the other three are
   * exactly as the server last acknowledged them, so re-sending them is pure payload.
   */
  @Test
  public void anXpChangeCarriesSkillsAlone() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        acked.plan(
            skills("attack", 200),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertTrue(plan.shouldSubmit());
    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  @Test
  public void aQuestChangeCarriesQuestsAndNotTheOtherRiders() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "IN_PROGRESS"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  @Test
  public void aDiaryChangeCarriesDiariesAlone() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "INCOMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesDiaries());
    assertFalse(plan.includesQuests());
  }

  @Test
  public void aGrownCollectionLogCarriesTheLogAlone() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesCollectionLog());
    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
  }

  @Test
  public void anOptInThatIsOffNeverContributesAndIsNeverSent() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan = acked.plan(skills("attack", 100), null, null, NO_LOG);

    assertFalse(plan.shouldSubmit());
    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  /**
   * A block the server has never acknowledged counts as changed, so it keeps riding
   * along until it is stored. That is what makes an unstored block self-heal the moment
   * its rollout flag comes on, and omitting unchanged blocks must not weaken it.
   */
  @Test
  public void aBlockThatWasNeverAcknowledgedKeepsBeingSent() {
    SkillBaseline skills = new SkillBaseline();
    skills.advance(skills("attack", 100));

    BankstandPlugin.SubmitPlan plan =
        BankstandPlugin.plan(
            skills,
            skills("attack", 100),
            new QuestBaseline(),
            states("COOKS_ASSISTANT", "FINISHED"),
            new DiaryBaseline(),
            states("VARROCK_EASY", "COMPLETE"),
            new CollectionLogBaseline(),
            new java.util.HashSet<>(Arrays.asList(1)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesQuests());
    assertTrue(plan.includesDiaries());
    assertTrue(plan.includesCollectionLog());
  }

  /**
   * An empty block is omitted whatever the baseline says. Absent means "not observed"
   * on this wire, so sending an empty map would assert the player has no quests rather
   * than that nothing was read.
   */
  @Test
  public void anEmptyBlockIsNeverSent() {
    BankstandPlugin.SubmitPlan plan =
        BankstandPlugin.plan(
            new SkillBaseline(),
            skills("attack", 100),
            new QuestBaseline(),
            new LinkedHashMap<>(),
            new DiaryBaseline(),
            new LinkedHashMap<>(),
            new CollectionLogBaseline(),
            NO_LOG);

    assertFalse(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertFalse(plan.includesCollectionLog());
  }

  @Test
  public void severalChangesRideTogether() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        acked.plan(
            skills("attack", 200),
            states("COOKS_ASSISTANT", "IN_PROGRESS"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)));

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesQuests());
    assertFalse(plan.includesDiaries());
    assertTrue(plan.includesCollectionLog());
  }

  /**
   * The combat achievement opt-in is enforced by never reading the counts, so a capture
   * with it off passes an empty map here. Two things must hold for that to be safe.
   *
   * <p>It must not read as "every tier went to zero", and it must not put an empty block
   * on the wire: the server drops an empty block without acknowledging it, so a client
   * that sent one would never advance its baseline and would resubmit forever. The rest
   * of the capture carries on regardless, which is the point of a per-capability opt-in.
   */
  @Test
  public void leavesCombatAchievementsOutWhileTheOptInIsOff() {
    Acked acked = new Acked();
    CombatAchievementBaseline combat = new CombatAchievementBaseline();
    combat.advance(skills("easy", 23));

    BankstandPlugin.SubmitPlan plan =
        BankstandPlugin.plan(
            acked.skills,
            skills("attack", 200),
            acked.quests,
            null,
            acked.diaries,
            null,
            acked.log,
            NO_LOG,
            combat,
            Collections.emptyMap());

    assertFalse(plan.includesCombatAchievements());
    assertTrue(plan.shouldSubmit());
  }

  /**
   * The case #466 exists for: a COMPLETE guided read that revealed zero new ids, because
   * the account's partial reads had already, coincidentally, covered everything a full
   * search would show. Without the pending signal counting toward the decision, this
   * capture would carry no collection log block at all and the completeness fact would
   * never reach the server.
   */
  @Test
  public void aCompleteEnumerationCarriesTheLogEvenWithNoNewItems() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        BankstandPlugin.plan(
            acked.skills,
            skills("attack", 100),
            acked.quests,
            states("COOKS_ASSISTANT", "FINISHED"),
            acked.diaries,
            states("VARROCK_EASY", "COMPLETE"),
            acked.log,
            new java.util.HashSet<>(Arrays.asList(1, 2)),
            new CombatAchievementBaseline(),
            null,
            new AccountTypeBaseline(),
            null,
            true);

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesCollectionLog());
    assertTrue(plan.includesFullEnumeration());
  }

  /**
   * The pending signal cannot manufacture a block out of nothing: a genuinely empty
   * account has no collection log to attach the fact to, the same "empty means not
   * observed" limitation every other capability already accepts.
   */
  @Test
  public void aPendingEnumerationNeverCarriesAnEmptyLog() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        BankstandPlugin.plan(
            acked.skills,
            skills("attack", 200),
            acked.quests,
            states("COOKS_ASSISTANT", "FINISHED"),
            acked.diaries,
            states("VARROCK_EASY", "COMPLETE"),
            new CollectionLogBaseline(),
            NO_LOG,
            new CombatAchievementBaseline(),
            null,
            new AccountTypeBaseline(),
            null,
            true);

    assertFalse(plan.includesCollectionLog());
    assertFalse(plan.includesFullEnumeration());
  }

  /**
   * An ordinary grown log, with no enumeration pending, must not claim one it was never
   * told about.
   */
  @Test
  public void anOrdinaryLogChangeNeverClaimsFullEnumeration() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        BankstandPlugin.plan(
            acked.skills,
            skills("attack", 100),
            acked.quests,
            states("COOKS_ASSISTANT", "FINISHED"),
            acked.diaries,
            states("VARROCK_EASY", "COMPLETE"),
            acked.log,
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)),
            new CombatAchievementBaseline(),
            null,
            new AccountTypeBaseline(),
            null,
            false);

    assertTrue(plan.includesCollectionLog());
    assertFalse(plan.includesFullEnumeration());
  }

  /** The pre-#466 overload still omits the signal entirely, as every existing caller does. */
  @Test
  public void theShorterOverloadNeverClaimsFullEnumeration() {
    Acked acked = new Acked();

    BankstandPlugin.SubmitPlan plan =
        acked.plan(
            skills("attack", 100),
            states("COOKS_ASSISTANT", "FINISHED"),
            states("VARROCK_EASY", "COMPLETE"),
            new java.util.HashSet<>(Arrays.asList(1, 2, 3)));

    assertTrue(plan.includesCollectionLog());
    assertFalse(plan.includesFullEnumeration());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import org.junit.Test;

public class IdentityNoticeTest {

  @Test
  public void confirmsTheLinkedCharacterWhenVerified() {
    assertEquals(
        "Verified as B0aty.",
        BankstandPlugin.identityNoticeFor(true, "B0aty", "bound"));
  }

  @Test
  public void saysNotClaimedWhenTheNameMatchesNoClaim() {
    assertEquals(
        "This character is not claimed on Bankstand yet, so nothing will sync."
            + " Claim it on your account page.",
        BankstandPlugin.identityNoticeFor(false, null, "no_claim"));
  }

  /**
   * The exact defect the incident behind #608 reported: a claimed character told
   * the player to claim it, which sent them in circles across three pairing
   * attempts. A contested binding gets its own message with a different remedy.
   */
  @Test
  public void saysAlreadyLinkedRatherThanNotClaimedWhenAnotherAccountHoldsIt() {
    String message = BankstandPlugin.identityNoticeFor(false, null, "held_by_other");
    assertEquals(
        "This character is already linked, so there is nothing to claim here."
            + " If that looks wrong, contact support.",
        message);
    assertFalse(message.toLowerCase().contains("not claimed"));
  }

  @Test
  public void saysAlreadyLinkedWhenThisAccountHashBindsADifferentCharacter() {
    assertEquals(
        "This character is already linked, so there is nothing to claim here."
            + " If that looks wrong, contact support.",
        BankstandPlugin.identityNoticeFor(false, null, "hash_bound_elsewhere"));
  }

  /**
   * Additive-field compatibility (#753): a server this build predates never sends
   * `outcome` at all, and a future outcome this build does not recognise falls
   * back the same way. Both must keep behaving exactly as the pre-#608 client did,
   * never silently drop the notice or throw on a null/unrecognised value.
   */
  @Test
  public void fallsBackToNotClaimedForAMissingOrUnrecognisedOutcome() {
    assertEquals(
        "This character is not claimed on Bankstand yet, so nothing will sync."
            + " Claim it on your account page.",
        BankstandPlugin.identityNoticeFor(false, null, null));
    assertEquals(
        "This character is not claimed on Bankstand yet, so nothing will sync."
            + " Claim it on your account page.",
        BankstandPlugin.identityNoticeFor(false, null, "a_future_outcome_this_build_predates"));
  }

  @Test
  public void carriesNoEmDash() {
    for (String outcome :
        new String[] {"bound", "no_account", "no_display_name", "no_claim", "held_by_other",
            "hash_bound_elsewhere", null, "unknown"}) {
      assertFalse(
          BankstandPlugin.identityNoticeFor(false, "B0aty", outcome).contains("—"));
    }
    assertFalse(BankstandPlugin.identityNoticeFor(true, "B0aty", "bound").contains("—"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.bankstand.BankstandPlugin.CommandAction;
import org.junit.Test;

/**
 * Covers the pure half of {@code ::bstand} dispatch (#834): which command string is ours,
 * and which action word resolves to which {@link CommandAction}. What each action actually
 * does (armCollectionLogRead, requestManualCapture, ...) still needs a live Client/
 * ConfigManager and stays outside this file's reach, same as before this split.
 */
public class CommandDispatchTest {

  @Test
  public void recognisesTheMainCommandName() {
    assertTrue(BankstandPlugin.isBankstandCommand("bstand"));
  }

  @Test
  public void recognisesTheAliasCommandName() {
    assertTrue(BankstandPlugin.isBankstandCommand("stand"));
  }

  @Test
  public void commandNameMatchingIsCaseInsensitive() {
    assertTrue(BankstandPlugin.isBankstandCommand("BSTAND"));
    assertTrue(BankstandPlugin.isBankstandCommand("Stand"));
  }

  @Test
  public void ignoresAnUnrelatedCommandName() {
    assertFalse(BankstandPlugin.isBankstandCommand("bank"));
  }

  @Test
  public void defaultsToStatusWithNoArguments() {
    assertEquals(CommandAction.STATUS, BankstandPlugin.actionFor(new String[0]));
  }

  @Test
  public void resolvesEveryNamedAction() {
    assertEquals(CommandAction.STATUS, BankstandPlugin.actionFor(new String[] {"status"}));
    assertEquals(CommandAction.SYNC, BankstandPlugin.actionFor(new String[] {"sync"}));
    assertEquals(CommandAction.LINK, BankstandPlugin.actionFor(new String[] {"link"}));
    assertEquals(CommandAction.LOG, BankstandPlugin.actionFor(new String[] {"log"}));
    assertEquals(CommandAction.REPAIR, BankstandPlugin.actionFor(new String[] {"repair"}));
    assertEquals(CommandAction.EXPORT, BankstandPlugin.actionFor(new String[] {"export"}));
    assertEquals(CommandAction.HELP, BankstandPlugin.actionFor(new String[] {"help"}));
  }

  @Test
  public void commandsIsAnAliasForHelp() {
    // "help" is the conventional word; "commands" is the one a player reaching for
    // a full list is just as likely to try first. Same listing either way.
    assertEquals(CommandAction.HELP, BankstandPlugin.actionFor(new String[] {"commands"}));
  }

  @Test
  public void actionWordMatchingIsCaseInsensitive() {
    assertEquals(CommandAction.SYNC, BankstandPlugin.actionFor(new String[] {"SYNC"}));
    assertEquals(CommandAction.LOG, BankstandPlugin.actionFor(new String[] {"Log"}));
  }

  @Test
  public void resolvesAnUnrecognisedActionWordToUnknown() {
    assertEquals(CommandAction.UNKNOWN, BankstandPlugin.actionFor(new String[] {"nonsense"}));
  }

  @Test
  public void ignoresArgumentsPastTheFirst() {
    // A stray extra word (a typo'd second argument, say) must not change which
    // action runs; only the first word is the action.
    assertEquals(
        CommandAction.SYNC, BankstandPlugin.actionFor(new String[] {"sync", "now", "please"}));
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class CollectionLogBaselineTest {

  @Test
  public void reportsAChangeUntilTheServerAcknowledges() {
    CollectionLogBaseline b = new CollectionLogBaseline();
    assertTrue(b.changedSince(12));
    b.advance(12);
    assertFalse(b.changedSince(12));
  }

  @Test
  public void reportsAChangeWhenTheLogGrows() {
    CollectionLogBaseline b = new CollectionLogBaseline();
    b.advance(12);
    assertTrue(b.changedSince(13));
  }

  @Test
  public void neverReportsAChangeForAnEmptyLog() {
    // Nothing observed is not the same as nothing owned. Submitting here would send
    // an empty block, which the server reads as "not observed" anyway, so it would
    // be pure noise on every capture for a player who never opens their log.
    CollectionLogBaseline b = new CollectionLogBaseline();
    assertFalse(b.changedSince(0));
  }

  @Test
  public void resendsAfterAResetSoAnAccountSwitchStartsClean() {
    CollectionLogBaseline b = new CollectionLogBaseline();
    b.advance(12);
    b.reset();
    assertTrue(b.changedSince(12));
  }

  @Test
  public void doesNotAdvanceOnAnUnacknowledgedSubmit() {
    // The baseline only moves when the server says it stored the block, so a dropped
    // submit is retried rather than silently forgotten.
    CollectionLogBaseline b = new CollectionLogBaseline();
    assertTrue(b.changedSince(5));
    assertTrue(b.changedSince(5));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SubmitGateTest {

  private static void failAndSkipPast(SubmitGate gate) {
    gate.onFailure();
    while (!gate.allow()) {
      // Burn the backoff.
    }
  }

  @Test
  public void allowsACaptureWhenNothingHasGoneWrong() {
    SubmitGate gate = new SubmitGate();

    assertTrue(gate.allow());
    assertTrue(gate.allow());
  }

  /**
   * The gap this exists for. A revoked token fails fast inside a submit, and without a
   * latch the next capture tries again 60 seconds later, forever, while NoticeGate keeps
   * the player from ever hearing about it twice.
   */
  @Test
  public void stopsForeverOnARevokedToken() {
    SubmitGate gate = new SubmitGate();

    gate.onAuthFailure();

    assertTrue(gate.isHalted());
    for (int capture = 0; capture < 100; capture++) {
      assertFalse(gate.allow());
    }
  }

  @Test
  public void aRevokedTokenIsAnnouncedOnceRatherThanEveryCapture() {
    SubmitGate gate = new SubmitGate();

    assertTrue(gate.onAuthFailure());
    assertFalse(gate.onAuthFailure());
  }

  @Test
  public void resumingAfterAReRepairLetsCapturesThrough() {
    SubmitGate gate = new SubmitGate();
    gate.onAuthFailure();

    gate.resume();

    assertFalse(gate.isHalted());
    assertTrue(gate.allow());
  }

  @Test
  public void backsOffAfterAFailureRatherThanRetryingEveryCapture() {
    SubmitGate gate = new SubmitGate();

    gate.onFailure();

    assertFalse(gate.allow());
  }

  @Test
  public void backsOffFurtherTheLongerItKeepsFailing() {
    SubmitGate gate = new SubmitGate();
    int previous = 0;
    for (int round = 1; round <= 4; round++) {
      gate.onFailure();
      int skipped = 0;
      while (!gate.allow()) {
        skipped++;
      }
      assertTrue(
          "round " + round + " skipped " + skipped + ", previous " + previous, skipped > previous);
      previous = skipped;
    }
  }

  /** Bounded, so an all-night outage does not turn into an all-week one. */
  @Test
  public void neverBacksOffPastTheCap() {
    SubmitGate gate = new SubmitGate();
    for (int round = 0; round < 50; round++) {
      gate.onFailure();
    }
    int skipped = 0;
    while (!gate.allow()) {
      skipped++;
    }

    assertEquals(SubmitGate.MAX_SKIPPED_CAPTURES, skipped);
  }

  @Test
  public void oneSuccessClearsTheBackoffCompletely() {
    SubmitGate gate = new SubmitGate();
    for (int round = 0; round < 5; round++) {
      gate.onFailure();
    }

    gate.onSuccess();

    assertTrue(gate.allow());
    assertTrue(gate.allow());
  }

  @Test
  public void aFailureAfterARecoveryStartsFromTheShortestBackoffAgain() {
    SubmitGate gate = new SubmitGate();
    for (int round = 0; round < 5; round++) {
      gate.onFailure();
    }
    gate.onSuccess();
    failAndSkipPast(gate);

    // Back to the first rung, not the fifth: the server proved it was reachable.
    SubmitGate fresh = new SubmitGate();
    fresh.onFailure();
    int freshSkips = 0;
    while (!fresh.allow()) {
      freshSkips++;
    }
    gate.onSuccess();
    gate.onFailure();
    int afterRecoverySkips = 0;
    while (!gate.allow()) {
      afterRecoverySkips++;
    }

    assertEquals(freshSkips, afterRecoverySkips);
  }

  /** A halt outranks a backoff: re-pairing is the only thing that clears it. */
  @Test
  public void aBackoffElapsingDoesNotUnhaltARevokedToken() {
    SubmitGate gate = new SubmitGate();
    gate.onFailure();
    gate.onAuthFailure();

    for (int capture = 0; capture < 50; capture++) {
      assertFalse(gate.allow());
    }
  }

  @Test
  public void aSuccessDoesNotSilentlyUnhaltARevokedToken() {
    SubmitGate gate = new SubmitGate();
    gate.onAuthFailure();

    // Nothing can succeed while halted, but if the caller ever ordered these wrongly a
    // silent unhalt would resume submitting with a token the server already rejected.
    gate.onSuccess();

    assertTrue(gate.isHalted());
    assertFalse(gate.allow());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class PairingCodesTest {

  @Test
  public void upperCasesAndStripsWhitespaceAndDash() {
    assertEquals("ABCDEFGH", PairingCodes.normalize("abcd-efgh"));
    assertEquals("ABCDEFGH", PairingCodes.normalize("  ABCD EFGH "));
  }

  @Test
  public void foldsCrockfordLookAlikesLikeTheServer() {
    // O -> 0, I -> 1, L -> 1, matching the server's normalizePairingCode.
    assertEquals("001111", PairingCodes.normalize("OoIiLl"));
  }

  @Test
  public void nullNormalizesToEmpty() {
    assertEquals("", PairingCodes.normalize(null));
  }

  @Test
  public void validityRequiresEightCrockfordChars() {
    assertTrue(PairingCodes.isValid("ABCD1234"));
    assertFalse(PairingCodes.isValid("ABCD123")); // too short
    assertFalse(PairingCodes.isValid("ABCD12345")); // too long
    assertFalse(PairingCodes.isValid("ABCDEFGU")); // U is not in the alphabet
    assertFalse(PairingCodes.isValid(null));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import org.junit.Test;

/**
 * The decision behind the panel's per-capability sync times and recent-activity
 * lines, kept separate from the live submit wiring for the same reason {@code
 * shouldAdvanceX} is: it is testable here, on plain flags, without a live client.
 */
public class SyncedCapabilitiesThisCycleTest {

  private static Map<String, String> synced(
      boolean skillsAdvanced,
      boolean skillsChanged,
      boolean questsAdvanced,
      boolean diariesAdvanced,
      boolean collectionLogAdvanced,
      boolean combatAchievementsAdvanced,
      boolean accountTypeAdvanced) {
    return BankstandPlugin.syncedCapabilitiesThisCycle(
        skillsAdvanced,
        skillsChanged,
        questsAdvanced,
        diariesAdvanced,
        collectionLogAdvanced,
        combatAchievementsAdvanced,
        accountTypeAdvanced);
  }

  @Test
  public void nothingAdvancedMeansNothingSynced() {
    assertTrue(synced(false, false, false, false, false, false, false).isEmpty());
  }

  /**
   * The case this method exists for. Skills rides along on every submission whatever
   * triggered it, so the server storing the block again is not itself proof that xp
   * moved: a diary tier completing alone can advance skills too, and that must not
   * read as "Skills synced".
   */
  @Test
  public void skillsAdvancedWithNoActualChangeIsNotReportedAsSynced() {
    Map<String, String> result = synced(true, false, false, false, false, false, false);

    assertFalse(result.containsKey("skills"));
  }

  @Test
  public void skillsAdvancedWithARealChangeIsReportedWithItsOwnLine() {
    Map<String, String> result = synced(true, true, false, false, false, false, false);

    assertEquals("Skills synced", result.get("skills"));
  }

  /** Unlike skills, an advanced quests/diaries/accountType flag already means "this
   *  specific capability changed": submitSnapshot only receives a non-null value for
   *  one of those when plan() decided it had, so no separate changed flag is needed. */
  @Test
  public void questsDiariesAndAccountTypeEachGetTheirOwnLineWhenAdvanced() {
    Map<String, String> result = synced(false, false, true, true, false, false, true);

    assertEquals("Quests synced", result.get("quests"));
    assertEquals("Diaries synced", result.get("diaries"));
    assertEquals("Account type synced", result.get("accountType"));
  }

  /** The collection log and combat achievements still get a fresh sync time, just no
   *  generic line: their own chat-triggered captures already contribute a more
   *  specific one the moment an item or task is observed. */
  @Test
  public void collectionLogAndCombatAchievementsGetATimeButNoLine() {
    Map<String, String> result = synced(false, false, false, false, true, true, false);

    assertTrue(result.containsKey("collectionLog"));
    assertNull(result.get("collectionLog"));
    assertTrue(result.containsKey("combatAchievements"));
    assertNull(result.get("combatAchievements"));
  }

  @Test
  public void everythingAdvancingReportsAllSixCapabilities() {
    Map<String, String> result = synced(true, true, true, true, true, true, true);

    assertEquals(6, result.size());
  }
}

