        BankstandPlugin.capabilityNames(
                false, false, false, false, false, false, false, false)
            .isEmpty());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

public class DiaryTaskVarbitsTest {

  @Test
  public void coversTheSame48TiersAsTheCompletionTable() {
    // The two halves describe the same tiers. A key in one and not the other would be a
    // tier whose count could never be joined to its completion flag, and the join is the
    // whole point: 21 of 22 is only meaningful next to "not complete".
    assertEquals(DiaryVarbits.ALL.keySet(), DiaryTaskVarbits.ALL.keySet());
    assertEquals(48, DiaryTaskVarbits.ALL.size());
  }

  @Test
  public void readsADifferentVarbitFromTheCompletionFlag() {
    // The game keeps three varbits per tier. Reading the completion flag here would make
    // every tier report 0 or 1 tasks, which is worse than reporting nothing.
    for (Map.Entry<String, Integer> e : DiaryTaskVarbits.ALL.entrySet()) {
      assertNotEquals(e.getKey(), DiaryVarbits.ALL.get(e.getKey()), e.getValue());
    }
  }

  @Test
  public void namesEachVarbitOnce() {
    // A copy-paste inside a region would make two tiers share a count and report the
    // same number for both, which reads as real data.
    Set<Integer> seen = new HashSet<>(DiaryTaskVarbits.ALL.values());
    assertEquals(DiaryTaskVarbits.ALL.size(), seen.size());
  }

  @Test
  public void keepsKaramjaOutsideTheBlockWhereTheGamePutIt() {
    // Karamja's diary predates the 6288-6330 block, so its easy count is at 2423. Far
    // enough away to look like a mistake, which is why it is pinned.
    assertEquals(Integer.valueOf(2423), DiaryTaskVarbits.ALL.get("KARAMJA_EASY"));
    for (Map.Entry<String, Integer> e : DiaryTaskVarbits.ALL.entrySet()) {
      if (e.getKey().equals("KARAMJA_EASY")) {
        continue;
      }
      assertTrue(e.getKey() + " = " + e.getValue(), e.getValue() >= 6288);
    }
  }

  @Test
  public void usesTheWireKeysAndNotTheRuneliteNames() {
    // Three regions are spelled differently on the wire, and the tier is MEDIUM here
    // where VarbitID says MED. Getting either wrong silently drops a whole region.
    assertTrue(DiaryTaskVarbits.ALL.containsKey("KOUREND_KEBOS_ELITE"));
    assertTrue(DiaryTaskVarbits.ALL.containsKey("LUMBRIDGE_DRAYNOR_MEDIUM"));
    assertTrue(DiaryTaskVarbits.ALL.containsKey("WESTERN_PROVINCES_HARD"));
    for (String key : DiaryTaskVarbits.ALL.keySet()) {
      assertTrue(key, key.endsWith("_EASY") || key.endsWith("_MEDIUM")
          || key.endsWith("_HARD") || key.endsWith("_ELITE"));
    }
  }
}

package com.bankstand;

import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;
import org.junit.Test;

/**
 * Keeps the device token out of {@code ConfigManager}.
 *
 * <p>{@code ConfigManager.saveConfiguration} checks {@code ConfigProfile.isSync()} and,
 * when true, PATCHes the whole changed key set to RuneLite's own config service. There is
 * no per-key exclusion, so one {@code setConfiguration} call with the token in it uploads
 * a bearer credential for the Bankstand submit API to a third party the player never
 * authorised for it.
 *
 * <p>It also breaks multi-client accounts, which is the part a reviewer would not catch.
 * The server keys one {@code plugin_device} row per token, so two machines sharing one
 * synced token are one device: one name, one last-seen time, and revoking either revokes
 * both.
 *
 * <p>Source-scanning rather than behavioural, in the same spirit as
 * {@link NoAutomationApiTest}, because the constraint is a call that must not appear.
 * Reading the keys is still allowed, and has to be: the migration reads them once to move
 * an old pairing into the file, and then unsets them so the synced copy is deleted
 * upstream rather than merely ignored.
 */
public class NoCredentialsInConfigTest {

  private static final Path SOURCE_ROOT = Paths.get("src", "main", "java");

  /** The keys that hold a credential. Never written through config, only read and unset. */
  private static final String[] CREDENTIAL_KEYS = {
    "KEY_DEVICE_TOKEN", "KEY_DEVICE_ID", "KEY_TOKEN_EXPIRES_AT",
  };

  @Test
  public void noCredentialIsWrittenThroughConfigManager() throws IOException {
    List<String> offences = new ArrayList<>();
    try (Stream<Path> files = Files.walk(SOURCE_ROOT)) {
      for (Path file :
          (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        for (int i = 0; i < lines.size(); i++) {
          String line = lines.get(i);
          if (isComment(line)) {
            continue;
          }
          // `unsetConfiguration` contains `setConfiguration`, and unsetting is the
          // opposite of the thing banned here: it is what deletes the synced copy.
          if (!line.contains(".setConfiguration")) {
            continue;
          }
          // The call and its key can sit on separate lines once formatted, so the key
          // is looked for on the same line or the next one.
          String window = line + (i + 1 < lines.size() ? lines.get(i + 1) : "");
          for (String key : CREDENTIAL_KEYS) {
            if (window.contains(key)) {
              offences.add(file + ":" + (i + 1) + "  " + line.trim());
            }
          }
        }
      }
    }
    assertTrue(
        "A device credential must never reach ConfigManager: a synced profile uploads it"
            + " to RuneLite, and a shared token collapses several clients into one"
            + " device. Use DeviceCredentialStore.\n"
            + String.join("\n", offences),
        offences.isEmpty());
  }

  private static boolean isComment(String line) {
    String trimmed = line.trim();
    return trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*");
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** No RuneLite or game dependency: a plain bounded list and a plain string builder,
 *  matching the "testable without a client" philosophy {@link StatusReport} already
 *  uses for its own wording. */
public class RecentActivityLogTest {

  @Test
  public void startsEmpty() {
    assertTrue(new RecentActivityLog().recent().isEmpty());
  }

  @Test
  public void newestEntryComesFirst() {
    RecentActivityLog log = new RecentActivityLog();
    log.record("first");
    log.record("second");

    assertEquals(List.of("second", "first"), descriptions(log.recent()));
  }

  @Test
  public void evictsTheOldestOnceFull() {
    RecentActivityLog log = new RecentActivityLog();
    for (int i = 0; i < RecentActivityLog.MAX_ENTRIES + 3; i++) {
      log.record("entry-" + i);
    }

    List<PanelModel.ActivityRow> recent = log.recent();

    assertEquals(RecentActivityLog.MAX_ENTRIES, recent.size());
    // Newest first, and the three oldest ("entry-0".."entry-2") are gone.
    assertEquals("entry-" + (RecentActivityLog.MAX_ENTRIES + 2), recent.get(0).description);
    assertEquals("entry-3", recent.get(recent.size() - 1).description);
  }

  @Test
  public void recentIsASnapshotNotALiveView() {
    RecentActivityLog log = new RecentActivityLog();
    log.record("first");

    List<PanelModel.ActivityRow> snapshot = log.recent();
    log.record("second");

    assertEquals(List.of("first"), descriptions(snapshot));
  }

  @Test
  public void stampsEachEntryWithWhenItWasRecorded() {
    RecentActivityLog log = new RecentActivityLog();
    long before = System.currentTimeMillis();
    log.record("first");
    long after = System.currentTimeMillis();

    long atMs = log.recent().get(0).atMs;
    assertTrue(atMs >= before && atMs <= after);
  }

  private static List<String> descriptions(List<PanelModel.ActivityRow> rows) {
    List<String> out = new ArrayList<>();
    for (PanelModel.ActivityRow row : rows) {
      out.add(row.description);
    }
    return out;
  }

  @Test
  public void clearForgetsEverything() {
    RecentActivityLog log = new RecentActivityLog();
    log.record("first");

    log.clear();

    assertTrue(log.recent().isEmpty());
  }

  private static Map<String, Object> payload(String... keyValuePairs) {
    Map<String, Object> payload = new LinkedHashMap<>();
    for (int i = 0; i < keyValuePairs.length; i += 2) {
      payload.put(keyValuePairs[i], keyValuePairs[i + 1]);
    }
    return payload;
  }

  @Test
  public void describesACollectionLogUnlockByItsItemName() {
    assertEquals(
        "Collection log: Dragon warhammer",
        RecentActivityLog.describe(
            TransientEvent.TYPE_COLLECTION_LOG_UNLOCK, payload("itemName", "Dragon warhammer")));
  }

  @Test
  public void describesACombatAchievementByItsTaskName() {
    assertEquals(
        "Combat achievements: Reflection completed",
        RecentActivityLog.describe(
            TransientEvent.TYPE_COMBAT_ACHIEVEMENT_COMPLETED,
            payload("tier", "master", "taskName", "Reflection")));
  }

  @Test
  public void describesADiaryTaskWithATitleCasedTier() {
    assertEquals(
        "Diaries: Elite task completed in Western Provinces",
        RecentActivityLog.describe(
            TransientEvent.TYPE_DIARY_TASK_COMPLETED,
            payload("tier", "elite", "area", "Western Provinces")));
  }

  @Test
  public void describesANotableDropByItsItemName() {
    assertEquals(
        "Notable drop: Twisted bow",
        RecentActivityLog.describe(TransientEvent.TYPE_NOTABLE_DROP, payload("itemName", "Twisted bow")));
  }

  @Test
  public void describesAPetDropByItsPetName() {
    assertEquals(
        "Pet drop: Baby mole",
        RecentActivityLog.describe(TransientEvent.TYPE_PET_DROP, payload("petName", "Baby mole")));
  }

  @Test
  public void anUnknownTypeDescribesAsNullRatherThanABlankLine() {
    assertNull(RecentActivityLog.describe("some_future_event", payload()));
  }
}

