package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import org.junit.Test;

/**
 * The account type as a capability, end to end on the client side.
 *
 * <p>It is the one block where a missed acknowledgement can never self-heal. Every other
 * capability describes something that moves again later, so a baseline advanced in error
 * is corrected by the next real change; an account's type changes once if ever, so a
 * wrong baseline is permanent. That is the same shape that made the collection log's
 * missing ack a live bug rather than a slow one.
 */
public class AccountTypeCaptureTest {

  private static final Set<Integer> NO_LOG = Collections.emptySet();

  private static Map<String, Integer> skills(int xp) {
    Map<String, Integer> map = new LinkedHashMap<>();
    map.put("attack", xp);
    return map;
  }

  /** Baselines with everything else already acknowledged, so only the type can move. */
  private static BankstandPlugin.SubmitPlan planWith(
      AccountTypeBaseline baseline, String accountType) {
    SkillBaseline skillBaseline = new SkillBaseline();
    skillBaseline.advance(skills(100));
    return BankstandPlugin.plan(
        skillBaseline,
        skills(100),
        new QuestBaseline(),
        null,
        new DiaryBaseline(),
        null,
        new CollectionLogBaseline(),
        NO_LOG,
        new CombatAchievementBaseline(),
        null,
        baseline,
        accountType);
  }

  @Test
  public void submitsOnTheTypeAloneWhenNothingElseMoved() {
    // Has to count toward the decision on its own. The type is read at login and never
    // changes after, so a capture waiting on xp would leave a Group Ironman reading as a
    // main until they happened to train something.
    BankstandPlugin.SubmitPlan plan = planWith(new AccountTypeBaseline(), "group");

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesAccountType());
  }

  @Test
  public void staysQuietOnceTheServerHasAcknowledgedIt() {
    AccountTypeBaseline acked = new AccountTypeBaseline();
    acked.advance("group");

    BankstandPlugin.SubmitPlan plan = planWith(acked, "group");

    assertFalse(plan.shouldSubmit());
    assertFalse(plan.includesAccountType());
  }

  @Test
  public void sendsAgainWhenTheAnswerChanges() {
    // A hardcore ironman dying is the case that matters: the account really does become
    // a different type, and it is the single most consequential state change it has.
    AccountTypeBaseline acked = new AccountTypeBaseline();
    acked.advance("hardcore");

    BankstandPlugin.SubmitPlan plan = planWith(acked, "ironman");

    assertTrue(plan.shouldSubmit());
    assertTrue(plan.includesAccountType());
  }

  @Test
  public void sendsNothingWhenTheGameNamedNoType() {
    // Null is an unrecognised varbit value or the opt-in being off. Both mean "not
    // observed", and neither is a reason to submit.
    assertFalse(planWith(new AccountTypeBaseline(), null).shouldSubmit());
    assertFalse(planWith(new AccountTypeBaseline(), "").shouldSubmit());
  }

  @Test
  public void advancesOnlyOnThisBlocksOwnAcknowledgement() {
    // The whole-submission verdict is decided by skills freshness, so it reads stored
    // even when the server dropped this block behind its rollout flag. Advancing on it
    // would lose the fact outright: there is no later value to force a resend.
    assertTrue(
        BankstandPlugin.shouldAdvanceAccountType(response("persisted", true, "accountType"), true));
    assertFalse(
        BankstandPlugin.shouldAdvanceAccountType(response("persisted", true, "skills"), true));
  }

  @Test
  public void neverAdvancesForABlockItDidNotSend() {
    assertFalse(
        BankstandPlugin.shouldAdvanceAccountType(
            response("persisted", true, "accountType"), false));
  }

  @Test
  public void survivesARestartThroughTheAckedState() {
    // Without this the client resends the same word on every capture forever, which is
    // the failure that self-heals for xp and does not for a one-shot fact.
    AccountTypeBaseline baseline = new AccountTypeBaseline();
    baseline.advance("unranked_group");

    AckedState state = new AckedState();
    state.setAccountType(baseline.ackedValue());

    AccountTypeBaseline restored = new AccountTypeBaseline();
    restored.restore(state.getAccountType());

    assertEquals("unranked_group", restored.ackedValue());
    assertFalse(restored.changedSince("unranked_group"));
  }

  @Test
  public void forgetsTheTypeOnAnAccountSwitch() {
    // A type belongs to one character. Carrying it across would let one account's answer
    // stand in for another's, which for a group account is the whole point of the read.
    AccountTypeBaseline baseline = new AccountTypeBaseline();
    baseline.advance("ironman");
    baseline.reset();

    assertTrue(baseline.changedSince("group"));
    assertEquals(null, baseline.ackedValue());
  }

  private static com.bankstand.dto.SubmitSnapshotResponse response(
      String reason, boolean stored, String... blocks) {
    return new com.google.gson.Gson()
        .fromJson(
            "{\"accepted\":true,\"stored\":"
                + stored
                + ",\"reason\":\""
                + reason
                + "\",\"storedBlocks\":[\""
                + String.join("\",\"", blocks)
                + "\"]}",
            com.bankstand.dto.SubmitSnapshotResponse.class);
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Stream;
import org.junit.Test;

/**
 * Derives the gated capability set from the actual call sites, instead of trusting a second
 * hand-written list to stay in sync with them.
 *
 * <p>The literal list in {@code CapabilityManifestTest} has gone stale twice already:
 * {@code accountType} shipped without it being added there, then {@code notableDrops} and
 * {@code petDrops} shipped without it either. A hand-maintained list only catches a gap its
 * own author remembered to update, which is exactly the failure that recurred. This scans
 * every {@code .java} file under {@code src/main/java} for a {@code allows("...")} call and
 * asserts each name it finds is in {@link CapabilityManifest#SUPPORTED_CAPABILITIES}, so a
 * ninth call site added anywhere fails this test the moment it is written rather than
 * shipping a capability that can never be switched on.
 */
public class CapabilityAllowlistCoverageTest {

  private static final Path SOURCE_ROOT = Paths.get("src", "main", "java");

  /** What a gate call looks like on the wire: {@code manifest.allows("someCapability")}. */
  private static final Pattern ALLOWS_CALL = Pattern.compile("allows\\(\"([^\"]+)\"\\)");

  @Test
  public void everyAllowsCallSiteNamesAKnownCapability() throws IOException {
    List<String> gatedOn = new ArrayList<>();
    try (Stream<Path> files = Files.walk(SOURCE_ROOT)) {
      for (Path file : (Iterable<Path>) files.filter(p -> p.toString().endsWith(".java"))::iterator) {
        List<String> lines = Files.readAllLines(file, StandardCharsets.UTF_8);
        for (String line : lines) {
          if (isComment(line)) {
            continue;
          }
          Matcher matcher = ALLOWS_CALL.matcher(line);
          while (matcher.find()) {
            gatedOn.add(matcher.group(1));
          }
        }
      }
    }

    // A scan that finds nothing is not a passing test, it is a broken one: the pattern
    // stopped matching real call sites and silently stopped protecting anything.
    assertFalse(
        "found no manifest.allows(...) call sites under src/main/java; the scan itself is"
            + " broken, this is not a pass",
        gatedOn.isEmpty());

    for (String capability : gatedOn) {
      assertTrue(
          capability + " is gated on by a manifest.allows(...) call in src/main/java but is"
              + " missing from SUPPORTED_CAPABILITIES, so that call can never return true",
          CapabilityManifest.SUPPORTED_CAPABILITIES.contains(capability));
    }
  }

  private static boolean isComment(String line) {
    String trimmed = line.trim();
    return trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*");
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Varbits;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;

public class CombatAchievementBossVarbitsTest {

  @Test
  public void covers68VerifiedSources() {
    // 77 CA_TOTAL_TASKS_COMPLETED_* constants exist in the real client. 6 are the
    // exact same varbit ids as the tier-count block (see the class doc) and 3 more
    // (COWBOSS, DOM, MAD_ANGEL) were left out for lack of a confident name, leaving
    // 68. This count moving without a matching change to the class doc's own
    // reasoning is the signal something drifted.
    assertEquals(68, CombatAchievementBossVarbits.ALL.size());
  }

  @Test
  public void everySourceMapsToADistinctVarbit() {
    // A copy-paste would attribute one boss's task count to two corpus sources.
    assertEquals(
        CombatAchievementBossVarbits.ALL.size(),
        new HashSet<>(CombatAchievementBossVarbits.ALL.values()).size());
  }

  @Test
  public void neverReadsATierCountVarbitAsABoss() {
    // The trap the class doc calls out by id: CA_TOTAL_TASKS_COMPLETED_EASY and
    // COMBAT_TASK_EASY are the same varbit (12885), so a boss entry that
    // accidentally reused one of the six tier ids would double-count a tier as a
    // fake "boss".
    Set<Integer> tierVarbits =
        new HashSet<>(
            Arrays.asList(
                Varbits.COMBAT_TASK_EASY,
                Varbits.COMBAT_TASK_MEDIUM,
                Varbits.COMBAT_TASK_HARD,
                Varbits.COMBAT_TASK_ELITE,
                Varbits.COMBAT_TASK_MASTER,
                Varbits.COMBAT_TASK_GRANDMASTER));
    for (Integer id : CombatAchievementBossVarbits.ALL.values()) {
      assertFalse("read a tier-count varbit as a boss", tierVarbits.contains(id));
    }
  }

  @Test
  public void everyKeyIsNonEmpty() {
    // The wire key is the corpus's own source name, not a code, so a blank one
    // would silently fail the server's join rather than fail loudly here.
    for (String key : CombatAchievementBossVarbits.ALL.keySet()) {
      assertTrue(key, !key.trim().isEmpty());
    }
  }

  @Test
  public void gargbossIsGrotesqueGuardiansNotThePlainMonster() {
    // Caught by review: GARGBOSS reads as "Gargoyle Boss", easy to misread as the
    // plain slayer monster. The corpus itself settles it: "Gargoyle" has one task
    // (not boss-shaped), "Grotesque Guardians" has fifteen.
    assertEquals(
        (Integer) VarbitID.CA_TOTAL_TASKS_COMPLETED_GARGBOSS,
        CombatAchievementBossVarbits.ALL.get("Grotesque Guardians"));
    assertFalse(CombatAchievementBossVarbits.ALL.containsKey("Gargoyle"));
  }

  @Test
  public void gauntletModesAreNotSwapped() {
    // Caught by review: the base/hard-mode pairing was backwards on first pass.
    // The corpus's own task text is unambiguous: every Crystalline Hunllef task
    // reads "Complete the Gauntlet" (the unsuffixed, base-mode varbit); every
    // Corrupted Hunllef task reads "Complete the Corrupted Gauntlet" (_HM).
    assertEquals(
        (Integer) VarbitID.CA_TOTAL_TASKS_COMPLETED_GAUNTLET,
        CombatAchievementBossVarbits.ALL.get("Crystalline Hunllef"));
    assertEquals(
        (Integer) VarbitID.CA_TOTAL_TASKS_COMPLETED_GAUNTLET_HM,
        CombatAchievementBossVarbits.ALL.get("Corrupted Hunllef"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** The prime-then-resolve state machine's pure logic (#660), tested without a live client. */
public class PetDropCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  @Test
  public void recognisesBothPrimeMessageForms() {
    assertTrue(PetDropCapture.isPrimeMessage("You have a funny feeling like you're being followed."));
    assertTrue(PetDropCapture.isPrimeMessage("You feel something weird sneaking into your backpack."));
  }

  @Test
  public void anUnrelatedMessageDoesNotPrime() {
    assertFalse(PetDropCapture.isPrimeMessage("You have received a drop: Coins."));
  }

  @Test
  public void resolvesAKnownPetFromTheCollectionLogLine() {
    String name = PetDropCapture.resolvePetName("New item added to your collection log: Baby mole");
    assertEquals("Baby mole", name);
  }

  @Test
  public void resolvesAKnownPetFromTheUntradeableDropLine() {
    String name = PetDropCapture.resolvePetName("Untradeable drop: Heron");
    assertEquals("Heron", name);
  }

  @Test
  public void aNonPetUntradeableIsIgnored() {
    assertNull(PetDropCapture.resolvePetName("Untradeable drop: Clue scroll (elite)"));
  }

  /**
   * The game's own broadcast lines use the pet's real display casing (title case for
   * most compound names), not the lowercase-first-word form several {@link
   * PetDropCapture#KNOWN_PETS} entries were typed as. A case-sensitive check silently
   * dropped every one of these: TzRek-Jad, Baby Mole, Giant Squirrel, Jal-Nib-Rek and
   * every "Pet &lt;Boss&gt;" pet never resolved at all before this fix.
   */
  @Test
  public void resolvesAKnownPetRegardlessOfCasing() {
    assertEquals(
        "TzRek-Jad",
        PetDropCapture.resolvePetName("Untradeable drop: TzRek-Jad"));
    assertEquals(
        "Baby Mole",
        PetDropCapture.resolvePetName("New item added to your collection log: Baby Mole"));
    assertEquals(
        "Giant Squirrel",
        PetDropCapture.resolvePetName("Untradeable drop: Giant Squirrel"));
    assertEquals(
        "Pet Dagannoth Prime",
        PetDropCapture.resolvePetName("Untradeable drop: Pet Dagannoth Prime"));
  }

  @Test
  public void anUnrecognisedMessageResolvesToNull() {
    assertNull(PetDropCapture.resolvePetName("Congratulations, you've completed a hard Combat Task."));
  }

  @Test
  public void payloadCarriesTheNameAndNoSource() {
    java.util.Map<String, Object> payload = PetDropCapture.payload("Baby mole");
    assertEquals("Baby mole", payload.get("petName"));
    assertNull(payload.get("source"));
  }

  /**
   * The toggle gates deriving-and-emitting, not the one-shot prime/consume
   * tracking (see {@code handleMessage}'s own doc for why). Feeds the exact
   * prime-then-resolve sequence for a known pet while disabled and confirms
   * nothing reaches the outbox either way.
   */
  @Test
  public void handleMessageEmitsNothingWhenDisabled() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    PetDropCapture capture = new PetDropCapture(outbox, () -> false, () -> 1L);

    capture.handleMessage("You have a funny feeling like you're being followed.");
    capture.handleMessage("New item added to your collection log: Baby mole");

    assertTrue(outbox.pending().isEmpty());
  }

  /**
   * The one-shot consumption must survive a toggle-off between the prime and its
   * resolve. If it did not, disabling between the two would leave {@code primed}
   * stuck true with nothing to clear it, and a later, unrelated message naming a
   * known pet after re-enabling would wrongly resolve that stale prime, exactly
   * the failure the one-shot design exists to prevent.
   */
  @Test
  public void aPrimeConsumedWhileDisabledIsNotWronglyResolvedAfterReEnabling() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    boolean[] enabled = {true};
    PetDropCapture capture = new PetDropCapture(outbox, () -> enabled[0], () -> 1L);

    capture.handleMessage("You have a funny feeling like you're being followed.");
    enabled[0] = false;
    // The resolve message arrives while disabled: nothing is emitted, but the
    // one-shot prime must still be consumed here, not left stuck for later.
    capture.handleMessage("Untradeable drop: Heron");
    enabled[0] = true;
    // An unrelated later message that happens to name a known pet must NOT be
    // treated as resolving anything: there is no active prime by this point.
    capture.handleMessage("Untradeable drop: Baby mole");

    assertTrue(outbox.pending().isEmpty());
  }
}

