package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import java.util.UUID;
import org.junit.Test;

public class UuidV7Test {
  @Test
  public void generatesACanonicalVersion7Uuid() {
    String s = UuidV7.generate();
    // Canonical 8-4-4-4-12 form, parseable by java.util.UUID.
    UUID parsed = UUID.fromString(s);
    assertEquals("36 chars", 36, s.length());
    assertEquals("version 7", 7, parsed.version());
    assertEquals("RFC variant", 2, parsed.variant());
    assertEquals("lowercase", s, s.toLowerCase());
  }

  @Test
  public void generatesDistinctValues() {
    assertNotEquals(UuidV7.generate(), UuidV7.generate());
  }

  @Test
  public void isTimeOrderedAcrossAShortDelay() throws Exception {
    String a = UuidV7.generate();
    Thread.sleep(2);
    String b = UuidV7.generate();
    // UUIDv7 leads with a millisecond timestamp, so lexical order tracks time.
    assertTrue("later uuid sorts after earlier", b.compareTo(a) > 0);
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class StatusReportTest {

  private static boolean mentions(List<String> lines, String needle) {
    for (String line : lines) {
      if (line.contains(needle)) {
        return true;
      }
    }
    return false;
  }

  @Test
  public void namesWhatItActuallyCounted() {
    // The plugin counts distinct item ids; the game counts entries. On a real
    // account those were 193 and 189, and calling ids "entries" put both numbers
    // in one chat window disagreeing with each other. The plugin has no manifest
    // and cannot resolve one into the other, so it names what it counted.
    List<String> lines =
        StatusReport.lines(
            true, "https://x", "Zezima", "just now", null, Arrays.asList("skills"), 193, null, null);
    assertTrue(mentions(lines, "193 items"));
    assertFalse(mentions(lines, "193 entries"));
  }

  @Test
  public void unpairedSaysOnlyThat() {
    // Every other line describes a pairing that does not exist. Printing them
    // reads as though something is configured when nothing is.
    List<String> lines =
        StatusReport.lines(false, "https://x", "Zezima", "just now", null, Arrays.asList("skills"), 12, null, null);
    assertEquals(1, lines.size());
    assertTrue(lines.get(0).contains("Not paired"));
  }

  @Test
  public void namesTheServerBecauseAWrongOneIsOtherwiseSilent() {
    List<String> lines =
        StatusReport.lines(
            true, "https://example.test", "Zezima", "just now", null, Arrays.asList("skills"), 12, null, null);
    assertTrue(mentions(lines, "https://example.test"));
  }

  @Test
  public void saysWhenNoCharacterIsLinkedAndHowToFixIt() {
    // The exact state that cost two hours: identity submitted once, failed, and
    // nothing in the client could be asked to try again.
    List<String> lines =
        StatusReport.lines(true, "https://x", null, null, null, Arrays.asList("skills"), -1, null, null);
    assertTrue(mentions(lines, "No character linked"));
    assertTrue(mentions(lines, "::bstand link"));
  }

  @Test
  public void namesTheLinkedCharacter() {
    List<String> lines =
        StatusReport.lines(true, "https://x", "Zezima", "just now", null, Arrays.asList("skills"), 5, null, null);
    assertTrue(mentions(lines, "Zezima"));
  }

  @Test
  public void saysWhenNothingIsSwitchedOn() {
    List<String> lines =
        StatusReport.lines(true, "https://x", "Zezima", null, null, Collections.emptyList(), -1, null, null);
    assertTrue(mentions(lines, "No capabilities switched on"));
  }

  @Test
  public void reportsTheLastFailureOnlyWhenThereIsOne() {
    List<String> withFailure =
        StatusReport.lines(
            true, "https://x", "Zezima", "5m ago", "401 unauthorised", Arrays.asList("skills"), 5, null, null);
    assertTrue(mentions(withFailure, "401 unauthorised"));

    List<String> clean =
        StatusReport.lines(true, "https://x", "Zezima", "5m ago", null, Arrays.asList("skills"), 5, null, null);
    assertFalse(mentions(clean, "Last failure"));
  }

  @Test
  public void alwaysExplainsTheCollectionLog() {
    // Read or not, it gets a line. It is the one capability a manual sync cannot
    // refresh, and silence about it is what makes a working sync look broken.
    List<String> neverRead =
        StatusReport.lines(true, "https://x", "Zezima", "5m ago", null, Arrays.asList("skills"), -1, null, null);
    assertTrue(mentions(neverRead, "Search"));
    assertFalse(mentions(neverRead, "-1"));

    List<String> read =
        StatusReport.lines(true, "https://x", "Zezima", "5m ago", null, Arrays.asList("skills"), 189, null, null);
    assertTrue(mentions(read, "189"));
    assertTrue(mentions(read, "Search"));
  }

  @Test
  public void syncNamesWhatItIsSendingAndWhatItIsNot() {
    List<String> lines = StatusReport.syncLines(true, Arrays.asList("skills", "quests"));
    assertTrue(mentions(lines, "skills, quests"));
    // The trap this line exists to avoid: a player runs a sync, sees no new
    // collection log slots, and concludes it did nothing.
    assertTrue(mentions(lines, "collection log is not included"));
  }

  @Test
  public void syncRefusesWithNothingToSend() {
    assertTrue(mentions(StatusReport.syncLines(false, Arrays.asList("skills")), "Not paired"));
    assertTrue(
        mentions(StatusReport.syncLines(true, Collections.emptyList()), "nothing to sync"));
  }

  @Test
  public void showsTheAccountTypeWhenTheGameReportedOne() {
    List<String> lines =
        StatusReport.lines(
            true,
            "https://x",
            "Zezima",
            "just now",
            null,
            Arrays.asList("skills"),
            5,
            "Account type: group (varbit 1777 = 4).", null);
    assertTrue(mentions(lines, "Account type: group"));
  }

  @Test
  public void saysNothingAboutTheAccountTypeWhileLoggedOut() {
    // The varbit reads 0 with no account loaded, which is the same value a regular
    // account reports. Printing "regular" there would be a wrong answer rather than a
    // missing one, so the caller passes null and the line is simply absent.
    List<String> lines =
        StatusReport.lines(
            true, "https://x", null, "just now", null, Arrays.asList("skills"), 5, null, null);
    assertFalse(mentions(lines, "Account type"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Whether a read taken as the player logs out can be trusted.
 *
 * <p>The final minute of a session is otherwise never captured, which is what #643 is
 * about. The catch is that this read happens after the client has left the world, and
 * whether skill XP is still readable there cannot be verified outside a running client.
 * So the read is checked instead of trusted: anything that looks like a cleared client
 * is discarded, and discarding costs nothing because the next login re-reads live state
 * that already includes those minutes.
 */
public class FinalReadTest {

  private static Map<String, Integer> xp(int attack, int cooking) {
    Map<String, Integer> m = new LinkedHashMap<>();
    m.put("attack", attack);
    m.put("cooking", cooking);
    return m;
  }

  @Test
  public void trustsAReadThatMatchesTheLastOne() {
    assertTrue(BankstandPlugin.isPlausibleFinalRead(xp(100, 200), xp(100, 200)));
  }

  @Test
  public void trustsAReadThatGainedXp() {
    assertTrue(BankstandPlugin.isPlausibleFinalRead(xp(100, 200), xp(140, 200)));
  }

  /** A cleared client reads as zeroes, and submitting those is an XP regression. */
  @Test
  public void rejectsAZeroedRead() {
    assertFalse(BankstandPlugin.isPlausibleFinalRead(xp(100, 200), xp(0, 0)));
  }

  @Test
  public void rejectsAReadWhereAnySkillWentBackwards() {
    assertFalse(BankstandPlugin.isPlausibleFinalRead(xp(100, 200), xp(100, 199)));
  }

  @Test
  public void rejectsAnEmptyRead() {
    assertFalse(BankstandPlugin.isPlausibleFinalRead(xp(100, 200), new LinkedHashMap<>()));
  }

  @Test
  public void rejectsAReadMissingSkillsTheLastOneHad() {
    Map<String, Integer> partial = new LinkedHashMap<>();
    partial.put("attack", 100);

    assertFalse(BankstandPlugin.isPlausibleFinalRead(xp(100, 200), partial));
  }

  /**
   * With no previous read there is nothing to compare against, so a non-empty one is
   * taken at face value. It still goes through the same submit path, where the server's
   * own regression guard is the backstop.
   */
  @Test
  public void acceptsAnyNonEmptyReadWhenThereIsNoPreviousOne() {
    assertTrue(BankstandPlugin.isPlausibleFinalRead(null, xp(100, 200)));
    assertFalse(BankstandPlugin.isPlausibleFinalRead(null, new LinkedHashMap<>()));
  }

  /** A genuinely zero skill is real for a fresh account, and must not be mistaken. */
  @Test
  public void acceptsAZeroThatWasAlreadyZero() {
    assertTrue(BankstandPlugin.isPlausibleFinalRead(xp(0, 0), xp(0, 0)));
    assertTrue(BankstandPlugin.isPlausibleFinalRead(xp(0, 0), xp(5, 0)));
  }
}

package com.bankstand;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class DeviceCredentialsTest {

  /**
   * {@code NoSecretsInLogsTest} bans passing the literal identifiers {@code token}/{@code
   * getToken()} to a log call by scanning source text, but cannot see through an object
   * argument whose own {@code toString()} embeds the credential: {@code log.debug("...",
   * credentials)} reads as passing {@code credentials}, not the token. This is the property
   * that closes that gap rather than merely relying on nobody ever passing the object whole.
   */
  @Test
  public void toStringNeverIncludesTheToken() {
    DeviceCredentials credentials = new DeviceCredentials();
    credentials.setToken("bsd_super_secret_token_value");
    credentials.setDeviceId("dev_1");
    credentials.setExpiresAt("2027-01-01T00:00:00Z");

    String rendered = credentials.toString();

    assertFalse(rendered.contains("bsd_super_secret_token_value"));
    // The other fields are not credentials, so toString() staying useful for
    // them is a deliberate trade-off, not something this exclusion should cost.
    assertTrue(rendered.contains("dev_1"));
    assertTrue(rendered.contains("2027-01-01T00:00:00Z"));
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class CollectionLogUnlockCaptureTest {

  @Rule public TemporaryFolder folder = new TemporaryFolder();

  @Test
  public void emitsOnTheCollectionLogBroadcast() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("New item added to your collection log: Abyssal orphan");

    assertTrue(!outbox.pending().isEmpty());
    // A typo in TYPE_COLLECTION_LOG_UNLOCK would compile and pass every other
    // assertion here, then fail permanently in production as a 400 the server
    // rejects: the type is the one value in this diff the server also checks.
    assertEquals(
        TransientEvent.TYPE_COLLECTION_LOG_UNLOCK, outbox.pending().get(0).getEvent().getType());
    assertTrue(
        outbox.pending().get(0).getEvent().getPayload().get("itemName").equals("Abyssal orphan"));
  }

  /** The server validates a whole batch in one schema parse (128-char item-name bound)
   *  and 400s the WHOLE BATCH on any one event failing validation, with the drain
   *  acking nothing on failure: one oversized name would block every other queued
   *  event for the account, forever. */
  @Test
  public void skipsAnOversizedItemName() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);
    String oversizedName = repeat("A", 129);

    capture.handleMessage("New item added to your collection log: " + oversizedName);

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void emitsAnItemNameAtExactlyTheLengthBound() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);
    String boundedName = repeat("A", 128);

    capture.handleMessage("New item added to your collection log: " + boundedName);

    assertTrue(!outbox.pending().isEmpty());
  }

  private static String repeat(String s, int times) {
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < times; i++) {
      builder.append(s);
    }
    return builder.toString();
  }

  /** A whitespace-only capture is min(1)-valid junk on the wire, not a real item
   *  name, and one bad event 400s the whole batch (see the oversized-name test
   *  above), permanently blocking every other queued event for the account. */
  @Test
  public void doesNotEmitAWhitespaceOnlyItemName() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("New item added to your collection log:    ");

    assertTrue(outbox.pending().isEmpty());
  }

  @Test
  public void trimsSurroundingWhitespaceFromTheItemName() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("New item added to your collection log:  Abyssal orphan  ");

    assertTrue(!outbox.pending().isEmpty());
    assertEquals(
        "Abyssal orphan", outbox.pending().get(0).getEvent().getPayload().get("itemName"));
  }

  @Test
  public void ignoresAnUnrelatedMessage() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> true, () -> 1L);

    capture.handleMessage("Untradeable drop: Coins");

    assertTrue(outbox.pending().isEmpty());
  }

  /** The toggle must gate the read itself, not only emit, matching NotableDropCapture's
   *  established convention (#608's own plugin-side session recorded this as the rule
   *  to follow: a stateless single-message detector gates at the very top). */
  @Test
  public void touchesNothingWhenDisabled() throws IOException {
    File file = new File(folder.newFolder("bankstand"), "events.json");
    EventOutbox outbox = new EventOutbox(file, new Gson());
    CollectionLogUnlockCapture capture = new CollectionLogUnlockCapture(outbox, () -> false, () -> 1L);

    capture.handleMessage("New item added to your collection log: Abyssal orphan");

    assertTrue(outbox.pending().isEmpty());
  }
}

package com.bankstand.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class AccountSessionTest {

  @Test
  public void ignoresTheLoggedOutSentinel() {
    AccountSession s = new AccountSession();
    assertFalse(s.onLogin(AccountSession.LOGGED_OUT));
    assertFalse(s.isActive());
    assertEquals(AccountSession.LOGGED_OUT, s.getAccountHash());
  }

  @Test
  public void adoptsTheFirstRealHash() {
    AccountSession s = new AccountSession();
    assertTrue(s.onLogin(123L));
    assertTrue(s.isActive());
    assertEquals(123L, s.getAccountHash());
  }

  @Test
  public void theSameHashIsANoOp() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    assertFalse(s.onLogin(123L));
    assertEquals(123L, s.getAccountHash());
  }

  @Test
  public void aSwitchResetsAndAdoptsTheNewHash() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    assertTrue(s.onLogin(456L));
    assertEquals(456L, s.getAccountHash());
  }

  @Test
  public void logoutClearsTheSession() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    s.onLogout();
    assertFalse(s.isActive());
    assertEquals(AccountSession.LOGGED_OUT, s.getAccountHash());
  }

  @Test
  public void isCurrentForTheAdoptedHashAndGeneration() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    assertTrue(s.isCurrent(123L, s.getGeneration()));
  }

  @Test
  public void notCurrentForADifferentHash() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    assertFalse(s.isCurrent(456L, s.getGeneration()));
  }

  @Test
  public void notCurrentAfterSwitchingAccounts() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    int gen = s.getGeneration();
    s.onLogin(456L);
    // A stale in-flight submit for the old account must not be treated as current.
    assertFalse(s.isCurrent(123L, gen));
    assertTrue(s.isCurrent(456L, s.getGeneration()));
  }

  @Test
  public void notCurrentAfterLogout() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    int gen = s.getGeneration();
    s.onLogout();
    assertFalse(s.isCurrent(123L, gen));
  }

  @Test
  public void theLoggedOutSentinelIsNeverCurrent() {
    AccountSession s = new AccountSession();
    assertFalse(s.isCurrent(AccountSession.LOGGED_OUT, s.getGeneration()));
  }

  @Test
  public void aStalePriorInstanceIsNotCurrentAfterReloggingTheSameAccount() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    int staleGen = s.getGeneration();
    // Log out and back into the SAME account: a fresh instance with a new generation.
    s.onLogout();
    s.onLogin(123L);
    // The prior instance's in-flight submit must not be treated as current even
    // though the account hash matches again.
    assertFalse(s.isCurrent(123L, staleGen));
    assertTrue(s.isCurrent(123L, s.getGeneration()));
  }

  @Test
  public void generationIsStableAcrossASameHashNoOpLogin() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    int gen = s.getGeneration();
    // A world hop stays on the same account: onLogin is a no-op and must not advance
    // the generation, so an in-flight submit for this instance stays current.
    assertFalse(s.onLogin(123L));
    assertEquals(gen, s.getGeneration());
    assertTrue(s.isCurrent(123L, gen));
  }

  @Test
  public void tracksTheSubmittedFlagPerAccount() {
    AccountSession s = new AccountSession();
    s.onLogin(123L);
    assertFalse(s.isSubmitted());
    s.markSubmitInFlight();
    assertTrue(s.isSubmitted());

    // Same account stays submitted; a switch resets it; so does logout.
    assertFalse(s.onLogin(123L));
    assertTrue(s.isSubmitted());
    assertTrue(s.onLogin(456L));
    assertFalse(s.isSubmitted());

    s.markSubmitInFlight();
    s.onLogout();
    assertFalse(s.isSubmitted());
  }

  @Test
  public void releasesTheMarkWhenASubmitFails() {
    // The bug this exists to stop: a failed identity submit used to leave the session
    // marked forever, so nothing retried and every later capture was refused until the
    // player logged out and back in. A failure must leave the session able to try again.
    AccountSession s = new AccountSession();
    s.onLogin(42L);
    s.markSubmitInFlight();
    assertTrue(s.isSubmitted());

    s.markSubmitFailed(42L, s.getGeneration());
    assertFalse(s.isSubmitted());
  }

  @Test
  public void ignoresAFailureFromASupersededLogin() {
    // A failure can arrive after the player has switched character, because the submit
    // retries with backoff for several seconds. Re-arming a submit for an account that is
    // no longer logged in would fire one against the wrong session.
    AccountSession s = new AccountSession();
    s.onLogin(42L);
    s.markSubmitInFlight();
    int staleGeneration = s.getGeneration();

    s.onLogin(99L);
    s.markSubmitInFlight();
    s.markSubmitFailed(42L, staleGeneration);

    assertTrue("a stale failure must not re-arm the current session", s.isSubmitted());
  }

  @Test
  public void ignoresAFailureFromAnEarlierGenerationOfTheSameAccount() {
    // A logout and relog to the SAME account advances the generation, so the hash alone
    // is not enough to tell the two apart.
    AccountSession s = new AccountSession();
    s.onLogin(42L);
    s.markSubmitInFlight();
    int staleGeneration = s.getGeneration();

    s.onLogout();
    s.onLogin(42L);
    s.markSubmitInFlight();
    s.markSubmitFailed(42L, staleGeneration);

    assertTrue(s.isSubmitted());
  }
}

package com.bankstand;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class DiaryTaskRegionsTest {

  @Test
  public void resolvesEveryRegionDiaryTaskVarplayersKnows() {
    for (String region : DiaryTaskVarplayers.ALL.keySet()) {
      boolean found = false;
      for (String areaText : new String[] {
          "Ardougne", "Desert", "Falador", "Fremennik", "Kandarin", "Kourend & Kebos",
          "Lumbridge & Draynor", "Morytania", "Varrock", "Western Provinces",
          "Wilderness", "Karamja"}) {
