package com.bankstand;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import org.junit.Test;

public class DiaryTaskBitsTest {

  @Test
  public void firstObservationEstablishesTheBaselineAndReportsNothing() {
    // Pre-existing progress must not read as freshly completed on the first read.
    DiaryTaskBits bits = new DiaryTaskBits();

    int[] newlySet = bits.diff(1196, 0b101);

    assertArrayEquals(new int[0], newlySet);
  }

  @Test
  public void reportsExactlyTheBitThatWentFromUnsetToSet() {
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0001);

    int[] newlySet = bits.diff(1196, 0b0101);

    assertArrayEquals(new int[] {2}, newlySet);
  }

  @Test
  public void reportsMultipleBitsFlippedAtOnce() {
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0000);

    int[] newlySet = bits.diff(1196, 0b1010);

    assertArrayEquals(new int[] {1, 3}, newlySet);
  }

  @Test
  public void reportsNothingWhenTheValueIsUnchanged() {
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0101);

    int[] newlySet = bits.diff(1196, 0b0101);

    assertArrayEquals(new int[0], newlySet);
  }

  @Test
  public void doesNotReportABitGoingFromSetToUnset() {
    // Shouldn't happen (nothing un-completes a diary task), must not crash either way.
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0111);

    int[] newlySet = bits.diff(1196, 0b0011);

    assertArrayEquals(new int[0], newlySet);
  }

  @Test
  public void alwaysAdvancesRegardlessOfWhatCallerDoesWithTheResult() {
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0001);
    bits.diff(1196, 0b0011);

    // The baseline is now 0b0011; re-reading the same value reports nothing new.
    assertArrayEquals(new int[0], bits.diff(1196, 0b0011));
  }

  @Test
  public void tracksEachVarplayerIndependently() {
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0001);
    bits.diff(1197, 0b0001);

    // A bit newly set on one varplayer must not be diffed against another's baseline.
    int[] first = bits.diff(1196, 0b0011);
    int[] second = bits.diff(1198, 0b0001);

    assertArrayEquals(new int[] {1}, first);
    assertArrayEquals(new int[0], second);
  }

  @Test
  public void resetForgetsEveryVarplayer() {
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0111);

    bits.reset();

    // A reset makes this a first observation again, not three newly completed tasks.
    assertArrayEquals(new int[0], bits.diff(1196, 0b0111));
  }

  @Test
  public void restoreAndSnapshotRoundTrip() {
    DiaryTaskBits original = new DiaryTaskBits();
    original.diff(1196, 0b0001);
    original.diff(1197, 0b0010);

    Map<Integer, Integer> saved = original.snapshot();
    DiaryTaskBits restored = new DiaryTaskBits();
    restored.restore(saved);

    // Diffs against the restored baseline, not a fresh first observation.
    assertArrayEquals(new int[] {1}, restored.diff(1196, 0b0011));
    assertEquals(2, saved.size());
    assertTrue(saved.containsKey(1196));
    assertTrue(saved.containsKey(1197));
  }

  @Test
  public void snapshotIsIndependentOfLaterChanges() {
    DiaryTaskBits bits = new DiaryTaskBits();
    bits.diff(1196, 0b0001);

    Map<Integer, Integer> snapshot = bits.snapshot();
    bits.diff(1196, 0b0011);

    assertEquals(Integer.valueOf(0b0001), snapshot.get(1196));
  }
}

package com.bankstand;

import java.util.Map;

/**
 * The last quest-state vector the server acknowledged, used as a change gate so the
 * capture loop only submits when something moved. The plugin resets this on an
 * account switch and advances it only when a submit is acknowledged, so a dropped
 * submit is retried on the next capture (the baseline never moved).
 *
 * <p>Held as a digest rather than a copy of the vector, so the same value can be
 * written to disk and restored on the next client start. See {@link SkillBaseline} for
 * why one representation across memory and disk is worth a hash.
 */
public class QuestBaseline {
  private String acked;

  /** True when {@code current} differs from what the server last acknowledged. */
  public boolean changedSince(Map<String, String> current) {
    return !CapabilityDigest.of(current).equals(acked);
  }

  public void advance(Map<String, String> ackedNow) {
    acked = CapabilityDigest.of(ackedNow);
  }

  /** Restores a digest read back from disk. Null means nothing is known. */
  public void restore(String digest) {
    acked = digest;
  }

  /** The acknowledged digest, or null when nothing has been. */
  public String ackedDigest() {
    return acked;
  }

  public void reset() {
    acked = null;
  }
}

package com.bankstand;

import net.runelite.api.Varbits;

/**
 * Reads the account type the game itself reports, and names it the way Bankstand does.
 *
 * <p><b>Why this is worth reading at all.</b> Group Ironman accounts do not appear on
 * the ironman hiscores, so Wise Old Man reports every one of them as a regular account.
 * Three of Bankstand's seven account types are therefore undetectable from any public
 * source, and until now the only way to record one was for the owner to pick it from a
 * dropdown. This varbit is what the game says.
 *
 * <p><b>It confirms; it does not verify.</b> Like everything else the plugin sends, this
 * is client-asserted: it says what a client reported, never who owns the account. It
 * must never become the public account type on a profile.
 *
 * <p>A plain mapping with no {@code Client} dependency in the pure part, so the table is
 * unit-testable without a live game client.
 */
public final class AccountTypes {

  private AccountTypes() {}

  /**
   * Varbit 1777, named {@code ACCOUNT_TYPE} in the older table and {@code IRONMAN} in
   * {@code VarbitID}. The value is the ordinal of RuneLite's own
   * {@code net.runelite.api.vars.AccountType}.
   */
  public static final int ACCOUNT_TYPE_VARBIT = Varbits.ACCOUNT_TYPE;

  /**
   * Bankstand's own type keys, indexed by varbit value.
   *
   * <p>These are Bankstand's names, not RuneLite's: the server's {@code ACCOUNT_TYPES}
   * calls them {@code hardcore} and {@code ultimate} where RuneLite says
   * {@code HARDCORE_IRONMAN} and {@code ULTIMATE_IRONMAN}, and the wire has to match the
   * server.
   *
   * <p><b>6 is measured, not inherited.</b> RuneLite's enum has six members and stops at
   * hardcore group ironman, so the last entry here comes from reading the varbit on real
   * accounts rather than from the enum:
   *
   * <pre>
   *   a normal account        1777 = 0
   *   a ranked HCGIM          1777 = 5
   *   an unranked GIM         1777 = 6
   * </pre>
   *
   * The middle reading is what makes the last one trustworthy. 5 landing exactly where
   * RuneLite declares hardcore group ironman confirms the ordinal and the varbit are the
   * same number, so 6 is the next mode along and not a coincidence.
   */
  private static final String[] BY_VALUE = {
    "regular",
    "ironman",
    "ultimate",
    "hardcore",
    "group",
    "hardcore_group",
    "unranked_group",
  };

  /**
   * The Bankstand type key for a varbit value, or null when the value is one this build
   * has never seen.
   *
   * <p>Null rather than a fallback to {@code regular}. An unmapped value means the game
   * reported something new, and calling that "regular" would quietly turn an unknown into
   * a confident wrong answer, which is the one outcome the whole account type feature
   * exists to stop.
   */
  public static String keyFor(int varbitValue) {
    if (varbitValue < 0 || varbitValue >= BY_VALUE.length) {
      return null;
    }
    return BY_VALUE[varbitValue];
  }

  /**
   * One status line naming the type and the raw varbit value.
   *
   * <p>The raw value is shown deliberately, and is the entire point of the line while the
   * unranked Group Ironman question is open: RuneLite's {@code VarInspector} logs var
   * <i>changes</i>, and 1777 does not change during a session, so there is no other way
   * to see what a real account reports.
   */
  public static String describe(int varbitValue) {
    String key = keyFor(varbitValue);
    if (key == null) {
      return "Account type: unrecognised (varbit "
          + ACCOUNT_TYPE_VARBIT
          + " = "
          + varbitValue
          + "). Please report this value.";
    }
    return "Account type: " + key + " (varbit " + ACCOUNT_TYPE_VARBIT + " = " + varbitValue + ").";
  }
}

package com.bankstand;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.HashMap;
import java.util.Map;

/**
 * Reads and writes what the server has already acknowledged, per character.
 *
 * <p>A file, not {@code ConfigManager}: a synced profile PATCHes its whole config to
 * RuneLite's own service, with no per-key exclusion, and what this holds is the player's
 * captured game data.
 *
 * <p>Every read failure resolves to "nothing is known", which re-sends everything once.
 * That is what the client did before any of this persisted, so the failure mode is the
 * status quo.
 *
 * <p>Not thread-safe; the plugin calls it only from its background executor.
 */
public class AckedStateStore {

  /** One file, characters keyed by account hash. */
  private static class Document {
    Map<String, AckedState> accounts;
  }

  private final File file;
  private final Gson gson;

  public AckedStateStore(File file, Gson gson) {
    this.file = file;
    this.gson = gson;
  }

  /** Never null. */
  public AckedState load(long accountHash) {
    AckedState stored = read().accounts.get(Long.toString(accountHash));
    if (stored == null) {
      return AckedState.empty();
    }
    // Copied, so a caller mutating what it got cannot reach into the next read.
    AckedState copy = AckedState.empty();
    copy.setSkills(stored.getSkills());
    copy.setQuests(stored.getQuests());
    copy.setDiaries(stored.getDiaries());
    copy.setCombatAchievements(stored.getCombatAchievements());
    copy.setCollectionLogItems(stored.getCollectionLogItems());
    copy.setCollectionLogAcked(stored.getCollectionLogAcked());
    copy.setLastSyncedAt(stored.getLastSyncedAt());
    copy.setDiaryTaskBits(stored.getDiaryTaskBits());
    return copy;
  }

  /** Leaves every other character's state untouched. */
  public void save(long accountHash, AckedState state) {
    Document document = read();
    document.accounts.put(Long.toString(accountHash), state);
    write(document);
  }

  private Document read() {
    Document document = null;
    if (file.exists()) {
      try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
        document = gson.fromJson(reader, Document.class);
      } catch (IOException | RuntimeException e) {
        // Not logged: the document holds an account hash and a collection log.
        document = null;
      }
    }
    if (document == null) {
      document = new Document();
    }
    if (document.accounts == null) {
      document.accounts = new HashMap<>();
    }
    return document;
  }

  private void write(Document document) {
    Path target = file.toPath();
    Path directory = target.getParent();
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash midway leaves the previous document intact.
      Path temp = Files.createTempFile(directory, "acked", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(document, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
    } catch (IOException | RuntimeException e) {
      // A failed save costs one resend next start, which is not worth throwing out of a
      // background task on the submit path.
    }
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;

/**
 * Maps a combat achievement source's real name (the same string the website's own task
 * corpus keys its {@code source} field on, e.g. "Vorkath", "Theatre of Blood: Hard Mode")
 * to the varbit holding how many of that source's tasks are done.
 *
 * <p>The wire key is the boss/activity name itself, not a RuneLite-internal code, so the
 * server's join against its own corpus needs no separate name-translation table: the
 * plugin is the one place that has to know {@code VarbitID.CA_TOTAL_TASKS_COMPLETED_KBD}
 * means King Black Dragon, not the website.
 *
 * <p><b>Not every {@code CA_TOTAL_TASKS_COMPLETED_*} constant is listed here.</b> Six of
 * the 77 ({@code EASY}/{@code MEDIUM}/{@code HARD}/{@code ELITE}/{@code MASTER}/{@code
 * GRANDMASTER}) are the exact same varbit ids {@link CombatAchievementVarbits} already
 * reads for the tier-count block (confirmed by id, not name: {@code
 * CA_TOTAL_TASKS_COMPLETED_EASY} and {@code COMBAT_TASK_EASY} are both 12885), so they add
 * nothing new here. Three more are left out deliberately because a confident name could
 * not be established: {@code COWBOSS} sits among 25th-anniversary varbits with no
 * matching task in the corpus at all; {@code DOM} is a varbit id in the 3000s, a range
 * that predates Combat Achievements as a system by years, so despite superficially
 * spelling out "Doom of Mokhaiotl" it almost certainly is not that boss (see {@code
 * CATA_BOSS} below, whose id sits correctly among the 2023-era combat achievement block
 * and is used for that boss instead); {@code MAD_ANGEL} sits among brand-new
 * Sailing-skill varbits, most likely a boss too recent for the corpus this was
 * generated from. Misattributing a task count to the wrong boss is a real, visible
 * correctness bug, not a cosmetic gap, so an uncertain id is left out rather than
 * guessed.
 *
 * <p>Every id below is a symbolic reference to the real RuneLite constant, not a bare
 * number: if a future RuneLite release renames or drops one, this file fails to
 * <i>compile</i> against the new API, which is a stronger, earlier failure than a
 * runtime check could give (and reflection, which would dodge this trap a different way,
 * is off the table: the Plugin Hub review disallows it).
 */
public final class CombatAchievementBossVarbits {
  private CombatAchievementBossVarbits() {}

  /** Ordered, unmodifiable: wire key (the corpus's own source name) to varbit id. */
  public static final Map<String, Integer> ALL = Collections.unmodifiableMap(build());

  private static Map<String, Integer> build() {
    Map<String, Integer> m = new LinkedHashMap<>();
    m.put("Abyssal Sire", VarbitID.CA_TOTAL_TASKS_COMPLETED_ABYSSALSIRE);
    m.put("Amoxliatl", VarbitID.CA_TOTAL_TASKS_COMPLETED_AMOXLIATL);
    m.put("Araxxor", VarbitID.CA_TOTAL_TASKS_COMPLETED_ARAXXOR);
    // Godwars generals are keyed by god here (RuneLite's own naming) but by the boss
    // NPC's name in the corpus.
    m.put("Kree'arra", VarbitID.CA_TOTAL_TASKS_COMPLETED_ARMADYL);
    m.put("General Graardor", VarbitID.CA_TOTAL_TASKS_COMPLETED_BANDOS);
    m.put("Commander Zilyana", VarbitID.CA_TOTAL_TASKS_COMPLETED_SARADOMIN);
    m.put("K'ril Tsutsaroth", VarbitID.CA_TOTAL_TASKS_COMPLETED_ZAMORAK);
    m.put("Barrows", VarbitID.CA_TOTAL_TASKS_COMPLETED_BARROWS);
    m.put("Bryophyta", VarbitID.CA_TOTAL_TASKS_COMPLETED_BRYOPHYTA);
    m.put("Callisto", VarbitID.CA_TOTAL_TASKS_COMPLETED_CALLISTO);
    // See the class doc: id 12918 sits in the 2023-era combat achievement block, unlike
    // the similarly-spelled but far older CA_TOTAL_TASKS_COMPLETED_DOM (id 3209), which
    // is left out for that reason.
    m.put("Doom of Mokhaiotl", VarbitID.CA_TOTAL_TASKS_COMPLETED_CATA_BOSS);
    m.put("Cerberus", VarbitID.CA_TOTAL_TASKS_COMPLETED_CERBERUS);
    m.put("Chaos Elemental", VarbitID.CA_TOTAL_TASKS_COMPLETED_CHAOSELE);
    m.put("Chaos Fanatic", VarbitID.CA_TOTAL_TASKS_COMPLETED_CHAOSFANATIC);
    m.put("Fortis Colosseum", VarbitID.CA_TOTAL_TASKS_COMPLETED_COLOSSEUM);
    m.put("Corporeal Beast", VarbitID.CA_TOTAL_TASKS_COMPLETED_CORP);
    m.put("Crazy Archaeologist", VarbitID.CA_TOTAL_TASKS_COMPLETED_CRAZYARCHAEOLOGIST);
    m.put("Deranged Archaeologist", VarbitID.CA_TOTAL_TASKS_COMPLETED_DERANGEDARCHAEOLOGIST);
    m.put("Duke Sucellus", VarbitID.CA_TOTAL_TASKS_COMPLETED_DUKESUCELLUS);
    // GARGBOSS reads as "Gargoyle Boss": the Grotesque Guardians encounter (Dawn and
    // Dusk), not the plain slayer monster. The corpus itself proves which is right:
    // "Gargoyle" has exactly one task (not boss-shaped), "Grotesque Guardians" has 15.
    m.put("Grotesque Guardians", VarbitID.CA_TOTAL_TASKS_COMPLETED_GARGBOSS);
    // Gauntlet's normal and Corrupted modes have different boss forms and different
