package com.bankstand;

import java.util.Map;

/**
 * The last skill-XP vector the server acknowledged, used as a change gate so the
 * capture loop only submits when something moved. The plugin resets this on an
 * account switch and advances it only when a submit is acknowledged, so a dropped
 * submit is retried on the next capture (the baseline never moved).
 *
 * <p>Held as a digest rather than a copy, so the same value can be written to disk and
 * restored on the next start; without that, every start re-sends every block once. One
 * representation is what lets memory and disk agree by construction.
 */
public class SkillBaseline {
  private String acked;

  /** True when {@code current} differs from what the server last acknowledged. */
  public boolean changedSince(Map<String, Integer> current) {
    return !CapabilityDigest.of(current).equals(acked);
  }

  public void advance(Map<String, Integer> ackedNow) {
    acked = CapabilityDigest.of(ackedNow);
  }

  /** Restores a digest read back from disk. Null means nothing is known. */
  public void restore(String digest) {
    acked = digest;
  }

  /** The acknowledged digest, or null when nothing has been. */
  public String ackedDigest() {
    return acked;
  }

  public void reset() {
    acked = null;
  }
}

package com.bankstand;

/**
 * Decides whether a capture is allowed to submit at all.
 *
 * <p>The inner HTTP retry handles a blip within one submit. This handles the outer loop,
 * where the two real problems live. A revoked token fails fast inside the submit and
 * then the next capture tries again sixty seconds later, forever, with {@link
 * NoticeGate} making sure the player only ever hears about it once: a permanent,
 * invisible retry loop. And a server that has been down an hour is still being hit every
 * sixty seconds.
 *
 * <p>Counted in captures rather than milliseconds, because the capture schedule is the
 * only clock this has, and a duration-based backoff shorter than the schedule can never
 * elapse while one longer than it is just a skip count in disguise.
 *
 * <p>Not thread-safe; touched only from the client thread.
 */
public class SubmitGate {

  /** About sixteen minutes at a sixty second capture. */
  public static final int MAX_SKIPPED_CAPTURES = 15;

  private boolean halted;
  private int consecutiveFailures;
  private int skipsRemaining;

  /** True when this capture may submit. Consumes one skip when backing off. */
  public boolean allow() {
    if (halted) {
      return false;
    }
    if (skipsRemaining > 0) {
      skipsRemaining--;
      return false;
    }
    return true;
  }

  /** A reached server. Clears any backoff, but never the halt. */
  public void onSuccess() {
    consecutiveFailures = 0;
    skipsRemaining = 0;
  }

  /** A failure worth waiting out. Doubles the wait, to a cap. */
  public void onFailure() {
    consecutiveFailures++;
    skipsRemaining = Math.min(MAX_SKIPPED_CAPTURES, (1 << Math.min(consecutiveFailures, 5)) - 1);
  }

  /**
   * A rejected or revoked token. Returns true the first time, so the caller announces it
   * once rather than on every capture that then gets refused.
   */
  public boolean onAuthFailure() {
    boolean announce = !halted;
    halted = true;
    return announce;
  }

  /** Re-pairing, the only thing that clears a halt. */
  public void resume() {
    halted = false;
    consecutiveFailures = 0;
    skipsRemaining = 0;
  }

  public boolean isHalted() {
    return halted;
  }
}

package com.bankstand;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures a whole combat achievement TIER completing (all of that tier's tasks done), from
 * the game's own chat broadcast. Distinct from {@link CombatAchievementCompletionCapture}, which
 * captures a single task finishing; this one fires once per tier, when the last task in it is
 * done, and never carries a task identity.
 *
 * <p><b>The regex below is an unverified, best-effort guess, not a confirmed live capture.</b>
 * It is built from the one documented fragment available: RuneLite's own chat-notification
 * highlight pattern for this broadcast, "has completed the (\w*) tier of the Combat
 * Achievements". Two prior guesses in this exact file family, {@link
 * CombatAchievementCompletionCapture}'s CA_ID prefix handling and its leading icon-tag handling,
 * were both found to be wrong on the first guess and only fixed after a real live capture; treat
 * this one the same way. If a live capture later disagrees with this wording, the wording is
 * wrong, not the test: update both together.
 */
public class CombatAchievementTierCompletionCapture extends BaseCapture {

  // Unverified, best-effort guess (see the class javadoc): the trailing "!" is made optional
  // because nothing in the one documented fragment confirms it is always present.
  private static final Pattern TIER_COMPLETION_PATTERN =
      Pattern.compile(
          "^Congratulations, you have completed the (\\w+) tier of the Combat Achievements!?$");

  public CombatAchievementTierCompletionCapture(
      EventOutbox outbox, BooleanSupplier enabled, LongSupplier accountHash) {
    super(outbox, enabled, accountHash);
  }

  public CombatAchievementTierCompletionCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.GAMEMESSAGE) {
      return;
    }
    handleMessage(Text.removeTags(event.getMessage()));
  }

  /** Package-private, not private: the test calls this directly with plain strings. */
  void handleMessage(String message) {
    if (!isEnabled()) {
      return;
    }
    Matcher matcher = TIER_COMPLETION_PATTERN.matcher(message);
    if (!matcher.matches()) {
      return;
    }
    String tier = matcher.group(1).toLowerCase(Locale.ROOT);
    if (!CombatAchievementVarbits.ALL.containsKey(tier)) {
      return;
    }
    emit(TransientEvent.TYPE_COMBAT_ACHIEVEMENT_TIER_COMPLETED, payload(tier));
  }

  static Map<String, Object> payload(String tier) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("tier", tier);
    return payload;
  }
}

package com.bankstand;

import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import net.runelite.api.ItemComposition;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

/**
 * Captures notable drops: a unique or untradeable item on a curated
 * allowlist, or any tradeable drop whose total GE value clears a configurable
 * threshold.
 *
 * <p><b>Scope, deliberately narrow</b>, matching the issue: tradeable-value
 * threshold and a curated untradeable allowlist. Collection-log-unlock framing
 * and pet drops are NOT this class; a pet is a separate detector because
 * the first chat line never names it (prime-then-resolve), and a collection-log
 * "first observed" trigger would need to cross-reference the slot tracking
 * that already ships, which is a bigger, separate design question.
 *
 * <p><b>Only these two events, deliberately.</b> The built-in Loot Tracker
 * plugin's own {@code LootReceived} looked like a third source worth also
 * subscribing to, but it is not: Loot Tracker constructs and posts it from the
 * exact same NPC-kill and player-kill moments the client already posts as
 * {@link NpcLootReceived}/{@link PlayerLootReceived}, so subscribing to all
 * three double-fired {@link #handleLoot} for every qualifying drop, one call
 * per event. It covers no loot source the other two miss (chests and some
 * reward interfaces are not covered by any of them), so it added duplication
 * with no coverage in return. GE price is client-side and can differ from the
 * server's view at the moment of the drop.
 */
public class NotableDropCapture extends BaseCapture {

  private final ItemManager itemManager;
  private final LongSupplier thresholdValue;
  private final Set<String> untradeableAllowlist;

  public NotableDropCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      ItemManager itemManager,
      LongSupplier thresholdValue,
      Set<String> untradeableAllowlist) {
    super(outbox, enabled, accountHash);
    this.itemManager = itemManager;
    this.thresholdValue = thresholdValue;
    this.untradeableAllowlist = untradeableAllowlist;
  }

  public NotableDropCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      ItemManager itemManager,
      LongSupplier thresholdValue,
      Set<String> untradeableAllowlist,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
    this.itemManager = itemManager;
    this.thresholdValue = thresholdValue;
    this.untradeableAllowlist = untradeableAllowlist;
  }

  @Subscribe
  public void onNpcLootReceived(NpcLootReceived event) {
    handleLoot(event.getNpc().getName(), event.getItems());
  }

  @Subscribe
  public void onPlayerLootReceived(PlayerLootReceived event) {
    handleLoot(event.getPlayer().getName(), event.getItems());
  }

  /** Package-private, not private: {@code NotableDropCaptureTest} calls this directly
   *  with a poisoned {@code itemManager} to prove the gate below runs before any read. */
  void handleLoot(String source, Collection<ItemStack> items) {
    if (!isEnabled()) return;
    for (ItemStack stack : items) {
      ItemComposition comp = itemManager.getItemComposition(stack.getId());
      if (comp == null) continue;
      Long value =
          comp.isGeTradeable() ? (long) itemManager.getItemPrice(stack.getId()) : null;
      if (!qualifies(
          comp.getName(), comp.isGeTradeable(), value, stack.getQuantity(),
          thresholdValue.getAsLong(), untradeableAllowlist)) {
        continue;
      }
      emit(
          TransientEvent.TYPE_NOTABLE_DROP,
          payload(
              comp.getName(),
              stack.getId(),
              stack.getQuantity(),
              value == null ? null : value * stack.getQuantity(),
              source == null || source.isEmpty() ? "Unknown" : source));
    }
  }

  /**
   * Pure and tested without a live client. A tradeable item qualifies on total
   * value (unit price times quantity); an untradeable one has no GE price at
   * all, so it qualifies only by name on the curated allowlist. {@code value}
   * is the UNIT price here (multiplied by quantity by the caller for the final
   * payload), null exactly when the item is untradeable.
   */
  static boolean qualifies(
      String itemName,
      boolean tradeable,
      Long unitValue,
      int quantity,
      long thresholdValue,
      Set<String> untradeableAllowlist) {
    if (!tradeable || unitValue == null) {
      return untradeableAllowlist.contains(itemName);
    }
    return unitValue * quantity >= thresholdValue;
  }

  static Map<String, Object> payload(
      String itemName, int itemId, int quantity, Long totalValue, String source) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("itemName", itemName);
    payload.put("itemId", itemId);
    payload.put("quantity", quantity);
    payload.put("value", totalValue);
    payload.put("source", source);
    return payload;
  }
}

