/**
 * The plugin's sidebar panel (#1174): a single scrollable view answering "did my sync
 * actually work", reachable from a toolbar icon rather than a permanent tab. The
 * plugin's whole design otherwise is chat lines and {@code ::bstand} commands for
 * something looked at once per device, which is deliberate; this panel does not change
 * that, it just gives the same information a place to be read back without scrolling
 * chat history.
 *
 * <p>Renders entirely from a {@link PanelModel} snapshot handed in by {@link
 * #render}; holds no reference to the plugin, the client, or the config itself, so
 * what it draws can be reasoned about from a value alone. Rebuilds its content from
 * scratch on every render rather than patching it in place: a repaint happens at most
 * once a minute (the capture cadence) or on a user action, never per game tick, so
 * there is no performance reason to diff and patch instead.
 */
class BankstandPanel extends PluginPanel {

  private final Runnable onSyncNow;
  private final Runnable onOpenBankstand;
  private final Runnable onRequestRefresh;

  BankstandPanel(Runnable onSyncNow, Runnable onOpenBankstand, Runnable onRequestRefresh) {
    super();
    this.onSyncNow = onSyncNow;
    this.onOpenBankstand = onOpenBankstand;
    this.onRequestRefresh = onRequestRefresh;
    render(PanelModel.empty(""));
  }

  /** RuneLite calls this when the sidebar opens on this tab (a fresh open, or
   *  switching back to it from another plugin's tab), which is the one moment a
   *  player is looking at the panel without having just clicked a button in it. The
   *  plugin hops to the client thread to rebuild real state and back to the event
   *  dispatch thread to repaint; this call itself stays cheap and synchronous. */
  @Override
  public void onActivate() {
    onRequestRefresh.run();
  }

  /** Rebuilds the four blocks from the given snapshot and repaints. Must be called on
   *  the Swing event dispatch thread. */
  void render(PanelModel model) {
    removeAll();

    add(buildHeader(model));
    add(buildCapabilityList(model));
    add(buildRecentActivity(model));
    add(buildActions(model));

    revalidate();
    repaint();
  }

  private JPanel buildHeader(PanelModel model) {
    JPanel header = new JPanel();
    header.setLayout(new javax.swing.BoxLayout(header, javax.swing.BoxLayout.Y_AXIS));
    header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    header.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    JComponent dot = statusDot(dotColor(model.dot), dotTooltip(model));

    JLabel title = new JLabel(headerText(model));
    title.setFont(FontManager.getRunescapeBoldFont());
    title.setForeground(Color.WHITE);

    JPanel titleRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 0));
    titleRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    titleRow.add(dot);
    titleRow.add(title);
    header.add(leftAligned(titleRow));

    // Named here for the same reason StatusReport's own "Paired with X" line exists:
    // a stale or misconfigured server address otherwise fails every sync in silence.
    if (model.paired) {
      JLabel serverLine = new JLabel("Paired with " + model.serverUrl);
      serverLine.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
      serverLine.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
      header.add(leftAligned(serverLine));
    }

    return header;
  }

  private static String headerText(PanelModel model) {
    if (!model.paired) {
      return "Bankstand: not paired";
    }
    return model.linkedName == null ? "Bankstand" : "Bankstand: " + model.linkedName;
  }

  private static String dotTooltip(PanelModel model) {
    switch (model.dot) {
      case GREEN:
        return "Paired, last sync succeeded";
      case AMBER:
        return "Paired, the last sync attempt failed";
      case GREY:
      default:
        return model.paired ? "Paired, nothing has synced yet" : "Not paired";
    }
  }

  private static Color dotColor(PanelPresentation.SyncDot dot) {
    switch (dot) {
      case GREEN:
        return ColorScheme.PROGRESS_COMPLETE_COLOR;
      case AMBER:
        return Color.ORANGE;
      case GREY:
      default:
        // MEDIUM_GRAY_COLOR (77,77,77) on this panel's DARKER_GRAY_COLOR (30,30,30)
        // background is a ~2:1 contrast ratio, under WCAG's 3:1 floor for anything
        // meant to be seen. LIGHT_GRAY_COLOR is already this panel's own muted-text
        // colour (the paired-with line, timestamps, placeholders) and reads clearly.
        return ColorScheme.LIGHT_GRAY_COLOR;
    }
  }

  // A painted circle instead of a Unicode glyph ("●" in a bare JLabel, this
  // panel's original approach): glyph coverage for that character depends on
  // whatever font Swing falls back to for an unstyled label, and on a real client it
  // rendered nothing at all rather than merely the wrong colour. Painting it directly
  // has no font to get wrong.
  private static JComponent statusDot(Color color, String tooltip) {
    JComponent dot =
        new JComponent() {
          @Override
          protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(color);
            g2.fillOval(0, 3, 9, 9);
            g2.dispose();
          }
        };
    dot.setOpaque(false);
    dot.setPreferredSize(new Dimension(11, 16));
    dot.setToolTipText(tooltip);
    return dot;
  }

  private JPanel buildCapabilityList(PanelModel model) {
    JPanel section = new JPanel();
    section.setLayout(new javax.swing.BoxLayout(section, javax.swing.BoxLayout.Y_AXIS));
    section.setBackground(ColorScheme.DARK_GRAY_COLOR);
    section.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    section.add(leftAligned(sectionTitle("Capabilities")));

    if (model.capabilities.isEmpty()) {
      section.add(leftAligned(mutedLabel("Nothing switched on")));
    } else {
      long now = System.currentTimeMillis();
      for (PanelModel.CapabilityRow row : model.capabilities) {
        section.add(buildCapabilityRow(row, now));
      }
    }
    return section;
  }

  private JPanel buildCapabilityRow(PanelModel.CapabilityRow row, long now) {
    JPanel line = new JPanel(new BorderLayout());
    line.setBackground(ColorScheme.DARK_GRAY_COLOR);
    line.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));

    JLabel name = new JLabel(row.name);
    name.setForeground(Color.WHITE);

    // Never a number, and never "0m ago" for something that has not happened: absence
    // is a different fact from a fresh sync, the same "'—' rather than a false zero"
    // rule this plugin's own StatusReport already renders by for the collection log.
    JLabel synced =
        new JLabel(
            row.lastSyncedAtMs == null
                ? "—"
                : PanelPresentation.formatAge(now - row.lastSyncedAtMs));
    synced.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
    synced.setHorizontalAlignment(SwingConstants.RIGHT);

    line.add(name, BorderLayout.WEST);
    line.add(synced, BorderLayout.EAST);
    return line;
  }

  private JPanel buildRecentActivity(PanelModel model) {
    JPanel section = new JPanel();
    section.setLayout(new javax.swing.BoxLayout(section, javax.swing.BoxLayout.Y_AXIS));
    section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
    section.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    section.add(leftAligned(sectionTitle("Recent activity")));

    List<PanelModel.ActivityRow> recent = model.recentActivity;
    if (recent.isEmpty()) {
      section.add(leftAligned(mutedLabel("Nothing sent yet this session")));
    } else {
      long now = System.currentTimeMillis();
      for (PanelModel.ActivityRow row : recent) {
        JLabel label =
            new JLabel(row.description + " (" + PanelPresentation.formatAge(now - row.atMs) + ")");
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
        section.add(leftAligned(label));
      }
    }
    return section;
  }

  private JPanel buildActions(PanelModel model) {
    JPanel section = new JPanel();
    section.setLayout(new javax.swing.BoxLayout(section, javax.swing.BoxLayout.Y_AXIS));
    section.setBackground(ColorScheme.DARK_GRAY_COLOR);
    section.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

    JButton syncButton = new JButton("Sync now");
    syncButton.setFocusable(false);
    syncButton.addActionListener(e -> onSyncNow.run());

    JButton openButton = new JButton("Open Bankstand");
    openButton.setFocusable(false);
    openButton.addActionListener(e -> onOpenBankstand.run());

    JPanel buttons = new JPanel();
    buttons.setLayout(new javax.swing.BoxLayout(buttons, javax.swing.BoxLayout.Y_AXIS));
    buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
    buttons.add(syncButton);
    buttons.add(javax.swing.Box.createVerticalStrut(4));
    buttons.add(openButton);
    section.add(leftAligned(buttons));

    if (model.lastFailureReason != null) {
      JLabel failure = new JLabel("<html>" + escapeHtml(model.lastFailureReason) + "</html>");
      failure.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
      failure.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));
      section.add(leftAligned(failure));
    }

    return section;
  }

  private static JLabel sectionTitle(String text) {
    JLabel label = new JLabel(text);
    label.setFont(FontManager.getRunescapeBoldFont());
    label.setForeground(Color.WHITE);
    label.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
    return label;
  }

  private static JLabel mutedLabel(String text) {
    JLabel label = new JLabel(text);
    label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
    return label;
  }

  // BoxLayout's own per-child alignmentX is the textbook way to left-pin a component
  // narrower than its container, and it is what this file relied on before. In
  // practice, one label on a real client (this panel's own "Capabilities" heading)
  // still rendered centered after a clean rebuild, with no code-level difference from
  // a sibling heading built the exact same way that rendered correctly. The capability
  // rows never misrendered in testing, and they use BorderLayout, not alignmentX, so
  // this wraps every other label the same way rather than trying to explain the one
  // that did not listen.
  private static JPanel leftAligned(JComponent inner) {
    JPanel wrapper = new JPanel(new BorderLayout());
    wrapper.setOpaque(false);
    wrapper.add(inner, BorderLayout.WEST);
    return wrapper;
  }

  // A failure message is the server's or the HTTP client's own text, never
  // player-authored, but it still reaches an html-rendering JLabel: escape the handful
  // of characters that would otherwise be read as markup rather than pulling in a full
  // HTML escaper for a plugin with zero third-party runtime dependencies.
  private static String escapeHtml(String text) {
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
  }
}

package com.bankstand;

import java.util.Locale;

/**
 * Client-side handling of the short pairing code. Mirrors the Bankstand server's
 * {@code normalizePairingCode} exactly so the panel can validate input before a
 * request, and so the code sent over the wire is already canonical. The server
 * re-normalizes authoritatively, so this only ever repairs input, never mangles a
 * valid code.
 */
public final class PairingCodes {

  /**
   * Crockford base32 alphabet (digits plus letters, with I, L, O and U removed).
   * A generated code only ever uses these 32 symbols.
   */
  public static final String CROCKFORD_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

  /** A valid code is 8 symbols once normalized. */
  public static final int CODE_LENGTH = 8;

  private PairingCodes() {}

  /**
   * Upper-cases, strips whitespace and the display dash, then folds the Crockford
   * look-alikes (O to 0, I and L to 1). Identical to the server's normalization.
   */
  public static String normalize(String input) {
    if (input == null) {
      return "";
    }
    return input
        .toUpperCase(Locale.ROOT)
        .replaceAll("[\\s-]", "")
        .replace('O', '0')
        .replace('I', '1')
        .replace('L', '1');
  }

  /** True when {@code normalized} is exactly 8 characters, all in the Crockford alphabet. */
  public static boolean isValid(String normalized) {
    if (normalized == null || normalized.length() != CODE_LENGTH) {
      return false;
    }
    for (int i = 0; i < normalized.length(); i++) {
      if (CROCKFORD_ALPHABET.indexOf(normalized.charAt(i)) < 0) {
        return false;
      }
    }
    return true;
  }
}

package com.bankstand;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

/**
 * Reads and writes this client's pairing credentials.
 *
 * <p><b>A file, not {@code ConfigManager}, and that is the whole point of this class.</b>
 * {@code ConfigManager.saveConfiguration} checks {@code ConfigProfile.isSync()} and, when
 * the profile is synced, PATCHes the whole changed key set to RuneLite's own config
 * service. There is no per-key exclusion, so a plugin cannot mark one value local-only.
 * The device token is a bearer credential for the submit API, and a player who paired
 * with Bankstand did not agree to RuneLite storing that credential.
 *
 * <p>It also keeps several clients on one account working rather than breaking them. A
 * synced token gives every machine the same credential, which collapses them into one
 * {@code plugin_device} row: one name, one last-seen time, and revoking one revokes all.
 * Per-install storage is what lets each machine be its own device.
 *
 * <p>Every read failure resolves to "not paired", which asks the player to pair again
 * rather than sending with a credential we could not read. That is the safe direction:
 * the alternative is a submit loop against a token that may not be ours.
 *
 * <p>Not thread-safe across a save/clear racing a load; the plugin calls those from the
 * client thread and its executor, never concurrently for the same file. {@link #cached}
 * is {@code volatile} for a narrower reason: a pairing written on one thread must be
 * visible to the very next {@link #load()} on the other, with no other synchronization
 * between them, the same cross-thread guarantee {@code AccountSession.submitted} already
 * needs one for.
 */
public class DeviceCredentialStore {

  private final File file;
  private final Gson gson;

  // Every gate the plugin registers (isPaired() and its callers) reads the credential on
  // nearly every in-game event, so re-reading and re-parsing the file on each call cost
  // real client-thread time for no reason: the credential only ever changes via save/clear,
  // both of which keep this field in step. Null means "not yet loaded this session", not
  // "not paired": DeviceCredentials.none() is itself a valid cached value once a real read
  // (or a clear) has established that.
  private volatile DeviceCredentials cached;

  public DeviceCredentialStore(File file, Gson gson) {
    this.file = file;
    this.gson = gson;
  }

  /** Never null. */
  public DeviceCredentials load() {
    DeviceCredentials current = cached;
    if (current != null) {
      return current;
    }
    DeviceCredentials loaded = readFromDisk();
    cached = loaded;
    return loaded;
  }

  private DeviceCredentials readFromDisk() {
    if (!file.exists()) {
      return DeviceCredentials.none();
    }
    try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
      DeviceCredentials stored = gson.fromJson(reader, DeviceCredentials.class);
      return stored == null ? DeviceCredentials.none() : stored;
    } catch (IOException | RuntimeException e) {
      // Not logged, at any level: this file holds a credential.
      return DeviceCredentials.none();
    }
  }

  public void save(DeviceCredentials credentials) {
    Path target = file.toPath();
    Path directory = target.getParent();
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash midway leaves the previous pairing intact rather
      // than truncating the only copy of the token.
      Path temp = Files.createTempFile(directory, "device", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(credentials, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
      // Only on the success path: a save that threw below never touched disk, so the
      // cache must keep reflecting whatever WAS there, the same "previous pairing
      // intact" guarantee the temp-then-move above already gives the file itself.
      cached = credentials;
    } catch (IOException | RuntimeException e) {
      // Swallowed like every other write on this path. A pairing that failed to persist
      // costs one re-pair; throwing out of the pairing handler costs the chat reply that
      // tells the player what happened.
    }
  }

  /** Forgets this device's pairing. A missing file is already forgotten. */
  public void clear() {
    try {
      Files.deleteIfExists(file.toPath());
      cached = DeviceCredentials.none();
    } catch (IOException | RuntimeException e) {
      // Fall back to an empty document, so a delete the filesystem refuses still leaves
      // no usable credential behind. save() sets the cache itself on its own success path.
      save(DeviceCredentials.none());
    }
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * What the panel's "recent activity" block shows: a short, session-scoped list of named
 * things this device has sent, newest first. Not persisted, unlike {@link AckedState}'s
 * new {@code lastSyncedAt}: a restart has nothing to show and that is fine, the same way
 * every other purely in-memory piece of state in this plugin starts fresh on launch.
 *
 * <p>Deliberately not derived later from stored ids. A collection log unlock or a
 * combat achievement completion is captured with its human name right there in the chat
 * line; re-deriving a description afterwards from a persisted item id or task id would
 * need a lookup table this plugin does not keep, so {@link #describe} runs at the same
 * moment the event itself is built, off the exact payload that event carries.
 *
 * <p><b>Thread-safe</b> the same way {@link EventOutbox} is, and for the same reason:
 * {@link #record} runs from a capture's {@code @Subscribe} handler or a submit
 * acknowledgement, both on the client thread, while {@link #recent} runs from the Swing
 * event dispatch thread when the panel repaints. Each method is one read-modify-write
 * over the same list, so without synchronization a repaint racing a record could see a
 * torn list.
 */
final class RecentActivityLog {

  static final int MAX_ENTRIES = 10;

  private final LinkedList<PanelModel.ActivityRow> entries = new LinkedList<>();

  /** Adds one description as the newest entry, stamped with the moment it was recorded,
   *  evicting the oldest once full. */
  synchronized void record(String description) {
    entries.addFirst(new PanelModel.ActivityRow(description, System.currentTimeMillis()));
    while (entries.size() > MAX_ENTRIES) {
      entries.removeLast();
    }
  }

  /** Every recorded row, newest first. A snapshot: mutating the result does not affect
   *  the log. */
  synchronized List<PanelModel.ActivityRow> recent() {
    return new ArrayList<>(entries);
  }

  /** Forgets everything. Called on an account switch: an activity line left over from a
   *  different character reads as a bug on this one. */
  synchronized void clear() {
    entries.clear();
  }

  /**
   * The short human line a capture's own emit contributes to the panel, built from the
   * exact type and payload {@link TransientEvent} was constructed with.
   *
   * @return null for a type this method does not know how to describe, which the caller
   *     treats as "nothing to show" rather than a blank line. Every current {@link
   *     TransientEvent#TYPE_NOTABLE_DROP} type constant is covered; a future one added
   *     to the envelope without a case here simply stays silent on the panel, the same
   *     "under-reports rather than crashes" failure mode {@code capabilityNames} already
   *     accepts for the chat status line.
   */
  static String describe(String type, Map<String, Object> payload) {
    switch (type) {
      case TransientEvent.TYPE_COLLECTION_LOG_UNLOCK:
        return "Collection log: " + payload.get("itemName");
      case TransientEvent.TYPE_COMBAT_ACHIEVEMENT_COMPLETED:
        return "Combat achievements: " + payload.get("taskName") + " completed";
      case TransientEvent.TYPE_DIARY_TASK_COMPLETED:
        return "Diaries: "
            + capitalize(String.valueOf(payload.get("tier")))
            + " task completed in "
            + payload.get("area");
      case TransientEvent.TYPE_NOTABLE_DROP:
        return "Notable drop: " + payload.get("itemName");
      case TransientEvent.TYPE_PET_DROP:
        return "Pet drop: " + payload.get("petName");
      default:
        return null;
    }
  }

  private static String capitalize(String word) {
    if (word.isEmpty()) {
      return word;
    }
    return word.substring(0, 1).toUpperCase(Locale.ROOT) + word.substring(1);
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;

/**
 * Maps the server's diary wire keys to the varbit holding how many of that tier's tasks
 * are done.
 *
 * <p><b>The second of the three varbits per tier</b>, and the one that makes a partly
 * finished tier expressible at all. {@link DiaryVarbits} reads {@code *_COMPLETE}, which
 * is true only when every task is done, so a tier at 21 of 22 has been reporting as
 * nothing. This table is what fixes that, and it is a table extension rather than a
 * research project: the counts exist for all 48 tiers and RuneLite names every one.
 *
 * <p><b>These are counts, not task identities.</b> A tier reading 21 says nothing about
 * which 21, exactly as the combat achievement tier counts do not say which tasks moved.
 * Per-task state remains unresolved, and the reader's per-task marks stay unmarked.
 *
 * <p>Wire keys match {@link DiaryVarbits} exactly, because the two halves describe the
 * same 48 tiers and a key that existed in one and not the other would be a tier whose
 * count could never be joined to its completion flag. {@code DiaryTaskVarbitsTest}
 * asserts they agree rather than leaving it to review.
 *
 * <p>Names differ from the completion table in two ways worth knowing. These come from
 * the newer {@code VarbitID} table rather than {@code Varbits}, which is where the counts
 * are named; and the tier is spelled {@code MED} rather than {@code MEDIUM}. Three
 * regions are renamed to the wire key for the same reason as next door: KOUREND becomes
 * KOUREND_KEBOS, LUMBRIDGE becomes LUMBRIDGE_DRAYNOR, WESTERN becomes WESTERN_PROVINCES.
 *
 * <p>Karamja's easy count sits at 2423, far outside the 6288-6330 block the rest occupy,
 * because its diary predates them. That is the same split the completion table documents
 * and is not a sign of a wrong id.
 *
 * <p>A plain data table with no {@code Client} dependency, so it is unit-testable without
 * a live game client.
 */
public final class DiaryTaskVarbits {
  private DiaryTaskVarbits() {}

  /** Ordered, unmodifiable: wire key to the varbit holding that tier's completed count. */
  public static final Map<String, Integer> ALL = Collections.unmodifiableMap(build());

  private static Map<String, Integer> build() {
    Map<String, Integer> m = new LinkedHashMap<>();
    region(m, "ARDOUGNE", VarbitID.ARDOUGNE_EASY_COUNT, VarbitID.ARDOUGNE_MED_COUNT,
        VarbitID.ARDOUGNE_HARD_COUNT, VarbitID.ARDOUGNE_ELITE_COUNT);
    region(m, "DESERT", VarbitID.DESERT_EASY_COUNT, VarbitID.DESERT_MED_COUNT,
        VarbitID.DESERT_HARD_COUNT, VarbitID.DESERT_ELITE_COUNT);
    region(m, "FALADOR", VarbitID.FALADOR_EASY_COUNT, VarbitID.FALADOR_MED_COUNT,
        VarbitID.FALADOR_HARD_COUNT, VarbitID.FALADOR_ELITE_COUNT);
    region(m, "FREMENNIK", VarbitID.FREMENNIK_EASY_COUNT, VarbitID.FREMENNIK_MED_COUNT,
        VarbitID.FREMENNIK_HARD_COUNT, VarbitID.FREMENNIK_ELITE_COUNT);
    region(m, "KANDARIN", VarbitID.KANDARIN_EASY_COUNT, VarbitID.KANDARIN_MED_COUNT,
        VarbitID.KANDARIN_HARD_COUNT, VarbitID.KANDARIN_ELITE_COUNT);
    region(m, "KOUREND_KEBOS", VarbitID.KOUREND_EASY_COUNT, VarbitID.KOUREND_MED_COUNT,
        VarbitID.KOUREND_HARD_COUNT, VarbitID.KOUREND_ELITE_COUNT);
    region(m, "LUMBRIDGE_DRAYNOR", VarbitID.LUMBRIDGE_EASY_COUNT, VarbitID.LUMBRIDGE_MED_COUNT,
        VarbitID.LUMBRIDGE_HARD_COUNT, VarbitID.LUMBRIDGE_ELITE_COUNT);
    region(m, "MORYTANIA", VarbitID.MORYTANIA_EASY_COUNT, VarbitID.MORYTANIA_MED_COUNT,
        VarbitID.MORYTANIA_HARD_COUNT, VarbitID.MORYTANIA_ELITE_COUNT);
    region(m, "VARROCK", VarbitID.VARROCK_EASY_COUNT, VarbitID.VARROCK_MED_COUNT,
        VarbitID.VARROCK_HARD_COUNT, VarbitID.VARROCK_ELITE_COUNT);
    region(m, "WESTERN_PROVINCES", VarbitID.WESTERN_EASY_COUNT, VarbitID.WESTERN_MED_COUNT,
        VarbitID.WESTERN_HARD_COUNT, VarbitID.WESTERN_ELITE_COUNT);
    region(m, "WILDERNESS", VarbitID.WILDERNESS_EASY_COUNT, VarbitID.WILDERNESS_MED_COUNT,
        VarbitID.WILDERNESS_HARD_COUNT, VarbitID.WILDERNESS_ELITE_COUNT);
    region(m, "KARAMJA", VarbitID.KARAMJA_EASY_COUNT, VarbitID.KARAMJA_MED_COUNT,
        VarbitID.KARAMJA_HARD_COUNT, VarbitID.KARAMJA_ELITE_COUNT);
    return m;
  }

  private static void region(Map<String, Integer> m, String key, int easy, int medium, int hard,
      int elite) {
    m.put(key + "_EASY", easy);
    m.put(key + "_MEDIUM", medium);
    m.put(key + "_HARD", hard);
    m.put(key + "_ELITE", elite);
  }
}

package com.bankstand;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * The append-only outbox for {@link TransientEvent}s. Not a coalescing
 * 4-slot structure like the skills/quests/diaries snapshot outbox: each
 * event is a distinct, one-shot fact, so a newer one cannot overwrite an older
 * one the way a fresher skill total can.
 *
 * <p><b>Ordered</b>: entries are appended and drained oldest-first, so a batch
 * submit reports events in the order they happened.
 *
 * <p><b>Bounded, with an explicit and logged drop policy</b>: capped at {@link
 * #MAX_PENDING}. A full outbox drops the OLDEST entry to make room for the
 * newest, logged via {@code log.warn} because a silently dropped drop is worse
 * than a noisy one. This is the honest trade-off named in the design: a client
 * offline long enough to overflow the cap loses the oldest of what it saw,
 * rather than growing without limit or losing the newest instead.
 *
 * <p><b>A file, not {@code ConfigManager}</b>, for the same reason {@link
 * DeviceCredentialStore} and {@link AckedStateStore} are: pending state IS the
 * player's captured game data, and a synced profile PATCHes its whole config to
 * RuneLite's own service with no per-key exclusion.
 *
 * <p><b>Thread-safe.</b> {@link #add} runs synchronously inside a capture's {@code
 * @Subscribe} handler, on the client thread; {@link #pending} and {@link #ack} run
 * from {@code drainEventOutbox}'s {@code @Schedule} callback and its executor
 * continuation, off the client thread (the same split {@code captureSkills}' own
 * {@code clientThread.invokeLater} hop exists to bridge). Each public method is one
 * read-modify-write against the same file, so without a lock a drop captured
 * between a drain's read and its write is silently and permanently overwritten:
 * proven by {@code EventOutboxTest#concurrentAddAndAckDoNotLoseEntries}, which
 * fails on an unsynchronized version of this class.
 */
@Slf4j
public class EventOutbox {

  static final int MAX_PENDING = 200;

  private static final Type LIST_TYPE = new TypeToken<ArrayList<OutboxEntry>>() {}.getType();

  private final File file;
  private final Gson gson;

  public EventOutbox(File file, Gson gson) {
    this.file = file;
    this.gson = gson;
  }

  /** Appends one event, evicting the oldest pending entry (logged) if this overflows the cap. */
  public synchronized void add(long accountHash, TransientEvent event) {
    List<OutboxEntry> entries = read();
    entries.add(new OutboxEntry(accountHash, event));
    while (entries.size() > MAX_PENDING) {
      OutboxEntry dropped = entries.remove(0);
      log.warn(
          "event outbox full ({} pending): dropped oldest entry, type={}",
          MAX_PENDING,
          dropped.getEvent().getType());
    }
    write(entries);
  }

  /** Every pending entry, oldest first. A snapshot: mutating the result does not persist. */
  public synchronized List<OutboxEntry> pending() {
    return read();
  }

  /** Removes exactly the entries whose event id is in {@code ids}: ordinarily because
   *  the server stored them, but a caller may also include an id it has decided is
   *  permanently undeliverable (a stale rejection, say), since retrying that forever
   *  would only waste outbox capacity on something that can never be stored. Leaves
   *  the rest, in order, for the next drain. */
  public synchronized void ack(Set<String> ids) {
    if (ids.isEmpty()) return;
    List<OutboxEntry> entries = read();
    entries.removeIf(entry -> ids.contains(entry.getEvent().getId()));
    write(entries);
  }

  /** Forgets every pending event. Not called on an account switch: unlike the skills
   *  baseline, an event already happened and stays true for whichever character it
   *  was tagged under (see {@link OutboxEntry}), so a relog must not lose it. */
  public synchronized void clear() {
    write(Collections.emptyList());
  }

  private List<OutboxEntry> read() {
    if (!file.exists()) {
      return new ArrayList<>();
    }
    try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8)) {
      List<OutboxEntry> stored = gson.fromJson(reader, LIST_TYPE);
      return stored == null ? new ArrayList<>() : new ArrayList<>(stored);
    } catch (IOException | RuntimeException e) {
      // Not logged at more than debug: this file holds the player's captured drops.
      log.debug("event outbox unreadable, treating as empty: {}", e.getMessage());
      return new ArrayList<>();
    }
  }

  private void write(List<OutboxEntry> entries) {
    Path target = file.toPath();
    Path directory = target.getParent();
    try {
      if (directory != null) {
        Files.createDirectories(directory);
      }
      // Temp then move, so a crash mid-write leaves the previous outbox intact
      // rather than truncating it.
      Path temp = Files.createTempFile(directory, "events", ".tmp");
      try (Writer writer = Files.newBufferedWriter(temp, StandardCharsets.UTF_8)) {
        gson.toJson(entries, LIST_TYPE, writer);
      }
      try {
        Files.move(
            temp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
      } catch (AtomicMoveNotSupportedException e) {
        Files.move(temp, target, StandardCopyOption.REPLACE_EXISTING);
      }
    } catch (IOException | RuntimeException e) {
      // Swallowed like every other write on this path. A drop that failed to persist
      // costs one lost event on the next crash; throwing out of a capture handler
      // costs every detector behind it on the same tick.
      log.debug("event outbox write failed: {}", e.getMessage());
    }
  }

  static Set<String> toIdSet(Iterable<String> ids) {
    Set<String> set = new HashSet<>();
    for (String id : ids) set.add(id);
    return set;
  }
}

