package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.Set;

/**
 * The collection log items observed on this account so far.
 *
 * <p>Unlike every other capability, this ACCUMULATES rather than snapshots. Skills,
 * quests and diaries are read whole on every capture, so a fresh read legitimately
 * replaces the last one. The collection log is not resident in the client: the game
 * only reveals it while the log interface enumerates, and an enumeration can be
 * partial (a cancelled search, one page browsed). Replacing on a partial read would
 * discard everything previously known, so a read only ever adds.
 *
 * <p>Ownership of an item is also one-way. Nothing in the game removes an entry from
 * a collection log, so "observed once" stays true and there is no un-set to model.
 *
 * <p>The corollary is that this cannot report absence. Not-yet-seen and not-owned are
 * indistinguishable from here, which is why the server treats an omitted item as "not
 * observed" and never as "does not have it".
 */
public class CollectionLogAccumulator {
  private final Set<Integer> observed = new LinkedHashSet<>();

  /** Records one item the client enumerated. Returns true when it was not already known. */
  public boolean observe(int itemId) {
    return observed.add(itemId);
  }

  /** Every item observed so far, in first-seen order. */
  public Set<Integer> observed() {
    return Collections.unmodifiableSet(observed);
  }

  public int size() {
    return observed.size();
  }

  public boolean isEmpty() {
    return observed.isEmpty();
  }

  /**
   * Restores items read back from disk. The one capability that must persist: the others
   * are re-read live next capture, but the game reveals the log only while the player is
   * looking at it, so an observation lost to a restart cannot be asked for again.
   */
  public void restore(Set<Integer> items) {
    observed.clear();
    observed.addAll(items);
  }

  /**
   * Forgets everything. Called on an account switch: a collection log belongs to one
   * character, and carrying it across would attribute one account's items to another.
   */
  public void reset() {
    observed.clear();
  }
}

package com.bankstand;

import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * What one character has already had accepted by the server, and what its client has
 * observed, in the form that survives a restart.
 *
 * <p>Two kinds of thing live here and the difference matters. The three digests are
 * *verdicts*: skills, quests and diaries are re-read live on every capture, so losing a
 * digest costs one redundant submission and nothing else. The collection log entries
 * are *observations*: the game reveals the log only while the player is looking at it,
 * so losing them cannot be recovered by asking the client again.
 *
 * <p><b>{@code collectionLogAcked} and {@code collectionLogItems} must persist together
 * or not at all.</b> The acked figure is a count over the observed set, valid only while
 * that set grows monotonically. Persist the count while the set resets and a later
 * partial browse reads as a change and churns every session; persist the set while
 * deriving the count from it and a log whose submission failed is silently treated as
 * delivered and never sent again. A baseline and the state it is a baseline of need the
 * same lifetime.
 *
 * <p>Gson populates this by field, so the field names are the on-disk format.
 */
public class AckedState {

  private String skills;
  private String quests;
  private String diaries;
  private String combatAchievements;

  /**
   * The last account type the server acknowledged.
   *
   * <p>The value itself, not a digest, unlike every collection-shaped field here: it is
   * one short word, so hashing it would cost the ability to read this file in a bug
   * report and buy nothing.
   */
  private String accountType;
  private Set<Integer> collectionLogItems;
  private int collectionLogAcked;

  /**
   * When each capability last had a fresh acknowledgement from the server, epoch millis,
   * keyed by the same capability name {@code manifest.allows(...)} and {@code
   * SubmitSnapshotResponse#isBlockStored(...)} already use ("skills", "collectionLog", and
   * so on).
   *
   * <p>A digest says whether a capability's last-known value differs from what the server
   * has; it says nothing about when that last happened, which is what the panel's
   * per-capability list needs. Stamped only on a cycle where the server actually
   * acknowledged fresh data for that capability, never on a resend of something already
   * acknowledged, so it answers "when did this last genuinely sync" rather than "when did
   * the plugin last try".
   */
  private Map<String, Long> lastSyncedAt;

  /**
   * Last-known value of every diary varplayer read so far, keyed by varplayer id. A raw
   * value rather than a digest, because {@link DiaryTaskCompletionCapture}'s per-task
   * identity resolution needs the actual prior bit pattern to XOR against. See
   * {@link DiaryTaskBits} for why this has to survive a restart, same as
   * {@code collectionLogItems}.
   */
  private Map<Integer, Integer> diaryTaskBits;

  /** The state of a character nothing is known about yet: everything resends once. */
  public static AckedState empty() {
    AckedState state = new AckedState();
    state.collectionLogItems = new LinkedHashSet<>();
    state.collectionLogAcked = -1;
    state.lastSyncedAt = new LinkedHashMap<>();
    state.diaryTaskBits = new LinkedHashMap<>();
    return state;
  }

  public String getSkills() {
    return skills;
  }

  public void setSkills(String skills) {
    this.skills = skills;
  }

  public String getQuests() {
    return quests;
  }

  public void setQuests(String quests) {
    this.quests = quests;
  }

  public String getDiaries() {
    return diaries;
  }

  public void setDiaries(String diaries) {
    this.diaries = diaries;
  }

  public String getCombatAchievements() {
    return combatAchievements;
  }

  public void setCombatAchievements(String combatAchievements) {
    this.combatAchievements = combatAchievements;
  }

  public String getAccountType() {
    return accountType;
  }

  public void setAccountType(String accountType) {
    this.accountType = accountType;
  }

  /**
   * Never null, even when the stored document omitted the field or set it null, so a
   * hand-edited or older file cannot hand a caller a null set to iterate.
   */
  public Set<Integer> getCollectionLogItems() {
    if (collectionLogItems == null) {
      collectionLogItems = new LinkedHashSet<>();
    }
    return collectionLogItems;
  }

  public void setCollectionLogItems(Set<Integer> items) {
    this.collectionLogItems = new LinkedHashSet<>(items);
  }

  /** The observed count the server last acknowledged, or -1 for none. */
  public int getCollectionLogAcked() {
    return collectionLogAcked;
  }

  public void setCollectionLogAcked(int acked) {
    this.collectionLogAcked = acked;
  }

  /**
   * Never null, even when the stored document omitted the field or set it null, so a
   * hand-edited or older file cannot hand a caller a null map to iterate.
   */
  public Map<String, Long> getLastSyncedAt() {
    if (lastSyncedAt == null) {
      lastSyncedAt = new LinkedHashMap<>();
    }
    return lastSyncedAt;
  }

  /** Copied, so a caller mutating the map it passed in cannot reach back into this state. */
  public void setLastSyncedAt(Map<String, Long> lastSyncedAt) {
    this.lastSyncedAt = new LinkedHashMap<>(lastSyncedAt);
  }

  /**
   * Never null, even when the stored document omitted the field or set it null, so a
   * hand-edited or older file cannot hand a caller a null map to iterate.
   */
  public Map<Integer, Integer> getDiaryTaskBits() {
    if (diaryTaskBits == null) {
      diaryTaskBits = new LinkedHashMap<>();
    }
    return diaryTaskBits;
  }

  public void setDiaryTaskBits(Map<Integer, Integer> bits) {
    this.diaryTaskBits = new LinkedHashMap<>(bits);
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Builds the v1 skills-submit envelope as an ordered map, ready for Gson. The
 * account hash is emitted as a decimal string because a 64-bit value does not fit
 * a JSON number safely, matching the server's contract. The shape is frozen; see
 * the mirrored contract fixtures under src/test/resources/contracts.
 */
public final class SubmitEnvelope {
  private SubmitEnvelope() {}

  public static final int SCHEMA_VERSION = 1;

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, null, null, null, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, collectionLogItems, null, null, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems,
      Map<String, Integer> combatAchievementCounts,
      Map<String, Integer> diaryTaskCounts,
      String accountType) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, collectionLogItems, combatAchievementCounts, diaryTaskCounts,
        accountType, false);
  }

  /** Kept for callers built before {@code combatAchievementBossCounts} existed. */
  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems,
      Map<String, Integer> combatAchievementCounts,
      Map<String, Integer> diaryTaskCounts,
      String accountType,
      boolean fullEnumeration) {
    return body(
        submissionId, schemaVersion, pluginVersion, capturedAt, accountHash, displayName, skillXp,
        questStates, diaryStates, collectionLogItems, combatAchievementCounts, diaryTaskCounts,
        accountType, fullEnumeration, null);
  }

  public static Map<String, Object> body(
      String submissionId,
      int schemaVersion,
      String pluginVersion,
      String capturedAt,
      long accountHash,
      String displayName,
      Map<String, Integer> skillXp,
      Map<String, String> questStates,
      Map<String, String> diaryStates,
      Collection<Integer> collectionLogItems,
      Map<String, Integer> combatAchievementCounts,
      Map<String, Integer> diaryTaskCounts,
      String accountType,
      boolean fullEnumeration,
      Map<String, Integer> combatAchievementBossCounts) {
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("submissionId", submissionId);
    body.put("schemaVersion", schemaVersion);
    body.put("pluginVersion", pluginVersion);
    body.put("capturedAt", capturedAt);
    body.put("accountHash", Long.toString(accountHash));
    if (displayName != null && !displayName.trim().isEmpty()) {
      body.put("displayName", displayName);
    }
    Map<String, Object> skills = new LinkedHashMap<>();
    for (Map.Entry<String, Integer> e : skillXp.entrySet()) {
      Map<String, Object> stat = new LinkedHashMap<>();
      stat.put("xp", e.getValue());
      skills.put(e.getKey(), stat);
    }
    body.put("skills", skills);
    if (questStates != null && !questStates.isEmpty()) {
      body.put("quests", new LinkedHashMap<>(questStates));
    }
    if (diaryStates != null && !diaryStates.isEmpty()) {
      body.put("diaries", new LinkedHashMap<>(diaryStates));
    }
    // How many of each tier's tasks are done, which is what makes a tier at 21 of 22
    // expressible at all: the completion flag above is true only when every task is
    // done, so a partly finished tier has been reporting as nothing. Counts, never
    // task identities. Omitted when empty like every other block, and for the same
    // reason: empty means "not observed", not "none done".
    if (diaryTaskCounts != null && !diaryTaskCounts.isEmpty()) {
      body.put("diaryTasks", new LinkedHashMap<>(diaryTaskCounts));
    }
    // An array, not a map: this capability records presence only. Omitted when empty
    // for the same reason as every other block, and the reason is load-bearing here
    // too: an empty block means "not observed", and the server would otherwise have
    // to distinguish that from "owns nothing".
    if (collectionLogItems != null && !collectionLogItems.isEmpty()) {
      body.put("collectionLog", new ArrayList<>(collectionLogItems));
      // Present, and true, only on a submission that rode a COMPLETE guided read:
      // the game's Search interface was seen open while entries streamed, not
      // incidental page browsing. Never sent false; a partial or ordinary read has
      // nothing to assert here, the same "absence means not observed" rule the rest
      // of this envelope follows for every other block.
      if (fullEnumeration) {
        body.put("collectionLogFullyEnumerated", true);
      }
    }
    // Per-tier completed COUNTS, which is all the game exposes. Omitted when empty
    // for the same reason as every other block: an empty block means "not observed",
    // and the server treats a present-but-empty one as an erase.
    if (combatAchievementCounts != null && !combatAchievementCounts.isEmpty()) {
      body.put("combatAchievements", new LinkedHashMap<>(combatAchievementCounts));
    }
    // How many of each VERIFIED boss/activity's tasks are done, keyed by the corpus's
    // own source name (see CombatAchievementBossVarbits). Rides on the same
    // "omitted when empty means not observed" rule as diaryTasks above, for the same
    // reason.
    if (combatAchievementBossCounts != null && !combatAchievementBossCounts.isEmpty()) {
      body.put("combatAchievementBossCounts", new LinkedHashMap<>(combatAchievementBossCounts));
    }
    // One word, and the only block that is not a collection: the game has exactly one
    // answer. Sent because the hiscores cannot answer it at all for a Group Ironman,
    // who is absent from the ironman boards and so reads as a main everywhere public.
    //
    // Null when the varbit held a value this build has no name for, per
    // AccountTypes.keyFor, which is the same "omit rather than guess" the blocks
    // above use for empty. A wrong type is worse than no type: it is the badge on
    // the player's own profile.
    if (accountType != null && !accountType.isEmpty()) {
      body.put("accountType", accountType);
    }
    return body;
  }
}

package com.bankstand;

import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * One discrete, one-shot fact for the outbox: a notable drop, a pet drop,
 * and whatever else joins later. Unlike the skills/quests/diaries snapshot, this
 * is never overwritten by a newer capture of the same thing; each occurrence is
 * its own event with its own {@link UuidV7} id, which is what lets the server ack
 * (and the outbox drop) entries independently rather than as one submission.
 *
 * <p>Immutable and Gson-serializable as-is: the field names here are exactly the
 * wire shape {@code lib/plugin/events-envelope.ts} validates, so no separate DTO
 * mapping step exists to drift from it.
 */
public final class TransientEvent {

  public static final String TYPE_NOTABLE_DROP = "notable_drop";
  public static final String TYPE_PET_DROP = "pet_drop";
  public static final String TYPE_COLLECTION_LOG_UNLOCK = "collection_log_unlock";
  public static final String TYPE_COMBAT_ACHIEVEMENT_COMPLETED = "combat_achievement_completed";
  public static final String TYPE_COMBAT_ACHIEVEMENT_TIER_COMPLETED =
      "combat_achievement_tier_completed";
  public static final String TYPE_DIARY_TASK_COMPLETED = "diary_task_completed";

  private final String id;
  private final String type;
  private final String occurredAt;
  private final Map<String, Object> payload;

  public TransientEvent(String type, Map<String, Object> payload) {
    this(UuidV7.generate(), type, Instant.now().toString(), payload);
  }

  /** For deserializing a persisted entry, where the id and time must survive a restart. */
  public TransientEvent(String id, String type, String occurredAt, Map<String, Object> payload) {
    this.id = id;
    this.type = type;
    this.occurredAt = occurredAt;
    this.payload = new LinkedHashMap<>(payload);
  }

  public String getId() {
    return id;
  }

  public String getType() {
    return type;
  }

  public String getOccurredAt() {
    return occurredAt;
  }

  public Map<String, Object> getPayload() {
    return payload;
  }
}

package com.bankstand;

import java.util.Map;

/**
 * The last diary-state vector the server acknowledged, used as a change gate so the
 * capture loop only submits when something moved. The plugin resets this on an
 * account switch and advances it only when a submit is acknowledged, so a dropped
 * submit is retried on the next capture (the baseline never moved).
 *
 * <p>Held as a digest rather than a copy of the vector, so the same value can be
 * written to disk and restored on the next client start. See {@link SkillBaseline} for
 * why one representation across memory and disk is worth a hash.
 */
public class DiaryBaseline {
  private String acked;

  /** True when {@code current} differs from what the server last acknowledged. */
  public boolean changedSince(Map<String, String> current) {
    return !CapabilityDigest.of(current).equals(acked);
  }

  public void advance(Map<String, String> ackedNow) {
    acked = CapabilityDigest.of(ackedNow);
  }

  /** Restores a digest read back from disk. Null means nothing is known. */
  public void restore(String digest) {
    acked = digest;
  }

  /** The acknowledged digest, or null when nothing has been. */
  public String ackedDigest() {
    return acked;
  }

  public void reset() {
    acked = null;
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Varbits;

/**
 * Maps the server's diary wire keys to the varbit that carries each tier's completion
 * flag. Bankstand derives its wire keys from its own guide slugs, not from the
 * RuneLite {@link Varbits} constant names, so three regions are renamed here:
 * KOUREND becomes KOUREND_KEBOS, LUMBRIDGE becomes LUMBRIDGE_DRAYNOR, and WESTERN
 * becomes WESTERN_PROVINCES. The other nine regions keep their name.
 *
 * <p>All 48 tiers are captured, Karamja included. Its easy/medium/hard flags do sit
 * outside the 4458-4498 block the other regions occupy, at 3578/3599/3611, because the
 * Karamja diary predates that block. They were once excluded on the theory that they
 * were task counters rather than completion flags; the newer {@code VarbitID} table
 * disproves it by naming those exact ids {@code ATJUN_EASY_DONE},
 * {@code ATJUN_MED_DONE} and {@code ATJUN_HARD_DONE}. The {@code KARAMJA_*_COUNT}
 * varbits that prompted the doubt are separate ids entirely (2423/6288/6289/6290), so
 * reading 3578 never reports a diary complete on a single task.
 *
 * <p>Worth knowing for anything built on top: the game keeps THREE varbits per tier,
 * and this table reads only the first. {@code *_COMPLETE} (here) means every task is
 * done. {@code *_REWARD} is a separate flag for whether the player has claimed the
 * rewards from the taskmaster. {@code *_COUNT} holds how many of the tier's tasks are
 * done, and exists for all 48 tiers. A tier can therefore be complete but unclaimed,
 * which this table alone cannot express.
 *
 * <p>A plain data table with no {@code Client} dependency, so it is unit-testable
 * without a live game client.
 */
public final class DiaryVarbits {
  private DiaryVarbits() {}

  private static final Map<String, Integer> BY_WIRE_KEY = build();

  /** Ordered, unmodifiable: wire key (server's contract) to varbit id. */
  public static final Map<String, Integer> ALL = Collections.unmodifiableMap(BY_WIRE_KEY);

  private static Map<String, Integer> build() {
    Map<String, Integer> m = new LinkedHashMap<>();
    region(m, "ARDOUGNE", Varbits.DIARY_ARDOUGNE_EASY, Varbits.DIARY_ARDOUGNE_MEDIUM,
        Varbits.DIARY_ARDOUGNE_HARD, Varbits.DIARY_ARDOUGNE_ELITE);
    region(m, "DESERT", Varbits.DIARY_DESERT_EASY, Varbits.DIARY_DESERT_MEDIUM,
        Varbits.DIARY_DESERT_HARD, Varbits.DIARY_DESERT_ELITE);
    region(m, "FALADOR", Varbits.DIARY_FALADOR_EASY, Varbits.DIARY_FALADOR_MEDIUM,
        Varbits.DIARY_FALADOR_HARD, Varbits.DIARY_FALADOR_ELITE);
    region(m, "FREMENNIK", Varbits.DIARY_FREMENNIK_EASY, Varbits.DIARY_FREMENNIK_MEDIUM,
        Varbits.DIARY_FREMENNIK_HARD, Varbits.DIARY_FREMENNIK_ELITE);
    region(m, "KANDARIN", Varbits.DIARY_KANDARIN_EASY, Varbits.DIARY_KANDARIN_MEDIUM,
        Varbits.DIARY_KANDARIN_HARD, Varbits.DIARY_KANDARIN_ELITE);
    // KOUREND is the RuneLite constant prefix; the wire key is KOUREND_KEBOS.
    region(m, "KOUREND_KEBOS", Varbits.DIARY_KOUREND_EASY, Varbits.DIARY_KOUREND_MEDIUM,
        Varbits.DIARY_KOUREND_HARD, Varbits.DIARY_KOUREND_ELITE);
    // LUMBRIDGE is the RuneLite constant prefix; the wire key is LUMBRIDGE_DRAYNOR.
    region(m, "LUMBRIDGE_DRAYNOR", Varbits.DIARY_LUMBRIDGE_EASY, Varbits.DIARY_LUMBRIDGE_MEDIUM,
        Varbits.DIARY_LUMBRIDGE_HARD, Varbits.DIARY_LUMBRIDGE_ELITE);
    region(m, "MORYTANIA", Varbits.DIARY_MORYTANIA_EASY, Varbits.DIARY_MORYTANIA_MEDIUM,
        Varbits.DIARY_MORYTANIA_HARD, Varbits.DIARY_MORYTANIA_ELITE);
    region(m, "VARROCK", Varbits.DIARY_VARROCK_EASY, Varbits.DIARY_VARROCK_MEDIUM,
        Varbits.DIARY_VARROCK_HARD, Varbits.DIARY_VARROCK_ELITE);
    // WESTERN is the RuneLite constant prefix; the wire key is WESTERN_PROVINCES.
    region(m, "WESTERN_PROVINCES", Varbits.DIARY_WESTERN_EASY, Varbits.DIARY_WESTERN_MEDIUM,
        Varbits.DIARY_WESTERN_HARD, Varbits.DIARY_WESTERN_ELITE);
    region(m, "WILDERNESS", Varbits.DIARY_WILDERNESS_EASY, Varbits.DIARY_WILDERNESS_MEDIUM,
        Varbits.DIARY_WILDERNESS_HARD, Varbits.DIARY_WILDERNESS_ELITE);
    // Karamja's easy/medium/hard flags sit outside the block the other regions use
    // (3578/3599/3611 rather than 4458-4498), because its diary predates them. They
    // are still completion flags. See the class comment.
    region(m, "KARAMJA", Varbits.DIARY_KARAMJA_EASY, Varbits.DIARY_KARAMJA_MEDIUM,
        Varbits.DIARY_KARAMJA_HARD, Varbits.DIARY_KARAMJA_ELITE);
    return m;
  }

  private static void region(
      Map<String, Integer> m, String prefix, int easy, int medium, int hard, int elite) {
    m.put(prefix + "_EASY", easy);
    m.put(prefix + "_MEDIUM", medium);
    m.put(prefix + "_HARD", hard);
    m.put(prefix + "_ELITE", elite);
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.IntUnaryOperator;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures that SOME diary task completed, from its own chat broadcast:
 * tier and area only, never which specific task. The tier-completion broadcast already matched
 * elsewhere ("Congratulations, you have completed all of the &lt;tier&gt; tasks in the
 * &lt;area&gt; area...") fires once per finished tier; this one fires once per task, well
 * before the tier is complete, and starts with a different word entirely so the two can never
 * collide.
 *
 * <p>Verified live wording: "Well done! You have completed an elite task in the Western
 * Provinces area. Your Achievement Diary has been updated."
 *
 * <p>Per-task identity, when possible, comes from the region's {@link DiaryTaskManifest}:
 * no varbit or widget names an individual task, so a bit packed into the region's own
 * varplayer(s) ({@link DiaryTaskVarplayers}) is diffed against the last-known value
 * ({@link DiaryTaskBits}) to find what flipped. Only attempted for a region
 * {@link DiaryTaskManifest#isVerified} has confirmed; other regions still read and advance
 * their baseline, just never attach a name. A miss, a tier mismatch, or more than one bit
 * resolving at once all fail closed rather than guess.
 */
@Slf4j
public class DiaryTaskCompletionCapture extends BaseCapture {

  private static final Pattern COMPLETION_PATTERN =
      Pattern.compile(
          "^Well done! You have completed an? (\\w+) task in the (.+) area\\. Your Achievement"
              + " Diary has been updated\\.$");

  // Diary tiers, not CombatAchievementVarbits.ALL's keys: despite sharing four of the same
  // words, they are a different vocabulary (that map also has "master" and "grandmaster",
  // which do not exist as diary tiers), so validating against it here would silently accept
  // two tier names the diary system has no notion of.
  private static final Set<String> DIARY_TIERS = Set.of("easy", "medium", "hard", "elite");

  // Matches the server's own bound (MAX_NAME_LENGTH in events-envelope.ts). The server
  // validates a whole batch in one schema parse and 400s the WHOLE BATCH on any one event
  // failing, so one oversized area name must never reach the outbox.
  private static final int MAX_AREA_NAME_LENGTH = 128;

  private final IntUnaryOperator varpReader;
  private final DiaryTaskBits bits;
  private final DiaryTaskManifest manifest;
  private final Runnable onBaselineTouched;

  /** No task-identity resolution, tier/area only. Used by every existing caller. */
  public DiaryTaskCompletionCapture(
      EventOutbox outbox, BooleanSupplier enabled, LongSupplier accountHash) {
    this(
        outbox,
        enabled,
        accountHash,
        id -> 0,
        new DiaryTaskBits(),
        DiaryTaskManifest.shipped(),
        () -> {});
  }

  /**
   * @param onBaselineTouched fires once per recognised region, right after its varplayer(s)
   *     are read and diffed. Asks the caller to persist {@code bits} soon, decoupled from
   *     the periodic snapshot's own, unrelated reasons to resubmit; otherwise the persisted
   *     copy could lag real progress indefinitely, and a crash in that gap loses it.
   */
  public DiaryTaskCompletionCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      IntUnaryOperator varpReader,
      DiaryTaskBits bits,
      DiaryTaskManifest manifest,
      Runnable onBaselineTouched) {
    this(outbox, enabled, accountHash, varpReader, bits, manifest, onBaselineTouched, null);
  }

  /**
   * Same as the constructor above, plus {@code onEmit}: notified after every event this
   * capture emits, for the status panel's recent-activity list. See {@link BaseCapture}.
   */
  public DiaryTaskCompletionCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      IntUnaryOperator varpReader,
      DiaryTaskBits bits,
      DiaryTaskManifest manifest,
      Runnable onBaselineTouched,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
    this.varpReader = varpReader;
    this.bits = bits;
    this.manifest = manifest;
    this.onBaselineTouched = onBaselineTouched;
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.GAMEMESSAGE) {
      return;
    }
    handleMessage(Text.removeTags(event.getMessage()));
  }

  /** Package-private, not private: the test calls this directly with plain strings. */
  void handleMessage(String message) {
    if (!isEnabled()) {
      return;
    }
    Matcher matcher = COMPLETION_PATTERN.matcher(message);
    if (!matcher.matches()) {
      return;
    }
    String tier = matcher.group(1).toLowerCase(Locale.ROOT);
    if (!DIARY_TIERS.contains(tier)) {
      return;
    }
    String area = matcher.group(2).trim();
    if (area.isEmpty() || area.length() > MAX_AREA_NAME_LENGTH) {
      return;
    }
    emit(
        TransientEvent.TYPE_DIARY_TASK_COMPLETED,
        payload(tier, area, resolveTaskName(tier, area)));
  }

  /**
   * Reads and diffs the region's varplayer(s) regardless of verification, so the baseline
   * never goes stale. Only looks up the manifest, and only ever returns a name, for a
   * verified region, and only when exactly one bit flipped and resolved cleanly.
   */
  private String resolveTaskName(String tier, String area) {
    String region = DiaryTaskRegions.forAreaText(area);
    if (region == null) {
      return null;
    }
    int[] varplayerIds = DiaryTaskVarplayers.ALL.get(region);
    if (varplayerIds == null) {
      return null;
    }
    boolean verified = manifest.isVerified(region);
    // Every bit that newly flipped, not just how many resolved: two bits flipping where
    // only one has a manifest entry is just as ambiguous as two that both resolve, since
    // there's no way to know which one this chat line is about.
    int totalNewlySet = 0;
    List<String> resolved = new ArrayList<>();
    boolean mismatch = false;
    for (int varplayerId : varplayerIds) {
      int newValue = varpReader.applyAsInt(varplayerId);
      int[] newlySetBits = bits.diff(varplayerId, newValue);
      totalNewlySet += newlySetBits.length;
      if (!verified) {
        continue;
      }
      for (int bitIndex : newlySetBits) {
        DiaryTaskManifest.Entry entry = manifest.lookup(region, varplayerId, bitIndex);
        if (entry == null) {
          continue; // unmapped bit in an otherwise-mapped region, expected and safe
        }
        if (!entry.tier().equals(tier)) {
          // Manifest and chat line disagree on tier. A stronger signal than an
          // ordinary miss (a shifted bit, a wrong region), never one to prefer over
          // the other.
          log.debug(
              "diary task manifest tier mismatch: region={} varplayer={} bit={} manifest={}"
                  + " chat={}",
              region, varplayerId, bitIndex, entry.tier(), tier);
          mismatch = true;
          continue;
        }
        resolved.add(entry.taskName());
      }
    }
    // After every varplayer in this region has been diffed, never before: the callback
    // persists bits, and persisting ahead of this call's own diff would always be one
    // message behind, losing the very update a crash right after this call would need.
    onBaselineTouched.run();
    if (mismatch || totalNewlySet != 1 || resolved.size() != 1) {
      return null;
    }
    return resolved.get(0);
  }

  static Map<String, Object> payload(String tier, String area, String taskName) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("tier", tier);
    payload.put("area", area);
    if (taskName != null) {
      payload.put("taskName", taskName);
    }
    return payload;
  }
}

package com.bankstand;

import java.util.Map;

/**
 * The last combat-achievement count vector the server acknowledged, used as a change gate so the
 * capture loop only submits when something moved. The plugin resets this on an
 * account switch and advances it only when a submit is acknowledged, so a dropped
 * submit is retried on the next capture (the baseline never moved).
 *
 * <p>Held as a digest rather than a copy of the vector, so the same value can be
 * written to disk and restored on the next client start. See {@link SkillBaseline} for
 * why one representation across memory and disk is worth a hash.
 */
public class CombatAchievementBaseline {
  private String acked;

  /** True when {@code current} differs from what the server last acknowledged. */
  public boolean changedSince(Map<String, Integer> current) {
    return !CapabilityDigest.of(current).equals(acked);
  }

  public void advance(Map<String, Integer> ackedNow) {
    acked = CapabilityDigest.of(ackedNow);
  }

  /** Restores a digest read back from disk. Null means nothing is known. */
  public void restore(String digest) {
    acked = digest;
  }

  /** The acknowledged digest, or null when nothing has been. */
  public String ackedDigest() {
    return acked;
  }

  public void reset() {
    acked = null;
  }
}

package com.bankstand;

import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;

/**
 * One single-purpose class per transient event type, all extending this.
 * Dink's structure: rather than a growing switch in the plugin class, each
 * detector is its own listener the plugin registers with the event bus.
 *
 * <p><b>Capture classes detect and emit domain events only. They do not
 * deliver.</b> {@link #emit} hands a built event to the {@link EventOutbox} and
 * returns; nothing here touches the network, retries, or persists beyond that.
 * Delivery belongs to the outbox, which is what makes a detector unit-testable
 * without a live client: feed it a synthetic RuneLite event and assert what it
 * handed the (fake) outbox, the same shape {@code DiaryVarbits} and {@code
 * CollectionLogAccumulator} already prove for the snapshot captures.
 *
 * <p>{@link #enabled} is the caller's own {@code config.collectX() &&
 * manifest.allows("x")} check, injected rather than read here, so a capture
 * never needs to know about {@code BankstandConfig} or {@code
 * CapabilityManifest} to be tested.
 */
public abstract class BaseCapture {

  private final EventOutbox outbox;
  private final BooleanSupplier enabled;
  private final LongSupplier accountHash;
  // Nullable: every existing test constructs a capture with the 3-arg constructor,
  // which has no notion of the panel's recent-activity list and does not need one.
  // Notified AFTER outbox.add, on the same emit, never re-invoked later from a
  // stored id: this is the one moment a human-readable description is cheaply
  // available (see RecentActivityLog's own javadoc for why that matters).
  private final Consumer<TransientEvent> onEmit;

  protected BaseCapture(EventOutbox outbox, BooleanSupplier enabled, LongSupplier accountHash) {
    this(outbox, enabled, accountHash, null);
  }

  protected BaseCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Consumer<TransientEvent> onEmit) {
    this.outbox = outbox;
    this.enabled = enabled;
    this.accountHash = accountHash;
    this.onEmit = onEmit;
  }

  /** Builds and emits one event, gated on {@link #enabled}. A no-op while off, so a
   *  detector can keep listening and simply drop what it observes without a second
   *  gate at every call site. */
  protected final void emit(String type, Map<String, Object> payload) {
    if (!enabled.getAsBoolean()) return;
    TransientEvent event = new TransientEvent(type, payload);
    outbox.add(accountHash.getAsLong(), event);
    if (onEmit != null) {
      onEmit.accept(event);
    }
  }

  /** Whether the toggle + manifest gate is currently open. A subclass checks this
   *  BEFORE doing any read (an item lookup, a regex match against chat), not only
   *  before {@link #emit}, so nothing is examined at all while the capability is
   *  off, matching the convention every other capture in this plugin already
   *  follows. */
  protected final boolean isEnabled() {
    return enabled.getAsBoolean();
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.List;

/**
 * The lines {@code ::bstand} prints, built from plain values.
 *
 * <p>Separated from the plugin so the wording is testable without a client. Half the value of a
 * manual trigger is being able to see what it did, and during an earlier incident there was no way
 * to see anything at all: every action was implicit, on a schedule or a game event, and a failure
 * left nothing on screen to read.
 *
 * <p>Every line answers a question a player asks when it looks broken: am I paired, which
 * character is linked, did anything reach the server, and what went wrong last time.
 */
public final class StatusReport {

  private StatusReport() {}

  /**
   * Builds the status lines.
   *
   * @param paired whether a device token is stored
   * @param serverUrl where submissions go; shown because a wrong one is silent otherwise
   * @param linkedName the character bound to this pairing, or null if none has been linked
   * @param lastSubmitDescription e.g. "4 minutes ago", or null when nothing has been submitted
   * @param lastFailure the last failure reason, or null when the last attempt succeeded
   * @param enabled which capability names are switched on, in display order
   * @param collectionLogSlots how many slots the last guided read saw, or -1 when never read
   * @param accountTypeLine what the game reports this account to be, or null when logged out
   * @param manifestLine the capability manifest in use, so it is never a guess in a bug report
   */
  public static List<String> lines(
      boolean paired,
      String serverUrl,
      String linkedName,
      String lastSubmitDescription,
      String lastFailure,
      List<String> enabled,
      int collectionLogSlots,
      String accountTypeLine,
      String manifestLine) {
    List<String> out = new ArrayList<>();

    if (!paired) {
      // Nothing else is worth printing: every other line describes a pairing that
      // does not exist, and listing them reads as though something is configured.
      out.add("Not paired. Paste a pairing code in the Bankstand settings to link this client.");
      return out;
    }

    out.add("Paired with " + serverUrl + ".");
    out.add(
        linkedName == null
            ? "No character linked yet. Log in and it links on the next tick, or run ::bstand link."
            : "Linked character: " + linkedName + ".");

    out.add(
        enabled.isEmpty()
            ? "No capabilities switched on, so nothing is being sent."
            : "Sending: " + String.join(", ", enabled) + ".");

    out.add(
        lastSubmitDescription == null
            ? "Nothing submitted yet this session."
            : "Last submitted " + lastSubmitDescription + ".");

    if (lastFailure != null) {
      out.add("Last failure: " + lastFailure);
    }

    // The collection log is the one capability a manual sync cannot refresh, so it
    // gets its own line whether or not it has ever been read. Without this a player
    // runs a sync, sees no new slots and concludes the whole thing is broken.
    //
    // **"items", not "entries".** This counts distinct item ids observed, and the
    // game counts ENTRIES, which is a different number: one account read 193 ids
    // for the 189 entries the client displayed, because several ids are variant
    // forms of a slot already owned under another id. The plugin has no manifest
    // and cannot resolve one into the other, so it names what it actually counted.
    // Saying "entries" put 193 beside the game's 189 in the same chat window.
    out.add(
        collectionLogSlots < 0
            ? "Collection log not read yet. Open it in game and use its Search to read the whole log."
            : "Collection log: "
                + collectionLogSlots
                + " items from the last read. Use the log's own Search to read it again.");

    // Read from the game rather than from the hiscores, which cannot see Group
    // Ironman at all. Null while logged out: the varbit reads 0 with no account
    // loaded, and printing "regular" for a logged-out client would be a wrong
    // answer rather than a missing one.
    if (accountTypeLine != null) {
      out.add(accountTypeLine);
    }

    // Which capabilities the server currently ingests, and how often it wants them. The
    // gates above are an intersection of this and the player's own toggles, so without it
    // a capability switched on in the config but absent from the manifest reads as a bug.
    if (manifestLine != null) {
      out.add(manifestLine);
    }

    return out;
  }

  /**
   * What {@code ::bstand export} prints: the current Collect/Events toggle state,
   * plain booleans and the one numeric threshold so this is testable without a live
   * config. Meant to be copied to another device or into a support message, so it
   * names only the toggles themselves and never the pairing code, device token, or
   * server URL: none of the three would mean anything on a different account or
   * client anyway, and two of them are secrets.
   */
  public static List<String> exportLines(
      boolean skills,
      boolean quests,
      boolean diaries,
      boolean collectionLog,
      boolean combatAchievements,
      boolean accountType,
      boolean notableDrops,
      int notableDropThreshold,
      boolean petDrops) {
    List<String> out = new ArrayList<>();
    out.add("Bankstand collect/events config:");
    out.add(onOff("Skill XP", skills));
    out.add(onOff("Quest progress", quests));
    out.add(onOff("Diary progress", diaries));
    out.add(onOff("Collection log", collectionLog));
    out.add(onOff("Combat achievements", combatAchievements));
    out.add(onOff("Account type", accountType));
    out.add(onOff("Notable drops", notableDrops) + " (threshold " + notableDropThreshold + " gp)");
    out.add(onOff("Pet drops", petDrops));
    return out;
  }

  private static String onOff(String label, boolean value) {
    return "- " + label + ": " + (value ? "on" : "off");
  }

  /**
   * What {@code ::bstand help} (or {@code ::bstand commands}) prints: every real
   * command, in the order {@code CommandAction} resolves them, with what each one
   * actually does. A fixed list rather than one built from {@code CommandAction}
   * reflectively, so a name typed here can never silently drift from the enum: the
   * matching {@code HelpLinesTest} pins the count, and a command added to one
   * without the other fails there rather than shipping a list a player cannot
   * trust.
   */
  public static List<String> helpLines() {
    List<String> out = new ArrayList<>();
    out.add("Bankstand commands:");
    out.add("- ::bstand - shows connection status: account, character, last sync.");
    out.add("- ::bstand sync - sends now instead of waiting for the next cycle.");
    out.add("- ::bstand link - re-links this character to your account.");
    out.add(
        "- ::bstand log - arms a guided collection log read; open the log and click Search.");
    out.add("- ::bstand export - prints and copies your current Collect/Events toggle state.");
    out.add("- ::bstand repair - clears a stale pairing so you can paste a fresh code.");
    out.add("- ::bstand help - shows this list.");
    return out;
  }

  /**
   * What {@code ::bstand sync} reports.
   *
   * <p>States plainly that the collection log is not included. A sync that silently leaves it out
   * looks like a sync that did not work, because the log is the capability a player is most likely
   * to be watching.
   */
  public static List<String> syncLines(boolean paired, List<String> enabled) {
    List<String> out = new ArrayList<>();
    if (!paired) {
      out.add("Not paired, so there is nothing to sync.");
      return out;
    }
    if (enabled.isEmpty()) {
      out.add("No capabilities switched on, so there is nothing to sync.");
      return out;
    }
    out.add("Syncing " + String.join(", ", enabled) + " now.");
    out.add("The collection log is not included: it can only be read from the log's own Search.");
    return out;
  }
}

package com.bankstand;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Map;
import java.util.TreeMap;

/**
 * A stable fingerprint of one complete capability block.
 *
 * <p>Exists so an acknowledged baseline can be written to disk. In memory the baselines
 * keep the block itself and compare it exactly, which is stronger than a digest because
 * it cannot collide; across a restart that is the wrong trade, since skills, quests and
 * diaries are all re-read live on the next capture and only the verdict "the server has
 * already seen this" needs to survive. Sixty-four characters carries that verdict for a
 * block of any size.
 *
 * <p>Canonical before hashed, and that ordering is load-bearing. The capture rebuilds
 * these maps every cycle from a {@code HashMap}, whose iteration order is not a
 * contract, so a digest taken over the block as it happens to be laid out would differ
 * on a cycle where nothing moved, and the block would be resent forever.
 *
 * <p>Pure and deterministic.
 */
public final class CapabilityDigest {

  private CapabilityDigest() {}

  /**
   * Digests a keyed block over its sorted keys.
   *
   * <p>Key and value are separated and each entry terminated, so {@code {"ab": "c"}} and
   * {@code {"a": "bc"}} cannot serialize to the same bytes.
   */
  public static String of(Map<String, ?> block) {
    StringBuilder canonical = new StringBuilder();
    for (Map.Entry<String, ?> entry : new TreeMap<String, Object>(block).entrySet()) {
      canonical.append(entry.getKey()).append('=').append(entry.getValue()).append('\n');
    }
    return sha256(canonical.toString());
  }

  private static String sha256(String input) {
    try {
      byte[] hash =
          MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
      StringBuilder hex = new StringBuilder(hash.length * 2);
      for (byte b : hash) {
        hex.append(Character.forDigit((b >> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
      }
      return hex.toString();
    } catch (NoSuchAlgorithmException e) {
      // Every JVM ships SHA-256. Unreachable, and not worth a fallback that would be
      // silently weaker than the thing it stands in for.
      throw new IllegalStateException("SHA-256 unavailable", e);
    }
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Maps the same wire region keys {@link DiaryVarbits}/{@link DiaryTaskVarbits} use to the
 * varplayer(s) that pack that region's per-task completion bits.
 *
 * <p>No varbit names an individual task, only {@code *_COMPLETE}/{@code *_REWARD}/
 * {@code *_COUNT} per tier. The bits live in these varplayers instead, with no RuneLite
 * name for what any one means; that mapping is {@link DiaryTaskManifest}'s job. This table
 * just says which varplayer(s) to read, verified against {@code VarPlayerID} rather than
 * assumed.
 *
 * <p>Ten regions use two ({@code _ACHIEVEMENT_DIARY}/{@code _ACHIEVEMENT_DIARY2}). Kourend
 * & Kebos has a third ({@code _MULTISTAGE}); Karamja predates the standard naming and uses
 * four ({@code ATJUN_TASKS_1..4}). 20 + 3 + 4 = 27.
 *
 * <p>{@code VarPlayerID} really does spell Ardougne's constant {@code
 * ARDOUNGE_ACHIEVEMENT_DIARY} and Lumbridge & Draynor's {@code LUMB_DRAY_ACHIEVEMENT_DIARY}.
 * Copied as-is, not typos.
 */
public final class DiaryTaskVarplayers {
  private DiaryTaskVarplayers() {}

  /** Ordered, unmodifiable: wire region key to its varplayer ids, region-canonical order. */
  public static final Map<String, int[]> ALL = Collections.unmodifiableMap(build());

  private static Map<String, int[]> build() {
    Map<String, int[]> m = new LinkedHashMap<>();
    m.put("ARDOUGNE", new int[] {
        VarPlayerID.ARDOUNGE_ACHIEVEMENT_DIARY, VarPlayerID.ARDOUNGE_ACHIEVEMENT_DIARY2});
    m.put("DESERT", new int[] {
        VarPlayerID.DESERT_ACHIEVEMENT_DIARY, VarPlayerID.DESERT_ACHIEVEMENT_DIARY2});
    m.put("FALADOR", new int[] {
        VarPlayerID.FALADOR_ACHIEVEMENT_DIARY, VarPlayerID.FALADOR_ACHIEVEMENT_DIARY2});
    m.put("FREMENNIK", new int[] {
        VarPlayerID.FREMENNIK_ACHIEVEMENT_DIARY, VarPlayerID.FREMENNIK_ACHIEVEMENT_DIARY2});
    m.put("KANDARIN", new int[] {
        VarPlayerID.KANDARIN_ACHIEVEMENT_DIARY, VarPlayerID.KANDARIN_ACHIEVEMENT_DIARY2});
    // KOUREND is the RuneLite constant prefix; the wire key is KOUREND_KEBOS, matching
    // DiaryVarbits/DiaryTaskVarbits. The third varplayer is this region's own irregularity.
    m.put("KOUREND_KEBOS", new int[] {
        VarPlayerID.KOUREND_ACHIEVEMENT_DIARY, VarPlayerID.KOUREND_ACHIEVEMENT_DIARY2,
        VarPlayerID.KOUREND_ACHIEVEMENT_DIARY_MULTISTAGE});
    // LUMB_DRAY is the RuneLite constant prefix; the wire key is LUMBRIDGE_DRAYNOR.
    m.put("LUMBRIDGE_DRAYNOR", new int[] {
        VarPlayerID.LUMB_DRAY_ACHIEVEMENT_DIARY, VarPlayerID.LUMB_DRAY_ACHIEVEMENT_DIARY2});
    m.put("MORYTANIA", new int[] {
        VarPlayerID.MORYTANIA_ACHIEVEMENT_DIARY, VarPlayerID.MORYTANIA_ACHIEVEMENT_DIARY2});
    m.put("VARROCK", new int[] {
        VarPlayerID.VARROCK_ACHIEVEMENT_DIARY, VarPlayerID.VARROCK_ACHIEVEMENT_DIARY2});
    m.put("WESTERN_PROVINCES", new int[] {
        VarPlayerID.WESTERN_ACHIEVEMENT_DIARY, VarPlayerID.WESTERN_ACHIEVEMENT_DIARY2});
    m.put("WILDERNESS", new int[] {
        VarPlayerID.WILDERNESS_ACHIEVEMENT_DIARY, VarPlayerID.WILDERNESS_ACHIEVEMENT_DIARY2});
    // Karamja's diary predates the standard two-varplayer layout, hence four
    // differently-named ids instead of a region-prefixed DIARY/DIARY2 pair.
    m.put("KARAMJA", new int[] {
        VarPlayerID.ATJUN_TASKS_1, VarPlayerID.ATJUN_TASKS_2,
        VarPlayerID.ATJUN_TASKS_3, VarPlayerID.ATJUN_TASKS_4});
    return m;
  }
}

package com.bankstand;

import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Item ids that fill a collection log slot another id already fills.
 *
 * <p>Some slots are awarded by two sources under two different ids, and the log
 * lists them once. Volcanic Mine's Prospector pieces are not Motherlode Mine's,
 * so a player with both sets holds eight items filling four slots, and counting
 * raw ids reported 193 where the log said 189.
 *
 * <p>Used for COUNTING only. Submissions still carry the ids the client actually
 * reported: which item a player holds is a fact, and canonicalising it on the
 * wire would tell the server they own a Motherlode piece when they own a
 * Volcanic one. The server maps ids to slots itself and holds the full table.
 *
 * <p>Only genuine duplicates belong here. An uncharged or empty form that is the
 * ONLY id for its slot is not a duplicate and must not be collapsed, or the
 * count drops below the truth.
 */
public final class VariantIds {

  private VariantIds() {}

  /** Variant id to the id the log counts it as. */
  private static final Map<Integer, Integer> CANONICAL = new HashMap<>();

  static {
    // Volcanic Mine's Prospector set, against Motherlode Mine's.
    CANONICAL.put(29472, 12013); // helmet
    CANONICAL.put(29474, 12014); // jacket
    CANONICAL.put(29476, 12015); // legs
    CANONICAL.put(29478, 12016); // boots
  }

  /** The id the log counts this one as, or the id itself. */
  public static int canonical(int itemId) {
    return CANONICAL.getOrDefault(itemId, itemId);
  }

  /** How many log slots these ids fill, which is what the player sees in game. */
  public static int countEntries(Collection<Integer> itemIds) {
    Set<Integer> entries = new HashSet<>();
    for (Integer id : itemIds) {
      if (id != null) entries.add(canonical(id));
    }
    return entries.size();
  }
}

package com.bankstand;

import java.util.Objects;

/**
 * Decides whether a submit outcome is worth telling the player about.
 *
 * <p>With no side panel to hold a status, outcomes surface as chat lines, and the
 * capture cycle runs every 60 seconds. An unreachable server would print the same
 * line forever, which trains the player to ignore it. So a failure is announced when
 * it is NEW (the first one, or a different reason from the one currently outstanding)
 * and a recovery is announced only when something was actually outstanding.
 *
 * <p>A failure that returns after a recovery is announced again, even with the same
 * reason: the player watched it clear, so its coming back is news rather than noise.
 *
 * <p>Not thread-safe, and deliberately so: it is only ever touched from the client
 * thread, alongside the rest of the session state.
 */
final class NoticeGate {

  /** The reason currently outstanding, or null when the last outcome was a success. */
  private String outstanding;

  private boolean healthy = true;

  /**
   * Records a failed submit. Returns true when it should be announced.
   *
   * @param reason the failure message, which may be null
   */
  boolean onFailure(String reason) {
    boolean announce = healthy || !Objects.equals(outstanding, reason);
    outstanding = reason;
    healthy = false;
    return announce;
  }

  /** Records a successful submit. Returns true when a recovery should be announced. */
  boolean onSuccess() {
    boolean announce = !healthy;
    outstanding = null;
    healthy = true;
    return announce;
  }
}

package com.bankstand;

/**
 * An identity submit that failed for any reason (not paired, network, a rejected
 * or revoked token, a bad response). The message is generic and safe to surface;
 * the raw token and account hash are never logged. {@link #isRetryable()} marks
 * transient failures (network, 429, 5xx) that a bounded retry may clear, so the
 * caller retries those and fails fast on terminal ones (a revoked token, a 4xx).
 */
public class SubmitException extends Exception {
  private final boolean retryable;
  private final boolean authFailure;

  public SubmitException(String message) {
    this(message, false);
  }

  public SubmitException(String message, boolean retryable) {
    this(message, retryable, false);
  }

  public SubmitException(String message, boolean retryable, boolean authFailure) {
    super(message);
    this.retryable = retryable;
    this.authFailure = authFailure;
  }

  public boolean isRetryable() {
    return retryable;
  }

  /**
   * A rejected or revoked token (401/403). Distinct from an ordinary terminal failure
   * because retrying never fixes it, only re-pairing does, so the caller has to stop
   * submitting rather than try again next capture.
   */
  public boolean isAuthFailure() {
    return authFailure;
  }
}

package com.bankstand;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * The live state of a guided collection log read.
 *
 * <p>A chat line cannot carry a running count, and printing one per entry would flood
 * the box with roughly seventeen hundred lines. The read is also the one moment where
 * the player is waiting on the plugin and has no other way to tell whether anything is
 * happening, so it is worth a transient surface of its own. It is added when a sync is
 * armed and removed the moment the read ends, so nothing lingers.
 *
 * <p>Reads its text straight off the sync rather than holding a copy, so the count
 * cannot drift from the state machine that owns it.
 */
class CollectionLogSyncInfoBox extends InfoBox {

  private final CollectionLogSync sync;

  CollectionLogSyncInfoBox(BufferedImage image, Plugin plugin, CollectionLogSync sync) {
    super(image, plugin);
    this.sync = sync;
    setPriority(net.runelite.client.ui.overlay.infobox.InfoBoxPriority.LOW);
  }

  @Override
  public String getText() {
    // A dash while waiting, not a zero: nothing has been read yet, which is a different
    // fact from having read none, and the same rule the rest of Bankstand renders by.
    return sync.isAwaitingSearch() ? "-" : Integer.toString(sync.observedCount());
  }

  @Override
  public Color getTextColor() {
    return Color.WHITE;
  }

  @Override
  public String getTooltip() {
    return sync.isAwaitingSearch()
        ? "Bankstand: click Search in your collection log to sync it"
        : "Bankstand: reading your collection log, " + sync.observedCount() + " entries observed";
  }
}

