package com.bankstand;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures a collection log unlock the moment the game announces it in chat,
 * rather than waiting for the player to open the log and click Search.
 *
 * <p>Carries the raw item NAME, not a resolved item id. The log's own display name is
 * not unique ("Graceful hood" names three separate entries across three sources), so
 * resolving it to the correct one is a disambiguation the server already does
 * correctly for the guided sync; duplicating that logic here would re-solve an
 * already-solved problem, with a real chance of getting it wrong.
 */
public class CollectionLogUnlockCapture extends BaseCapture {

  private static final Pattern UNLOCK_PATTERN =
      Pattern.compile("^New item added to your collection log: (.+)$");

  // Matches the server's own bound (MAX_NAME_LENGTH in events-envelope.ts). The server
  // validates a whole batch in one schema parse and 400s the WHOLE BATCH on any one
  // event failing, so one oversized or malformed name must never reach the outbox: it
  // would permanently block every other queued event for the account, not just itself.
  private static final int MAX_ITEM_NAME_LENGTH = 128;

  public CollectionLogUnlockCapture(
      EventOutbox outbox, BooleanSupplier enabled, LongSupplier accountHash) {
    super(outbox, enabled, accountHash);
  }

  public CollectionLogUnlockCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.GAMEMESSAGE) {
      return;
    }
    handleMessage(Text.removeTags(event.getMessage()));
  }

  /** Package-private, not private: CollectionLogUnlockCaptureTest calls this directly
   *  with plain strings, to avoid constructing a live ChatMessage. */
  void handleMessage(String message) {
    if (!isEnabled()) {
      return;
    }
    Matcher matcher = UNLOCK_PATTERN.matcher(message);
    if (!matcher.matches()) {
      return;
    }
    String itemName = matcher.group(1).trim();
    // A whitespace-only capture is min(1)-valid junk on the server's own schema, the
    // same way an empty one is, and one bad event 400s the whole batch (see
    // MAX_ITEM_NAME_LENGTH's comment for why that is never acceptable here).
    if (itemName.isEmpty() || itemName.length() > MAX_ITEM_NAME_LENGTH) {
      return;
    }
    emit(TransientEvent.TYPE_COLLECTION_LOG_UNLOCK, payload(itemName));
  }

  static Map<String, Object> payload(String itemName) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("itemName", itemName);
    return payload;
  }
}

package com.bankstand;

/**
 * One pending {@link TransientEvent}, tagged with the account it was captured
 * under. The tag never travels on the wire (a batch's one top-level {@code
 * accountHash} covers every event in it); it exists so the outbox can still
 * attribute an event correctly if the player relogs to a different character
 * before it is sent, rather than submitting stale entries under whichever
 * account happens to be active when the outbox next drains.
 */
public final class OutboxEntry {
  private final long accountHash;
  private final TransientEvent event;

  public OutboxEntry(long accountHash, TransientEvent event) {
    this.accountHash = accountHash;
    this.event = event;
  }

  public long getAccountHash() {
    return accountHash;
  }

  public TransientEvent getEvent() {
    return event;
  }
}

package com.bankstand;

import java.security.SecureRandom;
import java.util.UUID;

/**
 * A dependency-free UUIDv7 generator. UUIDv7 leads with a 48-bit Unix
 * millisecond timestamp, so ids are time-ordered, which keeps them useful as an
 * idempotency key without needing a separate sequence number. The random bits do
 * not need to be unpredictable (this is an idempotency and ordering key, not a
 * secret), but a decent RNG keeps collisions away within a millisecond.
 */
public final class UuidV7 {
  private UuidV7() {}

  private static final SecureRandom RANDOM = new SecureRandom();

  public static String generate() {
    long ts = System.currentTimeMillis();
    byte[] b = new byte[16];
    RANDOM.nextBytes(b);
    // 48-bit big-endian millisecond timestamp in bytes 0..5.
    b[0] = (byte) (ts >>> 40);
    b[1] = (byte) (ts >>> 32);
    b[2] = (byte) (ts >>> 24);
    b[3] = (byte) (ts >>> 16);
    b[4] = (byte) (ts >>> 8);
    b[5] = (byte) ts;
    // Version 7 in the high nibble of byte 6.
    b[6] = (byte) ((b[6] & 0x0f) | 0x70);
    // RFC 4122 variant (10xx) in the high bits of byte 8.
    b[8] = (byte) ((b[8] & 0x3f) | 0x80);
    long msb = 0;
    long lsb = 0;
    for (int i = 0; i < 8; i++) {
      msb = (msb << 8) | (b[i] & 0xff);
    }
    for (int i = 8; i < 16; i++) {
      lsb = (lsb << 8) | (b[i] & 0xff);
    }
    return new UUID(msb, lsb).toString();
  }
}

package com.bankstand;

import lombok.Data;
import lombok.ToString;

/**
 * This client's pairing with a Bankstand account: a bearer token, the server's id for
 * this device, and when the token expires.
 *
 * <p>Deliberately a device's credentials rather than an account's. The server keys one
 * {@code plugin_device} row per token, with its own name, last-seen time and revocation,
 * so two machines holding the same token are one device as far as Bankstand is concerned:
 * revoking either revokes both, and neither one's last-seen time survives the other's
 * submit. Keeping this per install is what makes several clients on one account work.
 */
@Data
public class DeviceCredentials {

  // Excluded from the generated toString(): NoSecretsInLogsTest bans passing the
  // literal identifiers `token`/`getToken()` to a log call, by scanning source text, but
  // cannot see through an object argument whose own toString() embeds the credential
  // (`log.debug("...", credentials)` reads as passing `credentials`, not `token`). Without
  // this exclusion the guard's ban would be true of the direct getter and false of the
  // object holding the exact same value.
  @ToString.Exclude private String token;
  private String deviceId;
  private String expiresAt;

  public static DeviceCredentials none() {
    return new DeviceCredentials();
  }

  public boolean isPaired() {
    return token != null && !token.trim().isEmpty();
  }
}

package com.bankstand;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Captures which specific combat achievement task was just completed, from the
 * game's own chat broadcast. The only source that can ever name a
 * specific task: RuneLite exposes a per-tier completed count and nothing per
 * task, and Jagex publishes no per-task identity anywhere.
 *
 * <p>Wording verified against Dink's own {@code CombatTaskNotifier} and its test
 * fixtures, a Hub-approved plugin whose combat achievement notifier is
 * live-tested at scale: "Congratulations, you've completed a/an &lt;tier&gt;
 * combat task: &lt;name&gt;." A grandmaster task additionally appends a
 * "(N points)" suffix to the name, which is stripped before emit. The real broadcast
 * also carries a leading "CA_ID:&lt;n&gt;|" the pattern accepts and discards; that
 * was missing from Dink's fixtures too and only surfaced from an actual live capture.
 */
public class CombatAchievementCompletionCapture extends BaseCapture {

  // The game itself tags this broadcast with a "CA_ID:<n>|" prefix (observed live)
  // that carries no information this capture needs; the task name alone
  // is the identity. Matched and discarded rather than stripped beforehand, so a
  // message with no prefix at all still matches too.
  private static final Pattern COMPLETION_PATTERN =
      Pattern.compile(
          "^(?:CA_ID:\\d+\\|)?Congratulations, you've completed an? (\\w+) combat task: (.+)\\.$");

  // Strips a trailing "(N points)" from a task name, matching Dink's own approach of a
  // dedicated strip pattern applied with replaceFirst(""). taskName becomes a permanent
  // primary key server-side (player_combat_achievement_task is append-only, with no
  // later sync to correct it), so the suffix must never reach the outbox: a future fix
  // would then record the same task a second time under the clean name with no way to
  // tell which row is the copy.
  private static final Pattern POINTS_SUFFIX_PATTERN =
      Pattern.compile("\\s+\\(\\d+ points?\\)$");

  // The real broadcast can also carry a leading "@word@" icon tag directly against the
  // task name (observed live: "@ach_comp@Perfect Shellbane"), the game client's own
  // inline icon-substitution syntax (distinct from the "<...>" tags RuneLite's
  // Text.removeTags already strips), left raw because a plugin reads the chat line
  // before the client resolves it to an icon. Not in Dink's fixtures either, the same
  // gap the CA_ID prefix above was. Stripped for the same reason as the points suffix:
  // this becomes a permanent primary key with no later sync to fix it.
  private static final Pattern ICON_TAG_PREFIX_PATTERN = Pattern.compile("^@\\w+@");

  // Matches the server's own bound (MAX_NAME_LENGTH in events-envelope.ts). The server
  // validates a whole batch in one schema parse and 400s the WHOLE BATCH on any one
  // event failing, so one oversized name must never reach the outbox: it would
  // permanently block every other queued event for the account, not just itself.
  private static final int MAX_TASK_NAME_LENGTH = 128;

  public CombatAchievementCompletionCapture(
      EventOutbox outbox, BooleanSupplier enabled, LongSupplier accountHash) {
    super(outbox, enabled, accountHash);
  }

  public CombatAchievementCompletionCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.GAMEMESSAGE) {
      return;
    }
    handleMessage(Text.removeTags(event.getMessage()));
  }

  /** Package-private, not private: the test calls this directly with plain strings. */
  void handleMessage(String message) {
    if (!isEnabled()) {
      return;
    }
    Matcher matcher = COMPLETION_PATTERN.matcher(message);
    if (!matcher.matches()) {
      return;
    }
    String tier = matcher.group(1).toLowerCase(Locale.ROOT);
    if (!CombatAchievementVarbits.ALL.containsKey(tier)) {
      return;
    }
    String rawName = ICON_TAG_PREFIX_PATTERN.matcher(matcher.group(2)).replaceFirst("");
    String taskName = POINTS_SUFFIX_PATTERN.matcher(rawName).replaceFirst("").trim();
    // The strip above can consume the whole captured group (a double space before the
    // suffix leaves nothing), and a whitespace-only capture is min(1)-valid junk the
    // same way an empty one is: either would 400 the whole batch on the server's own
    // schema (see MAX_TASK_NAME_LENGTH's comment for why that is never acceptable here).
    if (taskName.isEmpty() || taskName.length() > MAX_TASK_NAME_LENGTH) {
      return;
    }
    emit(TransientEvent.TYPE_COMBAT_ACHIEVEMENT_COMPLETED, payload(tier, taskName));
  }

  static Map<String, Object> payload(String tier, String taskName) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("tier", tier);
    payload.put("taskName", taskName);
    return payload;
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.List;

/**
 * A frozen snapshot of everything {@link BankstandPanel} shows, assembled by the plugin
 * on the client thread and handed to the panel to render on the Swing event dispatch
 * thread. Plain data, deliberately: the panel never reaches back into the plugin, the
 * client, or the config to ask for anything itself, so what it draws can be reasoned
 * about, and tested, from a value alone.
 */
final class PanelModel {

  final boolean paired;
  final String linkedName;
  final PanelPresentation.SyncDot dot;
  final List<CapabilityRow> capabilities;
  final List<ActivityRow> recentActivity;
  final String lastFailureReason;
  final String serverUrl;

  PanelModel(
      boolean paired,
      String linkedName,
      PanelPresentation.SyncDot dot,
      List<CapabilityRow> capabilities,
      List<ActivityRow> recentActivity,
      String lastFailureReason,
      String serverUrl) {
    this.paired = paired;
    this.linkedName = linkedName;
    this.dot = dot;
    this.capabilities = capabilities;
    this.recentActivity = recentActivity;
    this.lastFailureReason = lastFailureReason;
    this.serverUrl = serverUrl;
  }

  /** What the panel shows before the plugin has ever built a real snapshot: the initial
   *  paint, before any capture or button click has run. */
  static PanelModel empty(String serverUrl) {
    return new PanelModel(
        false,
        null,
        PanelPresentation.SyncDot.GREY,
        Collections.emptyList(),
        Collections.emptyList(),
        null,
        serverUrl);
  }

  /** One row of the per-capability list: a display name and when it last genuinely
   *  synced, or null when it never has. */
  static final class CapabilityRow {
    final String name;
    final Long lastSyncedAtMs;

    CapabilityRow(String name, Long lastSyncedAtMs) {
      this.name = name;
      this.lastSyncedAtMs = lastSyncedAtMs;
    }
  }

  /** One row of the recent-activity list: what was sent, and when. */
  static final class ActivityRow {
    final String description;
    final long atMs;

    ActivityRow(String description, long atMs) {
      this.description = description;
      this.atMs = atMs;
    }
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * What the server says it will ingest, after this client has decided how much of it to
 * believe.
 *
 * <p><b>The refusal is structural, not a policy.</b> This type has four fields: a schema
 * version, a minimum plugin version, a list of capability <i>names</i> and an interval.
 * There is no field that can carry a varbit id, a varp, a script, a widget, a URL, a class
 * name or an expression, so a fully compromised Bankstand server cannot ask this plugin to
 * read a bank, an inventory, worn equipment, chat or a location. Not because it would be
 * refused, but because there is no way to say it. The plugin owns the mapping from a
 * capability name to game values and always has.
 *
 * <p>That is the property a Plugin Hub reviewer needs to be able to check in one file, so
 * the enforcement is deliberately small, ordered and readable rather than clever. The
 * Hub's stated position is that if it is difficult for them to be sure a plugin is not
 * against the rules, they will not merge it.
 *
 * <p>Every rejection resolves to a usable manifest rather than to a failure: the last one
 * that validated, or the compiled-in {@link #bundled()}. A manifest outage, or a server
 * that starts sending nonsense, must never stop a paired client working.
 */
public final class CapabilityManifest {

  /**
   * The only capabilities this build can capture at all.
   *
   * <p>An allowlist, so a name the server invents is dropped and the rest of the manifest
   * is still used. Adding a name here is a code change with a Hub review attached, which
   * is exactly the friction that should exist around what the plugin reads.
   */
  public static final Set<String> SUPPORTED_CAPABILITIES =
      Collections.unmodifiableSet(
          new LinkedHashSet<>(
              Arrays.asList(
                  "skills", "quests", "diaries", "collectionLog", "combatAchievements",
                  "accountType", "notableDrops", "petDrops")));

  /** The contract version this build speaks. A manifest declaring anything else is not ours. */
  public static final int SUPPORTED_SCHEMA_VERSION = 1;

  /**
   * The fastest this client will ever submit, whatever the server asks for.
   *
   * <p>A server that could drive the interval down could turn every paired client into a
   * load generator against itself and against Wise Old Man, so the client keeps the floor.
   * The server's value is only ever able to make submissions <i>less</i> frequent.
   */
  public static final int MIN_UPLOAD_INTERVAL_SECONDS = 60;

  /** And the slowest, so a bad value cannot silently park a client forever. */
  public static final int MAX_UPLOAD_INTERVAL_SECONDS = 6 * 60 * 60;

  /** More names than exist today would mean the list had stopped being a capability list. */
  private static final int MAX_CAPABILITIES = 32;

  /** Long enough for every real name, short enough that the field cannot smuggle a payload. */
  private static final int MAX_CAPABILITY_LENGTH = 40;

  private final int schemaVersion;
  private final List<String> capabilities;
  private final int uploadIntervalSeconds;

  private CapabilityManifest(int schemaVersion, List<String> capabilities, int interval) {
    this.schemaVersion = schemaVersion;
    this.capabilities = Collections.unmodifiableList(capabilities);
    this.uploadIntervalSeconds = interval;
  }

  /**
   * The manifest compiled into this build.
   *
   * <p>Used before the first successful fetch and after a total failure, so a client that
   * has never reached the server still captures what it was built to capture. Deliberately
   * everything this build supports: the server's copy can only ever narrow it.
   */
  public static CapabilityManifest bundled() {
    return new CapabilityManifest(
        SUPPORTED_SCHEMA_VERSION,
        new ArrayList<>(SUPPORTED_CAPABILITIES),
        MIN_UPLOAD_INTERVAL_SECONDS * 5);
  }

  /**
   * Validates a manifest the server sent, or returns null to keep whatever is in use.
   *
   * <p>Null, never an exception and never a partly-applied manifest. The caller's job on a
   * null is to do nothing, which leaves the last good copy or the bundled one in place.
   *
   * <p>The schema version gates the whole document rather than a field: a manifest written
   * against a contract this build does not speak cannot be partly understood, and guessing
   * at the parts that look familiar is how a client ends up honouring half of something.
   */
  public static CapabilityManifest validate(RawManifest raw) {
    if (raw == null) {
      return null;
    }
    if (raw.schemaVersion != SUPPORTED_SCHEMA_VERSION) {
      return null;
    }
    if (raw.capabilities == null || raw.capabilities.size() > MAX_CAPABILITIES) {
      return null;
    }

    // An unknown name is dropped and the rest is kept, which is the opposite of the
    // version gate above and deliberately so: a new capability is an additive change the
    // server is entitled to make, and rejecting the whole manifest for one would mean a
    // server could never introduce anything without stranding every older client.
    List<String> accepted = new ArrayList<>();
    for (String name : raw.capabilities) {
      if (name == null || name.length() > MAX_CAPABILITY_LENGTH) {
        continue;
      }
      if (SUPPORTED_CAPABILITIES.contains(name) && !accepted.contains(name)) {
        accepted.add(name);
      }
    }

    return new CapabilityManifest(
        raw.schemaVersion, accepted, clampInterval(raw.uploadIntervalSeconds));
  }

  /** The server's interval, held between this client's own floor and ceiling. */
  public static int clampInterval(int requested) {
    if (requested < MIN_UPLOAD_INTERVAL_SECONDS) {
      return MIN_UPLOAD_INTERVAL_SECONDS;
    }
    return Math.min(requested, MAX_UPLOAD_INTERVAL_SECONDS);
  }

  /** Whether the server is currently ingesting this capability. */
  public boolean allows(String capability) {
    return capabilities.contains(capability);
  }

  public List<String> capabilities() {
    return capabilities;
  }

  public int uploadIntervalSeconds() {
    return uploadIntervalSeconds;
  }

  public int schemaVersion() {
    return schemaVersion;
  }

  /** One line for the debug output, so the active manifest is never a guess. */
  public String describe() {
    return "manifest v"
        + schemaVersion
        + ", "
        + (capabilities.isEmpty() ? "no capabilities" : String.join(", ", capabilities))
        + ", every "
        + uploadIntervalSeconds
        + "s";
  }

  /**
   * The wire shape, exactly as Gson fills it.
   *
   * <p>Primitives and a list of strings, matching the server's own document. Unknown fields
   * on the wire are ignored rather than rejected, which is what lets the server add one
   * without stranding older clients; Gson does that by simply having nowhere to put them.
   *
   * <p><b>Do not add a field here that is not a primitive.</b> The guarantee at the top of
   * this file is only true while this class cannot express anything else.
   */
  public static final class RawManifest {
    int schemaVersion;
    String minPluginVersion;
    List<String> capabilities;
    int uploadIntervalSeconds;
  }
}

package com.bankstand.session;

/**
 * Tracks the currently logged-in account across game-state changes. Two invariants
 * from the ingestion review are enforced here: the logged-out sentinel is never
 * adopted or submitted, and state is never carried across a change of account hash.
 * In this slice there are no capture caches yet; {@link #reset()} is the seam a
 * later gameplay-capture slice hooks into so a switch clears everything.
 */
public class AccountSession {

  /** RuneLite's {@code client.getAccountHash()} returns this when logged out. */
  public static final long LOGGED_OUT = -1L;

  // accountHash and generation are read from the submit executor thread (see
  // isCurrent) while written on the game thread, so both are volatile for visibility
  // across the two. submitted crosses the same boundary in the other direction:
  // markSubmitFailed is called from the executor thread's whenComplete callback (a
  // failed identity submit, not hopped onto the client thread the way the neighbouring
  // notice() call is), while isSubmitted is read every game tick on the client thread.
  // Without volatile there is no happens-before edge guaranteeing that write is ever
  // observed, so a failed submit could go on being read as still in-flight forever,
  // the exact incident markSubmitInFlight's own doc comment already describes.
  private volatile long accountHash = LOGGED_OUT;
  private volatile int generation = 0;
  private volatile boolean submitted = false;

  public long getAccountHash() {
    return accountHash;
  }

  public boolean isActive() {
    return accountHash != LOGGED_OUT;
  }

  /**
   * A monotonic marker of the current login instance, bumped on every session change
   * (a switch, a logout, or a relog). A submit captures it at dispatch; the callback
   * compares it via {@link #isCurrent} so a stale result cannot overwrite a later one.
   */
  public int getGeneration() {
    return generation;
  }

  /**
   * True when {@code hash}/{@code gen} still identify the current login instance. A
   * submit is dispatched asynchronously with the account and generation it started
   * for; its callback uses this to drop a superseded result once the session has
   * moved on (a switch to another character, a logout, or a relog to the same
   * account, which advances the generation). The logged-out sentinel is never current.
   */
  public boolean isCurrent(long hash, int gen) {
    return isActive() && accountHash == hash && generation == gen;
  }

  /**
   * True while this account's identity submit is in flight or has succeeded, so it is
   * not resent every tick.
   *
   * <p>Named for the question the caller asks ("should I dispatch one?"), which covers
   * both states, because the caller cannot act differently on them.
   */
  public boolean isSubmitted() {
    return submitted;
  }

  /**
   * Mark an identity submit as in flight, so the next tick does not fire a second one.
   *
   * <p><b>In flight, not done.</b> These were the same thing, and the difference cost a
   * player their whole session: a submit that failed was never retried, because the flag
   * was set before dispatch and nothing ever cleared it. The server was fixed four
   * minutes later and the client went on being refused until a full logout and login.
   * "Do not double-fire" and "never retry" are not the same requirement.
   */
  public void markSubmitInFlight() {
    submitted = true;
  }

  /**
   * Release the mark after a failed submit, so a later tick can try again.
   *
   * <p>Guarded on the login instance for the same reason the success path is: a failure
   * arriving after the player has switched character must not re-arm a submit for an
   * account that is no longer logged in.
   */
  public void markSubmitFailed(long hash, int gen) {
    if (isCurrent(hash, gen)) {
      submitted = false;
    }
  }

  /**
   * Handle a login for {@code hash}. The logged-out sentinel is ignored. A hash
   * that differs from the current one resets the session (clearing the submitted
   * flag so the new account is submitted afresh) and adopts the new hash; the same
   * hash is a no-op. Returns true when a fresh session was started.
   */
  public boolean onLogin(long hash) {
    if (hash == LOGGED_OUT || hash == accountHash) {
      return false;
    }
    reset();
    accountHash = hash;
    submitted = false;
    generation++;
    return true;
  }

  /**
   * Clear the transient session on logout. The device token is account-independent
   * and kept elsewhere (ConfigManager), so it is not touched here.
   */
  public void onLogout() {
    reset();
    accountHash = LOGGED_OUT;
    submitted = false;
    generation++;
  }

  private void reset() {
    // No capture caches in this slice. A later gameplay slice clears them here so a
    // change of account can never leak one character's data into another's session.
  }
}

package com.bankstand;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/**
 * Last-known value of every tracked diary varplayer, keyed by varplayer id, so a fresh
 * read can be XORed against it to find which bit(s) just flipped.
 *
 * <p>{@link DiaryVarbits}/{@link DiaryTaskVarbits} get away with a digest because a tier is
 * cheap to re-read whole; per-task identity needs the real prior bit pattern, since a
 * digest only says something changed, not which bit. Same reason
 * {@link CollectionLogAccumulator} persists raw ids instead of a hash.
 *
 * <p>First read of a varplayer sets its baseline and reports nothing, on purpose: without
 * that, a player with pre-existing progress (or a client that just restarted and lost this
 * in-memory state) would have every already-set bit reported as freshly completed.
 *
 * <p>Always advances to the value it just read, whether or not anything resolved, so the
 * next diff has the right baseline regardless.
 *
 * <p>Persisted per character via {@link AckedState#getDiaryTaskBits()}, reset on account
 * switch like every other baseline here.
 */
@Slf4j
public class DiaryTaskBits {

  private final Map<Integer, Integer> lastKnown = new LinkedHashMap<>();

  /**
   * Diffs {@code newValue} against the stored value, advances the baseline regardless, and
   * returns the 0-based bit positions that went from unset to set. Empty on a first read of
   * this varplayer, or when nothing newly set.
   */
  public int[] diff(int varplayerId, int newValue) {
    Integer previous = lastKnown.put(varplayerId, newValue);
    if (previous == null) {
      return new int[0];
    }
    int newlySet = ~previous & newValue;
    int unset = previous & ~newValue;
    if (unset != 0) {
      // Nothing un-completes a diary task, so this shouldn't happen. Log it, don't crash.
      log.debug("varplayer {} lost bits {} (0x{}), reading a diary task backwards",
          varplayerId, Integer.toBinaryString(unset), Integer.toHexString(unset));
    }
    if (newlySet == 0) {
      return new int[0];
    }
    List<Integer> positions = new ArrayList<>();
    for (int bit = 0; bit < 32; bit++) {
      if ((newlySet & (1 << bit)) != 0) {
        positions.add(bit);
      }
    }
    int[] result = new int[positions.size()];
    for (int i = 0; i < result.length; i++) {
      result[i] = positions.get(i);
    }
    return result;
  }

  /** Forgets every varplayer's baseline. Called on an account switch, so one account's
   *  diary is never diffed against another's. */
  public void reset() {
    lastKnown.clear();
  }

  /** Restores values read back from disk, replacing whatever is currently held. */
  public void restore(Map<Integer, Integer> stored) {
    lastKnown.clear();
    lastKnown.putAll(stored);
  }

  /** For persisting. */
  public Map<Integer, Integer> snapshot() {
    return new LinkedHashMap<>(lastKnown);
  }
}

package com.bankstand;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Detects pet drops with the prime-then-resolve pattern. Non-obvious
 * enough to be worth copying rather than re-deriving: the game's first message
 * never contains the pet's name.
 *
 * <ol>
 *   <li>Match the "funny feeling like you are being followed" /
 *       "something weird sneaking into your backpack" family and prime.
 *   <li>Resolve the name from the NEXT game message only, via the
 *       untradeable-drop line or the collection-log line. One-shot: whatever
 *       that next message is, primed state is consumed by it, matching or not.
 *   <li>Validate against a known pet-name set, cross-checkable against the
 *       collection log since pets appear there too.
 * </ol>
 *
 * <p>A primed message with no following drop line emits nothing, and a
 * non-pet untradeable is ignored: both fall out of requiring the resolved
 * name to be in {@link #KNOWN_PETS} before emitting anything.
 *
 * <p><b>{@link #KNOWN_PETS} is a starting set, not a claimed-complete one.</b>
 * OSRS has added pets steadily since release; this list is the well-known
 * boss and skilling pets as of the tier this plugin targets, and is meant to
 * be extended, not treated as exhaustive.
 */
public class PetDropCapture extends BaseCapture {

  private static final Pattern PRIME_PATTERN =
      Pattern.compile(
          "^(You have a funny feeling like you're being followed\\.|"
              + "You feel something weird sneaking into your backpack\\.)$");
  private static final Pattern COLLECTION_LOG_PATTERN =
      Pattern.compile("^New item added to your collection log: (.+)$");
  private static final Pattern UNTRADEABLE_DROP_PATTERN =
      Pattern.compile("^Untradeable drop: (.+)$");

  // Case-insensitive: several entries below were typed in a casing that does not
  // match the game's own broadcast lines (TzRek-Jad, Baby Mole, Giant Squirrel and
  // every "Pet <Boss>" pet all use title case in the actual chat/collection-log
  // text), so a plain case-sensitive Set silently dropped every one of them. The
  // resolved name still comes from the message itself (see resolvePetName), so this
  // only relaxes the membership check, never what gets emitted.
  static final Set<String> KNOWN_PETS = knownPets();

  private static Set<String> knownPets() {
    Set<String> pets = new TreeSet<>(String.CASE_INSENSITIVE_ORDER);
    pets.addAll(
        java.util.Arrays.asList(
              "Baby mole",
              "Prince black dragon",
              "Callisto cub",
              "Venenatis spiderling",
              "Vet'ion jr.",
              "Scorpia's offspring",
              "Vorki",
              "Hellpuppy",
              "Baby Kraken",
              "Ikkle Hydra",
              "Chompy chick",
              "Abyssal orphan",
              "Herbi",
              "Skotos",
              "Tzrek-jad",
              "TzRek-Xil",
              "Jal-nib-rek",
              "Nexling",
              "Muphin",
              "Bloodhound",
              "Rift guardian",
              "Rocky",
              "Beaver",
              "Giant squirrel",
              "Heron",
              "Rock golem",
              "Tangleroot",
              "Sraracha",
              "Smolcano",
              "Youngllef",
              "Pet dagannoth prime",
              "Pet dagannoth rex",
              "Pet dagannoth supreme",
              "Pet chaos elemental",
              "Pet kraken",
              "Baby Zilyana",
              "Bran",
              "Butch",
              "Lil' Zik",
              "Little nightmare",
              "Kalphite princess",
              "Olmlet",
              "Nid",
              "Noon",
              "Huberte",
              "Lil'viathan",
              "Smolder",
              "Wisp",
              "Abyssal protector",
              "Pet smoke devil",
              "Pet snakeling"));
    return pets;
  }

  private boolean primed;

  public PetDropCapture(EventOutbox outbox, BooleanSupplier enabled, LongSupplier accountHash) {
    super(outbox, enabled, accountHash);
  }

  public PetDropCapture(
      EventOutbox outbox,
      BooleanSupplier enabled,
      LongSupplier accountHash,
      Consumer<TransientEvent> onEmit) {
    super(outbox, enabled, accountHash, onEmit);
  }

  @Subscribe
  public void onChatMessage(ChatMessage event) {
    if (event.getType() != ChatMessageType.GAMEMESSAGE) {
      return;
    }
    handleMessage(Text.removeTags(event.getMessage()));
  }

  /** Package-private, not private: {@code PetDropCaptureTest} calls this directly
   *  with plain strings, to avoid constructing a live {@code ChatMessage}.
   *
   * <p>Unlike {@code NotableDropCapture}, the toggle gates only the derive-and-emit
   * step here, not the prime/consume tracking above it. The one-shot consumption
   * MUST run regardless of the toggle: if it did not, disabling the capability
   * between a prime and its resolve message would leave {@link #primed} stuck true
   * with nothing to ever clear it, and a later, unrelated message after
   * re-enabling could wrongly resolve that stale prime, which is exactly the bug
   * the one-shot design exists to prevent. */
  void handleMessage(String message) {
    if (isPrimeMessage(message)) {
      primed = true;
      return;
    }
    if (!primed) {
      return;
    }
    // One-shot: consumed by this message whether or not it resolves anything,
    // so a stray later message can never wrongly resolve a stale prime.
    primed = false;
    if (!isEnabled()) return;
    String name = resolvePetName(message);
    if (name == null) {
      return;
    }
    emit(TransientEvent.TYPE_PET_DROP, payload(name));
  }

  static boolean isPrimeMessage(String message) {
    return PRIME_PATTERN.matcher(message).matches();
  }

  /** Null when the message is not a recognised resolve line, or names something not
   *  in {@link #KNOWN_PETS}: both are "nothing to emit", never an error. */
  static String resolvePetName(String message) {
    String fromLog = matchGroup(COLLECTION_LOG_PATTERN, message);
    if (fromLog != null && KNOWN_PETS.contains(fromLog)) {
      return fromLog;
    }
    String fromDrop = matchGroup(UNTRADEABLE_DROP_PATTERN, message);
    if (fromDrop != null && KNOWN_PETS.contains(fromDrop)) {
      return fromDrop;
    }
    return null;
  }

  private static String matchGroup(Pattern pattern, String message) {
    Matcher matcher = pattern.matcher(message);
    return matcher.matches() ? matcher.group(1) : null;
  }

  static Map<String, Object> payload(String petName) {
    Map<String, Object> payload = new LinkedHashMap<>();
    payload.put("petName", petName);
    // Neither resolve line names an NPC: the collection-log broadcast and the
    // untradeable-drop line both carry only the item, never its source.
    payload.put("source", null);
    return payload;
  }
}

package com.bankstand;

import java.util.LinkedHashSet;
import java.util.Set;

/**
 * The guided collection log read: what the plugin knows about a sync the player started,
 * and when that read is over.
 *
 * <p>The plugin cannot make the log enumerate itself. Driving the game's own Search
 * needs {@code client.menuAction}, which the Plugin Hub rejects, so the player clicks
 * Search and the plugin watches. Nothing here triggers anything; every method is fed by
 * an event the client raised on its own.
 *
 * <p>Item script {@code 4100} fires for every entry whoever ran the Search, and it also
 * fires while a player simply browses a page. Those two cases have to be told apart or
 * a stroll through one boss tab would report itself as a whole-log sync. So an item only
 * counts toward a read once the player has armed one, and a read only claims to be
 * complete when the search interface was seen open while entries were streaming.
 *
 * <p>That last signal is a widget read, and a widget read cannot be verified outside a
 * running client. The rule is therefore written to fail toward {@code PARTIAL}: an
 * unseen search downgrades an otherwise clean read rather than a missed signal
 * promoting a half-read log to complete. Under-claiming costs the player one more
 * click; over-claiming stores a log that silently is not the whole log.
 *
 * <p>Pure and deterministic: no client, no clock, no scheduling. The plugin passes the
 * two facts it reads per tick and gets back the outcome, if the read just ended.
 * Single-threaded by construction, like the rest of the session state, and touched only
 * from the client thread.
 */
public class CollectionLogSync {

  /**
   * Ticks without a new entry before a read counts as over. The game streams the whole
   * log in a burst, so any real gap means the burst finished; a few ticks of slack
   * absorbs a stagger without making the player wait for a timeout.
   */
  public static final int QUIET_TICKS = 5;

  /**
   * Ticks an armed sync waits for a Search that never comes, about two minutes. Without
   * it, a player who opens the menu and changes their mind leaves the infobox up until
   * they close the log.
   */
  public static final int ARM_TIMEOUT_TICKS = 200;

  /** How a read ended, and how much of the log it saw. */
  public enum Outcome {
    /** Entries streamed while the search was open, and the stream ended on its own. */
    COMPLETE,
    /** The read was cut short, or ran without the search ever being seen. */
    PARTIAL;

    private int observed;

    /** Distinct entries seen during the read this outcome describes. */
    public int getObserved() {
      return observed;
    }

    private Outcome with(int count) {
      this.observed = count;
      return this;
    }
  }

  private enum State {
    IDLE,
    AWAITING_SEARCH,
    READING
  }

  private State state = State.IDLE;
  private final Set<Integer> observed = new LinkedHashSet<>();
  private int quietTicks;
  private int armedTicks;
  private boolean sawSearch;

  /** Starts a guided read. Arming again abandons whatever the last one had seen. */
  public void arm() {
    state = State.AWAITING_SEARCH;
    observed.clear();
    quietTicks = 0;
    armedTicks = 0;
    sawSearch = false;
  }

  /**
   * Records one entry the client reported.
   *
   * <p><b>A search starts a read on its own.</b> Arming was never a gate on capture,
   * only on reporting, so requiring it made the player click twice before the one click
   * that actually does the work. WikiSync gets away with a single button because it
   * drives the Search with {@code client.menuAction}; the Hub does not allow us that, so
   * the fewest possible actions is the player clicking the game's own Search, and that
   * is now the whole flow. The menu entry stays as a hint for anyone who does not know.
   *
   * <p>Entries arriving with the search closed are ordinary page browsing. They still
   * reach the accumulator, but they must not start or extend a read, or turning one page
   * would report itself as a whole-log sync.
   *
   * <p>Counted by distinct id, not by event. A real enumeration fires the script twice
   * per entry on the first read of a session, so counting events reported "Synced 422
   * entries" for a log holding 211.
   */
  public void onItemObserved(int itemId, boolean searchOpen) {
    if (state == State.IDLE) {
      if (!searchOpen) {
        return;
      }
      sawSearch = true;
    }
    state = State.READING;
    // Canonical, so the running count is slots filled rather than ids seen. The
    // accumulator keeps the raw id; this set only ever feeds a number on screen.
    observed.add(VariantIds.canonical(itemId));
    quietTicks = 0;
  }

  /**
   * Advances the read by one tick.
   *
   * @param searchOpen whether the log's own search interface is on screen
   * @param logOpen whether the collection log is still on screen at all
   * @return the outcome when this tick ended the read, otherwise null. A read that ends
   *     with nothing to report (armed, never acted on) returns null and simply stops.
   */
  public Outcome onTick(boolean searchOpen, boolean logOpen) {
    if (state == State.IDLE) {
      return null;
    }
    if (searchOpen) {
      sawSearch = true;
    }
    // Closing the log ends the read either way. Mid-stream that is an interruption worth
    // reporting; before any entry arrived there is nothing to report at all.
    if (!logOpen) {
      boolean reading = state == State.READING;
      Outcome outcome = reading ? Outcome.PARTIAL.with(observed.size()) : null;
      finish();
      return outcome;
    }
    if (state == State.AWAITING_SEARCH) {
      armedTicks++;
      if (armedTicks >= ARM_TIMEOUT_TICKS) {
        finish();
      }
      return null;
    }
    quietTicks++;
    if (quietTicks < QUIET_TICKS) {
      return null;
    }
    Outcome outcome = (sawSearch ? Outcome.COMPLETE : Outcome.PARTIAL).with(observed.size());
    finish();
    return outcome;
  }

  /** True while a read is armed or streaming. */
  public boolean isActive() {
    return state != State.IDLE;
  }

  /** True while waiting for the player to run the Search. */
  public boolean isAwaitingSearch() {
    return state == State.AWAITING_SEARCH;
  }

  /** Distinct entries seen so far in the current read. */
  public int observedCount() {
    return observed.size();
  }

  /**
   * Abandons anything in flight. A read belongs to the character that started it, so a
   * logout or an account switch drops it rather than carrying it across.
   */
  public void reset() {
    finish();
  }

  private void finish() {
    state = State.IDLE;
    observed.clear();
    quietTicks = 0;
    armedTicks = 0;
    sawSearch = false;
  }
}

package com.bankstand;

/**
 * Pure, client-free formatting for {@link BankstandPanel}: what color a status dot
 * resolves to, and how a millisecond age reads as a short relative time. Split out so
 * both are testable without a live client or a display, the same reasoning {@link
 * StatusReport} already uses to keep its own wording testable.
 */
final class PanelPresentation {

  private PanelPresentation() {}

  /** The header's one status dot. Named by color rather than by meaning, because color
   *  is the only thing {@link BankstandPanel} actually renders from it. */
  enum SyncDot {
    GREEN,
    AMBER,
    GREY
  }

  /**
   * @param paired whether a device token is stored
   * @param everSucceeded whether a submit has landed at least once this session
   * @param lastAttemptFailed whether the most recent submit attempt failed
   */
  static SyncDot resolveDot(boolean paired, boolean everSucceeded, boolean lastAttemptFailed) {
    if (!paired) {
      return SyncDot.GREY;
    }
    if (lastAttemptFailed) {
      return SyncDot.AMBER;
    }
    // Paired, no failure on record, but also nothing has actually landed yet (a fresh
    // pairing, or a session with capture still off): neither claim ("succeeded",
    // "failed") is true, so this reads as unknown rather than a false green.
    return everSucceeded ? SyncDot.GREEN : SyncDot.GREY;
  }

  /**
   * A short age like "just now", "2m ago", "3h ago", "5d ago". Coarser than {@code
   * BankstandPlugin#describeAge}'s chat wording on purpose: a capability row here is a
   * few dozen pixels wide, not a sentence in a chat window.
   */
  static String formatAge(long ageMillis) {
    if (ageMillis < 60_000L) {
      return "just now";
    }
    long minutes = ageMillis / 60_000L;
    if (minutes < 60) {
      return minutes + "m ago";
    }
    long hours = minutes / 60;
    if (hours < 24) {
      return hours + "h ago";
    }
    long days = hours / 24;
    return days + "d ago";
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Varbits;

/**
 * Maps each combat achievement tier's wire key to the varbit holding how many of that
 * tier's tasks are done.
 *
 * <p><b>Counts, not task ids.</b> RuneLite exposes {@code COMBAT_TASK_*}, a completed
 * count per tier, and nothing at all per task; Jagex publishes neither. So a count is
 * the honest limit of what can be observed here, and the server is written to treat it
 * as exactly that: a tier reading 23/41 says nothing about <i>which</i> 23, and the
 * per-task grid on the website keeps its placeholders even with this populated.
 *
 * <p>Do not be tempted by {@code COMBAT_ACHIEVEMENT_TIER_*}, which sit beside these.
 * Those track whether the tier's <i>rewards</i> have been claimed from the taskmaster,
 * which is a different fact: a player can finish every Easy task and never claim, and
 * reading those would report them at zero. Same trap as the diary table's
 * {@code *_REWARD} flags, called out there for the same reason.
 *
 * <p>Wire keys are lowercase to match the server's {@code CA_TIER_KEYS}, which come
 * from Bankstand's own tier ids rather than from the RuneLite constant names.
 *
 * <p>A plain data table with no {@code Client} dependency, so it is unit-testable
 * without a live game client.
 */
public final class CombatAchievementVarbits {
  private CombatAchievementVarbits() {}

  /** Ordered, unmodifiable: wire key (server's contract) to varbit id. */
  public static final Map<String, Integer> ALL = Collections.unmodifiableMap(build());

  private static Map<String, Integer> build() {
    Map<String, Integer> m = new LinkedHashMap<>();
    m.put("easy", Varbits.COMBAT_TASK_EASY);
    m.put("medium", Varbits.COMBAT_TASK_MEDIUM);
    m.put("hard", Varbits.COMBAT_TASK_HARD);
    m.put("elite", Varbits.COMBAT_TASK_ELITE);
    m.put("master", Varbits.COMBAT_TASK_MASTER);
    m.put("grandmaster", Varbits.COMBAT_TASK_GRANDMASTER);
    return m;
  }
}

package com.bankstand;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Resolves the diary task broadcast's own area text ("...completed an elite task in the
 * Western Provinces area...") to the wire region key {@link DiaryVarbits}/
 * {@link DiaryTaskVarbits}/{@link DiaryTaskVarplayers} use.
 *
 * <p>Nine of twelve match wording {@code DiaryTaskCompletionCapture}'s own tests already
 * confirm as real chat text. {@code KOUREND_KEBOS} is not confirmed, guessed by analogy to
 * the other two ampersand-joined names. Not yet checked against a live broadcast.
 *
 * <p>A miss (unrecognised text, including a wrong Kourend &amp; Kebos guess) just falls
 * through to the plain tier/area event, same as before this table existed.
 */
public final class DiaryTaskRegions {
  private DiaryTaskRegions() {}

  private static final Map<String, String> BY_AREA_TEXT = build();

  private static Map<String, String> build() {
    Map<String, String> m = new LinkedHashMap<>();
    m.put("Ardougne", "ARDOUGNE");
    m.put("Desert", "DESERT");
    m.put("Falador", "FALADOR");
    m.put("Fremennik", "FREMENNIK");
    m.put("Kandarin", "KANDARIN");
    // Not independently corroborated; see the class javadoc.
    m.put("Kourend & Kebos", "KOUREND_KEBOS");
    m.put("Lumbridge & Draynor", "LUMBRIDGE_DRAYNOR");
    m.put("Morytania", "MORYTANIA");
    m.put("Varrock", "VARROCK");
    m.put("Western Provinces", "WESTERN_PROVINCES");
    m.put("Wilderness", "WILDERNESS");
    m.put("Karamja", "KARAMJA");
    return Collections.unmodifiableMap(m);
  }

  /** The wire region key for this area text, or null when it matches none of the twelve. */
  public static String forAreaText(String areaText) {
    return BY_AREA_TEXT.get(areaText);
  }
}
